INSERT INTO `pages` VALUES
('0df104a2-b895-4d6d-a65a-ba9390736dd5','participants','{\"page_title\":\"Лучшие экстрасенсы России\",\"page_subtitle\":\"Сильнейшие экстрасенсы, медиумы, ясновидящие, маги и целители\"}','2026-03-06 17:33:19'),
('183e1ca1-6925-4bea-8e93-454a853935fe','topic-venets-bezbrachiya','{\"title\": \"Венец безбрачия\", \"description\": \"Венец безбрачия — это энергетическая блокировка, которая препятствует созданию семьи.\", \"symptoms_title\": \"Признаки венца безбрачия\", \"symptoms\": \"Отношения заканчиваются одинаково\\nНет серьёзных отношений после 30\\nСвадьбы отменяются\\nПривлекаете неподходящих партнёров\", \"when_title\": \"Когда нужна помощь\", \"when_to_contact\": \"Если личная жизнь не складывается годами\\nЕсли в роду есть одинокие люди\", \"consultation_title\": \"Работа с венцом безбрачия\", \"consultation_process\": \"Диагностика\\nОпределение причины\\nСнятие блокировки\\nВосстановление способности любить\", \"cta_title\": \"Готовы к переменам?\", \"cta_text\": \"Запишитесь на консультацию.\", \"cta_button\": \"Снять венец безбрачия\", \"additional_title\": \"Снятие венца безбрачия: путь к встрече со своим человеком\", \"additional_text\": \"Венец безбрачия — особая магическая программа, которая блокирует возможность создать крепкую семью. Внешне жизнь может казаться вполне успешной: интересная работа, друзья, отдельные отношения. Но каждый раз, когда дело подходит к чему-то серьёзному, события разворачиваются против человека. Партнёры исчезают, свадьбы срываются, браки распадаются спустя несколько лет. Это не «такая судьба» и не «не повезло с характером» — за подобными повторами почти всегда стоит конкретная программа, которую нужно снимать.\\n\\nВ проектах «битва экстрасенсов» и «экстрасенсы битва сильнейших» неоднократно показывали, насколько разнообразными могут быть формы венца безбрачия: родовой (когда «не выходят замуж» женщины целого рода), наведённый завистливыми «доброжелателями», обетный (когда сам человек когда-то неосознанно «зарекался»). Каждый случай требует индивидуального подхода. Опытная ясновидящая по фотографии или короткой беседе уже видит наличие программы, а потомственная ведьма подбирает обряд снятия, который сработает именно для вашей ситуации.\\n\\nПриём экстрасенса по вопросу венца безбрачия обычно проходит в спокойной, доверительной атмосфере. Сначала специалист задаёт уточняющие вопросы: как складывались предыдущие отношения, что повторяется, есть ли подобные сценарии в роду. Затем проводится диагностика и согласовывается план работы. Обряды снятия часто сопровождаются обрядами на встречу с подходящим партнёром, чтобы освободившийся канал не пустовал, а сразу наполнился правильной энергией.\\n\\nЕсли вам кажется, что вы «как заколдован» в личной жизни — постоянно встречаете не тех, не можете удержать достойного человека, или вокруг рушатся уже состоявшиеся пары — это серьёзный повод обратиться за помощью. Запись на консультацию ни к чему не обязывает, но позволяет увидеть честную картину и понять, что делать дальше. Снятый венец безбрачия — это не «гарантия штампа», а возвращённая возможность строить отношения свободно, без невидимых барьеров и повторяющихся сценариев.\\n\\nПосле снятия венца события обычно начинают разворачиваться не мгновенно, а постепенно: ослабевают старые «застрявшие» связи, отпадают неподходящие партнёры, появляются новые знакомства — часто в неожиданных местах и обстоятельствах. Важно дать процессу время и не пытаться форсировать встречу искусственно. Специалист даёт практические рекомендации: какие места посещать, как работать со своим женским или мужским образом, что менять во внешнем виде и привычках. Такой комплексный подход помогает не просто «снять программу», а перестроить всю личную сферу под здоровый, долговременный союз.\"}','2026-03-06 17:33:19'),
('2a7afb21-2561-490b-a926-f416c2c01f72','faq','{\"page_title\":\"Частые вопросы\",\"page_subtitle\":\"Ответы на самые популярные вопросы\"}','2026-03-06 17:33:19'),
('3c62cb2f-2e51-4212-8da3-74b334c35944','topic-zaklyatie','{\"title\": \"Заклятие\", \"description\": \"Заклятие — это мощное магическое воздействие, закрепляющее программу в судьбе человека.\", \"symptoms_title\": \"Признаки заклятия\", \"symptoms\": \"Хроническая неудача\\nПовторяющиеся негативные сценарии\\nОщущение «замкнутого круга»\\nБлокировка возможностей\", \"when_title\": \"Когда нужна помощь\", \"when_to_contact\": \"Если проблемы не решаются годами\\nЕсли жизнь остановилась\", \"consultation_title\": \"Работа с заклятием\", \"consultation_process\": \"Глубокая диагностика\\nОпределение типа\\nПоэтапная работа по снятию\\nЗакрепление результата\", \"cta_title\": \"Чувствуете блокировку?\", \"cta_text\": \"Запишитесь на консультацию.\", \"cta_button\": \"Снять заклятие\", \"additional_title\": \"Снятие заклятия: освобождение от чужих программ и обетов\", \"additional_text\": \"Заклятие — особый вид магического воздействия, при котором на человека или его жизнь накладывается конкретная программа: «не быть богатым», «не быть счастливым в любви», «болеть», «не выходить из круга». В отличие от порчи, заклятие почти всегда формулируется словами — иногда самим человеком в момент сильной эмоции, иногда близким родственником, иногда посторонним «в сердцах». И то, что было сказано в особом состоянии, может работать годами.\\n\\nПрограмма «битва экстрасенсов» в разные сезоны не раз показывала случаи, когда люди годами жили с чужими словами как с приговором — пока сильный специалист не снимал эту программу буквально за один-два сеанса. Профессиональный маг знает, как работать с речевыми конструкциями в тонком мире, как разрывать привязанность к словесной форме и возвращать человеку свободу. Точная диагностика — основа этой работы.\\n\\nКачественная помощь экстрасенса при заклятии всегда начинается с поиска источника. Опытная ясновидящая помогает вспомнить, когда впервые проявилась проблема, что было сказано вокруг, какие фразы повторялись в детстве («ты ничего не добьёшься», «всё у тебя в роду так», «ты как отец»). Иногда оказывается, что заклятие — это давнее проклятие бабушки, давно забытое самим клиентом. Иногда — слова бывшего супруга в момент скандала. Иногда — собственный неосторожный обет.\\n\\nКаждый случай уникален, поэтому шаблонных решений не существует. Снятие может включать сжигание словесного образа, перепрошивку родовой памяти, возврат программы источнику, постановку защиты. Если вы давно живёте с ощущением «как будто кто-то сказал — и закрыло», запишитесь на консультацию. Часто одной грамотной сессии достаточно, чтобы заклятие потеряло силу, а жизнь снова стала пластичной и открытой к лучшему.\\n\\nОтдельное внимание после снятия заклятия специалист уделяет работе с собственной речью клиента. Многие фразы, которые мы повторяем годами в адрес себя или близких («у меня никогда не получится», «вечно мне не везёт», «лучше бы я не родился»), сами по себе формируют новые программы. Мастер показывает, как заменить эти автоматические клише на нейтральные или поддерживающие конструкции, как обращаться со словами в моменты сильных эмоций. Эта внутренняя гигиена речи — лучшая профилактика того, чтобы старые программы не вернулись и не появились новые.\"}','2026-03-06 17:33:19'),
('431893f3-8106-4b72-a24c-9536f4c04fea','service-lyubovnaya-magiya','{\"title\": \"Любовная магия\", \"description\": \"Любовная магия — это одно из древнейших направлений, помогающее людям обрести счастье в личной жизни.\", \"directions_title\": \"Направления\", \"directions\": \"Возврат любимого\\nУкрепление семейных уз\\nПривлечение партнёра\\nОбряды на красоту\\nРитуалы на гармонию\\nСнятие венца безбрачия\", \"situations_title\": \"Когда стоит обратиться\", \"situations\": \"Партнёр ушёл\\nОтношения разрушаются\\nНе удаётся встретить партнёра\\nОхлаждение чувств\", \"how_it_works_title\": \"Как проходит работа\", \"how_it_works\": \"Беседа\\nДиагностика отношений\\nВыявление причин\\nРазработка стратегии\\nПроведение ритуалов\\nРекомендации\", \"results_title\": \"Что вы получите\", \"results\": \"Восстановление чувств\\nГармонизацию отношений\\nЗащиту отношений\\nПомощь в привлечении партнёра\", \"cta_title\": \"Хотите наладить личную жизнь?\", \"cta_text\": \"Запишитесь на консультацию.\", \"cta_button\": \"Получить консультацию\", \"additional_title\": \"Любовная магия: как вернуть гармонию в отношения\", \"additional_text\": \"Любовь — самая тонкая и уязвимая сфера человеческой жизни. Здесь сплетаются чувства, судьбы, родовые программы и порой намеренные негативные воздействия со стороны. Когда отношения, ещё вчера казавшиеся крепкими, вдруг рассыпаются на глазах, а одиночество затягивается на годы вопреки всем усилиям, это редко бывает случайностью. Это всегда повод задуматься и обратиться за грамотной помощью.\\n\\nНа официальном сайте «битва экстрасенсов» собраны специалисты с проверенным опытом, среди которых есть как практикующие маги, так и потомственные ведуньи. Каждая ведьма, работающая в команде проекта, проходит долгий путь обучения и умеет аккуратно настраивать тонкие связи между людьми. Это не «приворот любой ценой», а бережная и этичная работа: восстановление искренних чувств, снятие наведённого охлаждения, очищение пары от чужого влияния, гармонизация семейного эгрегора.\\n\\nКачественная помощь экстрасенса в любовных вопросах всегда начинается с честного разговора. Специалист задаёт уточняющие вопросы, проводит диагностику обоих партнёров (если речь о паре), смотрит причины — будь то остывание из-за усталости, последствия чужой ревности или влияние прошлых связей. Только после этого подбираются методы работы: ритуалы на возврат любви, обряды снятия одиночества, программы на встречу со своим человеком.\\n\\nПриём экстрасенса проводится в максимально комфортном для клиента формате — лично, по телефону или онлайн, с полным сохранением конфиденциальности. Никто не узнает о вашем обращении, а сам процесс выстроен так, чтобы вы чувствовали поддержку на каждом этапе. Если ваше сердце устало бороться в одиночку, а попытки «всё исправить самостоятельно» не приносят результата, доверьтесь специалисту. Запись на консультацию — это не слабость, а зрелое решение позаботиться о своём счастье и будущем.\\n\\nОчень важно понимать: грамотная работа в сфере любви — это всегда вопрос этики. Опытный специалист никогда не возьмётся за работу, которая грубо нарушает свободную волю другого человека или может навредить ребёнку в паре. Если ваш партнёр действительно ваш по судьбе, тонкая работа лишь поможет снять преграды и услышать друг друга заново. Если же связь была изначально чужой — мастер честно скажет об этом и предложит другой путь: освобождение, исцеление и встречу с тем, кто предназначен именно вам.\"}','2026-03-06 17:33:19'),
('5b34589e-f575-4d14-a0dd-e7538f194e60','topic-porcha','{\"title\": \"Порча\", \"description\": \"Порча — это целенаправленное негативное воздействие на человека, которое может затрагивать различные сферы его жизни.\\n\\nЕё последствия могут быть серьёзными и затяжными, если вовремя не обратиться за помощью.\", \"symptoms_title\": \"Признаки наличия порчи\", \"symptoms\": \"Резкое ухудшение здоровья без видимых причин\\nПостоянные неудачи в делах\\nРазлад в семье\\nФинансовые проблемы\\nАпатия, депрессия\\nНочные кошмары, бессонница\", \"when_title\": \"Когда стоит обратиться\", \"when_to_contact\": \"Если несколько признаков проявляются одновременно\\nЕсли негатив начался после конфликта\\nЕсли врачи не могут найти причину\", \"consultation_title\": \"Как проходит диагностика\", \"consultation_process\": \"Предварительная беседа\\nДиагностика\\nОпределение типа воздействия\\nСоставление программы помощи\\nПроведение обрядов\\nРекомендации по защите\", \"cta_title\": \"Нужна диагностика?\", \"cta_text\": \"Запишитесь на консультацию.\", \"cta_button\": \"Снять порчу\", \"additional_title\": \"Снятие порчи: как распознать и устранить негативное воздействие\", \"additional_text\": \"Порча — одно из самых тяжёлых негативных воздействий, с которыми сталкивается человек. В отличие от случайного сглаза, она наводится намеренно и нередко передаётся через бытовые предметы, фотографии или прямой контакт. Последствия могут быть крайне разрушительны: внезапные болезни без диагноза, череда финансовых неудач, разрыв отношений, постоянное чувство тревоги, навязчивые мысли. Чем дольше порча остаётся неснятой, тем глубже она прорастает в судьбу.\\n\\nПроект «битва экстрасенсов» неоднократно показывал, насколько разрушительной может быть энергетическая атака — и как профессионально с ней работают сильные специалисты. Опытная ведьма с потомственным даром способна точно определить тип воздействия: бытовая порча, кладбищенская, на смерть, на разрыв, наведённая через подклад. От правильного определения зависит весь дальнейший план работы — универсальных «таблеток» здесь не бывает.\\n\\nГрамотная помощь экстрасенса в случае порчи всегда состоит из нескольких обязательных шагов. Сначала проводится диагностика — на свечу, воду, карты или иные проверенные инструменты. Опытный медиум видит не только сам факт воздействия, но и канал, по которому оно поступило, силу, давность, источник. Затем выполняется снятие: специалист разрывает связь с заказчиком и исполнителем, очищает ауру, возвращает энергии в нейтральное русло. После — обязательная защита, чтобы новая атака не вернулась.\\n\\nЕсли вы заметили у себя или близкого человека сразу несколько тревожных признаков (резкое ухудшение здоровья, постоянные ссоры, потеря желания жить, навязчивые сны), не стоит ждать «само пройдёт». Самостоятельные ритуалы из интернета без точной диагностики чаще усугубляют ситуацию, чем помогают. Запишитесь на консультацию к проверенному специалисту: профессиональное снятие порчи возвращает человеку здоровье, чувство опоры и спокойствия — а главное, восстанавливает естественный ход событий в его жизни.\\n\\nПосле снятия порчи начинается важный этап восстановления. В первые дни возможна повышенная утомляемость, эмоциональные «откаты», необычные сны — это естественная реакция тела и психики на освобождение. Специалист сопровождает клиента и в этот период: даёт рекомендации по питанию, сну, общению, простым очищающим практикам. Постепенно возвращаются силы, нормализуется самочувствие, налаживаются дела. Параллельно ставится индивидуальная защита, чтобы повторная атака стала невозможной. В результате человек получает не просто «лекарство от симптома», а долговременную устойчивость и душевный покой.\"}','2026-03-06 17:33:19'),
('636833b3-84cf-4209-ad43-38078164ee6d','home','{\"hero_h1\": \"Битва экстрасенсов — официальный сайт помощи сильнейших экстрасенсов, ясновидящих, магов и целителей России\", \"hero_subtitle\": \"Официальный портал магической помощи от участников проекта «Битва экстрасенсов»\", \"hero_logo_bitva_url\": \"/api/uploads/logo-bitva.png\", \"hero_logo_bitva_alt\": \"Битва экстрасенсов\", \"hero_logo_bitva_height_desktop\": 64, \"hero_logo_bitva_height_mobile\": 48, \"hero_logo_tnt_url\": \"/api/uploads/logo-tnt.png\", \"hero_logo_tnt_alt\": \"ТНТ\", \"hero_logo_tnt_height_desktop\": 64, \"hero_logo_tnt_height_mobile\": 48, \"hero_unique\": \"Уникальная возможность получить реальную помощь!\", \"hero_text1\": \"Обратитесь лично к любому участнику легендарного проекта «Битва экстрасенсов» — победителям, финалистам и сильнейшим экстрасенсам, чьи способности были доказаны перед миллионами зрителей.\", \"hero_text2\": \"Получите персональную диагностику негатива, консультацию ясновидящей, помощь мага или медиума — онлайн или на личном приёме.\", \"hero_subheading\": \"магическая помощь и консультация экстрасенса — запись на приём\", \"about_text\": \"Здесь собраны сильнейшие экстрасенсы России — победители и финалисты проекта «Битва экстрасенсов» и «Экстрасенсы: Битва сильнейших». Каждый из них прошёл жёсткий отбор и доказал свои способности на глазах у миллионов зрителей. В нашей команде — потомственные ведьмы, ясновидящие, медиумы и маги, которые ежедневно помогают людям в самых сложных жизненных ситуациях: снятие порчи и сглаза, помощь в отношениях и личной жизни, снятие проклятий, магическая защита, финансовая магия и диагностика негатива. Не оставайтесь наедине со своей проблемой — доверьтесь тем, чья сила проверена и подтверждена.\", \"cta_text\": \"Количество заявок на помощь ограничено!\", \"cta_button\": \"Получить помощь экстрасенса!\", \"cta_subtext\": \"Не упустите свой шанс!\", \"participants_title\": \"Лучшие экстрасенсы России\", \"benefits_title\": \"Почему выбирают нас\", \"services_title\": \"Услуги экстрасенсов\", \"service_cat_1\": \"Финансовая магия\\nЖелаемая профессия\\nУвеличение заработка\\nПриумножение финансовых ресурсов\\nОткрытие денежного потока\\nСнятие блоков с финансовых потоков\", \"service_cat_2\": \"Любовная магия\\nВозврат любимого человека\\nУкрепление семейных уз\\nПривлечение второй половины\\nОбряды на красоту и молодость\\nРитуалы на гармонию в отношениях\", \"service_cat_3\": \"Магия жизни\\nУлучшение качества жизни\\nИзбавление от зависимостей\\nСнятие блоков и негативных программ\\nВосстановление мужской и женской энергии\\nОбретение внутренней гармонии\", \"service_cat_4\": \"Магическая защита\\nАвторские защиты и обереги\\nРунические амулеты\\nРитуалы на защиту семьи\\nЗащита имущества и финансов\\nЗаговоры на удачу и благополучие\", \"reviews_title\": \"Отзывы\", \"form_title\": \"Запишитесь на консультацию\", \"form_subtitle\": \"Заполните форму и мы свяжемся с вами в ближайшее время\", \"seo_text_title\": \"Помощь экстрасенса онлайн и на личном приёме — официальный сайт «Битва экстрасенсов»\", \"seo_text\": \"Официальный сайт «Битва экстрасенсов» — это крупнейший портал магической помощи в России, где вы можете напрямую обратиться к участникам легендарного телешоу. Здесь работают победители и финалисты новой Битвы экстрасенсов, а также сезонов «Экстрасенсы: реванш» — сильные экстрасенсы, ясновидящие, потомственные ведьмы, медиумы, маги и колдуньи, чьи способности были проверены в самых сложных испытаниях.\\n\\nЕсли вам нужна помощь экстрасенса — вы попали по адресу. Наши специалисты проводят диагностику негатива, снятие порчи, сглаза и проклятий, выполняют ритуалы магической защиты, помогают с приворотом и возвратом любимых, оказывают помощь в личной жизни, отношениях и финансах.\\n\\nКонсультация экстрасенса доступна как онлайн, так и на личном приёме. Запись на приём к экстрасенсу осуществляется через удобную форму на сайте. Не откладывайте решение проблемы — помощь мага, помощь ведьмы или консультация ясновидящей могут изменить вашу жизнь уже сегодня.\\n\\nМы являемся официальным сайтом экстрасенсов проекта «Битва экстрасенсов» на ТНТ. Каждый участник портала — реальный практик с подтверждённым опытом и тысячами благодарных обращений. Экстрасенс онлайн — это доступно, безопасно и конфиденциально.\"}','2026-03-06 17:33:19'),
('80ed4f5a-89ef-4d39-9d48-406042ed9a5e','service-magiya-zhizni','{\"title\": \"Магия жизни\", \"description\": \"Магия жизни — это широкий спектр энергетических практик, направленных на улучшение качества жизни.\", \"directions_title\": \"Направления\", \"directions\": \"Улучшение качества жизни\\nИзбавление от зависимостей\\nСнятие блоков\\nВосстановление энергии\\nОбретение гармонии\\nКармическая работа\", \"situations_title\": \"Когда обращаются\", \"situations\": \"Ощущение тупика\\nХроническая усталость\\nЗависимости\\nПотеря мотивации\\nТревожность\", \"how_it_works_title\": \"Как проходит консультация\", \"how_it_works\": \"Беседа\\nДиагностика\\nВыявление причин\\nСоставление плана\\nЭнергетические практики\\nРекомендации\", \"results_title\": \"Что вы получите\", \"results\": \"Восстановление энергии\\nОсвобождение от блоков\\nПомощь с зависимостями\\nГармонизацию состояния\", \"cta_title\": \"Готовы к переменам?\", \"cta_text\": \"Запишитесь на консультацию.\", \"cta_button\": \"Получить консультацию\", \"additional_title\": \"Магия жизни: восстановление пути и личной судьбы\", \"additional_text\": \"Бывает так, что человек делает всё правильно — много работает, заботится о близких, старается жить честно, — а удача упорно обходит стороной. Желания не сбываются, важные двери захлопываются, здоровье даёт сбой без понятных причин. В такие моменты привычная логика бессильна, и стоит посмотреть на ситуацию глазами того, кто видит мир глубже. Именно эту задачу решает магия жизни — комплексное направление, объединяющее работу с судьбой, родом и личной энергетикой.\\n\\nТелешоу «битва экстрасенсов» давно стало для миллионов зрителей синонимом настоящего дара. С каждым новым сезоном — и особенно когда выходит новая битва экстрасенсов — проект открывает зрителям сильных специалистов, способных видеть незримое. Многие из участников, ставших известными благодаря шоу, продолжают практику и сегодня, помогая людям не на экране, а в реальной жизни. Их методы проверены десятилетиями и сотнями подтверждённых случаев.\\n\\nКонсультация экстрасенса в сфере магии жизни обычно затрагивает сразу несколько слоёв: родовые программы, кармические задачи, последствия неосознанных обетов, влияние внешних негативных воздействий. Опытная ясновидящая способна увидеть, в какой именно точке судьбы человек «застрял», и подсказать, как этот узел развязать. Иногда достаточно одной встречи, чтобы клиент по-новому увидел свою ситуацию и почувствовал лёгкость; в более сложных случаях работа выстраивается поэтапно.\\n\\nЕсли вам кажется, что жизнь идёт «не туда», что вы повторяете сценарии родителей или раз за разом наступаете на одни и те же грабли — это серьёзный повод обратиться за помощью. Не нужно мириться с ощущением «застрял и не двигаюсь». Запишитесь на консультацию: специалист поможет вернуть ясность, восстановить контакт с собственным предназначением и снова почувствовать радость от того, как складывается ваш путь.\\n\\nГлубокая работа с судьбой — это не «волшебная палочка», а процесс, в котором клиент остаётся активным участником. Специалист открывает дорогу, но идти по ней предстоит вам самим: принимать решения, делать выборы, отпускать то, что больше не нужно. Между сеансами мастер остаётся на связи, отвечает на возникающие вопросы и при необходимости корректирует работу. Такой формат сопровождения даёт устойчивый результат: изменения закрепляются не на месяц-два, а на годы вперёд, постепенно перестраивая всю канву жизни.\"}','2026-03-06 17:33:19'),
('8c1fc5eb-5c5f-447e-936b-f3a350b5a971','service-finansovaya-magiya','{\"title\": \"Финансовая магия\", \"description\": \"Финансовая магия — это комплекс энергетических практик, направленных на улучшение материального положения.\", \"directions_title\": \"Направления финансовой магии\", \"directions\": \"Привлечение желаемой профессии\\nУвеличение заработка\\nПриумножение финансовых ресурсов\\nОткрытие денежного потока\\nСнятие финансовых блоков\\nЗащита бизнеса\", \"situations_title\": \"Когда стоит обратиться\", \"situations\": \"Хронические финансовые трудности\\nПостоянная потеря денег\\nНевозможность найти работу\\nБизнес не приносит прибыли\\nДолги растут\", \"how_it_works_title\": \"Как проходит консультация\", \"how_it_works\": \"Анализ ситуации\\nДиагностика денежных потоков\\nВыявление блоков\\nСоставление плана\\nПроведение ритуалов\\nРекомендации\", \"results_title\": \"Что вы получите\", \"results\": \"Устранение энергетических блоков\\nАктивизацию денежного потока\\nЗащиту финансов\\nРекомендации по поддержанию достатка\", \"cta_title\": \"Хотите улучшить положение?\", \"cta_text\": \"Запишитесь на консультацию.\", \"cta_button\": \"Получить консультацию\", \"additional_title\": \"Финансовая магия: путь к достатку через работу с экстрасенсом\", \"additional_text\": \"Деньги — это не только экономика и расчёты, но и тонкая энергетическая структура, которая откликается на внутреннее состояние человека. Когда финансовый поток внезапно иссякает, привычные источники дохода теряют силу, а каждое начинание оборачивается убытком, причина нередко лежит вне материального мира. Опытный маг видит эти скрытые блокировки и помогает их снять, чтобы человек снова мог свободно строить свою жизнь.\\n\\nЗа годы практики наши специалисты, прошедшие проверку в проекте «битва экстрасенсов», накопили глубокое понимание законов, которые управляют денежным потоком. Они работают не с пустыми обещаниями, а с конкретной ситуацией клиента: анализируют родовые программы, последствия чужой зависти, негативные установки, мешающие принимать достаток. Такая помощь экстрасенса позволяет увидеть проблему целиком, а не лечить отдельные симптомы.\\n\\nГрамотная консультация экстрасенса в финансовых вопросах — это всегда диалог. Сначала специалист слушает: как давно начались трудности, при каких обстоятельствах, какие попытки уже предпринимались. Затем проводит диагностику и предлагает индивидуальный план работы. Это может быть очищение от негативных воздействий, гармонизация денежного канала, обряды на привлечение клиентов, удачу в делах и стабильный доход. Важно понимать: ритуалы не заменяют труд, они открывают пространство, в котором ваши усилия начинают приносить заслуженные плоды.\\n\\nЕсли вы давно ощущаете, что финансовый потолок не пробивается, что договорённости срываются буквально перед подписанием, а заработанное «уходит сквозь пальцы», это серьёзный сигнал. Не стоит откладывать встречу со специалистом: чем раньше начинается работа, тем мягче и быстрее проходят изменения. Запишитесь на консультацию — и сделайте первый шаг к финансовой устойчивости и спокойной уверенности в завтрашнем дне.\\n\\nРабота с финансовой энергией ведётся в удобном для вас формате — лично, по телефону или дистанционно по фотографии. Дистанционные сеансы по силе ничем не уступают очным: тонкий мир не знает географических границ. Все обращения остаются строго конфиденциальными, а после завершения работы специалист подробно объясняет, какие изменения и в какие сроки можно ожидать. Это честный, ответственный подход — без обещаний «миллион завтра», но с реальной поддержкой и заметными результатами в течение нескольких недель.\"}','2026-03-06 17:33:19'),
('9ffad22b-3244-4ae9-8378-1cc384d5565e','service-magicheskaya-zashchita','{\"title\": \"Магическая защита\", \"description\": \"Магическая защита — это система ритуалов, направленных на создание защитного поля.\", \"directions_title\": \"Направления\", \"directions\": \"Авторские защиты и обереги\\nРунические амулеты\\nРитуалы на защиту семьи\\nЗащита имущества и финансов\\nЗаговоры на удачу\\nЗащита бизнеса\", \"situations_title\": \"Когда нужна защита\", \"situations\": \"После снятия порчи\\nПри ощущении зависти\\nПеред важными событиями\\nДля защиты детей\\nПосле серии неудач\", \"how_it_works_title\": \"Как проводится защита\", \"how_it_works\": \"Диагностика состояния\\nВыявление уязвимостей\\nПодбор метода\\nСоздание оберегов\\nЗащитные ритуалы\\nРекомендации\", \"results_title\": \"Что вы получите\", \"results\": \"Защитный барьер\\nИндивидуальный оберег\\nЗащиту семьи и дома\\nРекомендации по профилактике\", \"cta_title\": \"Хотите защитить себя?\", \"cta_text\": \"Запишитесь на консультацию.\", \"cta_button\": \"Получить консультацию\", \"additional_title\": \"Магическая защита: щит для человека, дома и семьи\", \"additional_text\": \"Магическая защита — это не «модный амулет» и не модная практика, а серьёзная многоуровневая работа, благодаря которой человек становится неуязвим для большинства внешних негативных воздействий. Зависть коллег, недобрые взгляды соседей, родовые проклятия, оставшиеся в наследство, целенаправленные наговоры — всё это реально влияет на здоровье, отношения и финансы. Грамотно поставленная защита убирает основной канал, через который негатив проникает в жизнь.\\n\\nПрограмма «экстрасенсы битва сильнейших», где встречаются самые опытные специалисты, наглядно показывает: настоящий маг не размахивает руками для эффекта, а работает тихо, точно и с пониманием механики тонкого мира. Опытный медиум видит каналы воздействия, чувствует, кто и зачем направил негатив, и подбирает индивидуальный комплекс защитных мер. Это не шаблон «один обряд на всех», а персональное решение для конкретной ситуации.\\n\\nКомплексная помощь экстрасенса в вопросах защиты включает несколько обязательных этапов. Сначала проводится диагностика: что уже «висит» на человеке, есть ли активные программы, кто их источник. Затем выполняется чистка — снятие негативных слоёв, отработка последствий. И только после этого ставится постоянная защита: на ауру, дом, машину, бизнес, близких. Дополнительно специалист обучает простым повседневным практикам, которые помогают поддерживать щит самостоятельно.\\n\\nОсобенно важно ставить защиту тем, кто работает с людьми (врачи, педагоги, бизнесмены, артисты), часто появляется на публике, разводится или, наоборот, переживает яркий этап взлёта — именно в такие периоды поток чужого внимания максимален. Если вы чувствуете беспричинную усталость, нарастающее раздражение в семье, череду «непонятных» болезней или странных совпадений, не откладывайте. Запишитесь на консультацию — и верните своему пространству безопасность, тишину и силу.\\n\\nОтдельное внимание специалист уделяет профилактике: учит распознавать первые признаки чужого влияния, объясняет, какие простые ритуалы можно проводить самостоятельно, как использовать защитные обереги, соль, свечи и молитвы. Эти повседневные практики не заменяют профессиональную работу, но прекрасно её дополняют — особенно после плотного контакта с большим количеством людей, после конфликтов или возвращения из «тяжёлых» мест. Защита становится не разовой акцией, а здоровой привычкой, благодаря которой негатив перестаёт находить лазейки в вашу жизнь.\"}','2026-03-06 17:33:19'),
('a94e9dfe-ee2b-460d-b9a7-1eb62e501891','topic-privorot','{\"title\": \"Приворот\", \"description\": \"Приворот — это магическое воздействие, направленное на привлечение чувств определённого человека.\", \"symptoms_title\": \"Признаки приворота\", \"symptoms\": \"Навязчивые мысли об одном человеке\\nПотеря интереса к другим\\nРезкое изменение чувств\\nЗависимость от партнёра\", \"when_title\": \"Когда обращаться\", \"when_to_contact\": \"Если подозреваете приворот\\nЕсли чувства изменились внезапно\", \"consultation_title\": \"Диагностика и помощь\", \"consultation_process\": \"Диагностика\\nОпределение типа воздействия\\nСнятие приворота\\nВосстановление состояния\", \"cta_title\": \"Нужна помощь?\", \"cta_text\": \"Запишитесь на диагностику.\", \"cta_button\": \"Снять приворот\", \"additional_title\": \"Снятие приворота: возврат свободы воли и подлинных чувств\", \"additional_text\": \"Приворот — направленное воздействие, цель которого — искусственно привязать одного человека к другому против его свободной воли. Со стороны такие отношения могут казаться «огромной любовью», но изнутри ощущаются как затяжная зависимость, болезнь, душевная тяжесть. Человек под приворотом часто страдает: его словно «ведёт» к партнёру, к которому в обычном состоянии он бы не пошёл. Здоровье ухудшается, психика расшатывается, страдают и близкие.\\n\\nКаждая новая битва экстрасенсов снова напоминает: тонкий мир не терпит насилия. Любое наведённое чувство рано или поздно даёт сбои — резкие смены настроения у объекта приворота, агрессия, болезни сердца, депрессии. Опытный маг видит приворот по характерным признакам в энергетике пары, а сильный медиум считывает не только сам факт привязки, но и личность того, кто заказывал воздействие. Это знание помогает выстроить корректный план снятия.\\n\\nКонсультация экстрасенса в вопросе приворота полезна с двух сторон. Снятие нужно как самому объекту воздействия (чтобы вернуть себе свободу выбора и здоровье), так и человеку, который ранее заказал приворот и теперь хочет очиститься от последствий — потому что обратная волна неизбежно прилетает к заказчику и сильно усложняет его собственную жизнь. Оба случая требуют деликатной, ответственной работы.\\n\\nСнятие приворота — не «магия мести», а возврат естественного хода вещей. После корректно проведённой работы человек постепенно выходит из туманного состояния, начинает яснее видеть реальность отношений и принимать решения уже не «под действием», а из себя. Если вы чувствуете, что в ваших отношениях есть что-то нездоровое и неестественное, или подозреваете, что близкий человек попал под чужое влияние, не закрывайте на это глаза. Запишитесь на консультацию: специалист поможет разобраться в ситуации и аккуратно восстановить свободу — вашу или дорогого вам человека.\\n\\nЕсли вы подозреваете, что под привороты попал близкий человек — сын, дочь, брат, друг, — действовать стоит особенно деликатно. Прямые обвинения и попытки «открыть глаза» обычно вызывают только агрессию: жертва приворота воспринимает партнёра как «свет в окошке» и любую критику отметает. Намного эффективнее обратиться к специалисту самостоятельно: грамотный мастер может работать с фотографией и согласием самого клиента (родственника), мягко ослабляя привязку. Постепенно человек начинает «приходить в себя» и сам видит ситуацию без розовых очков — и тогда у него появляется шанс на честный выбор.\"}','2026-03-06 17:33:19'),
('b4216bea-cc35-4f6a-8a2c-5fcd6d0087d5','booking','{\"page_title\":\"Запись на приём к экстрасенсу\",\"page_subtitle\":\"Заполните форму для записи на консультацию\"}','2026-03-06 17:33:19'),
('b7bb73ba-6c14-433d-b4fc-c3b89ee6ea9f','reviews','{\"page_title\":\"Отзывы о наших специалистах\",\"page_subtitle\":\"Реальные истории людей, которым мы помогли\"}','2026-03-06 17:33:19'),
('dbe0578e-2c3e-4102-aa14-904a4d9b5fd3','topic-proklyatie','{\"title\": \"Проклятие\", \"description\": \"Проклятие — это сильное негативное воздействие, которое может передаваться из поколения в поколение.\", \"symptoms_title\": \"Признаки родового проклятия\", \"symptoms\": \"Повторяющиеся несчастья в нескольких поколениях\\nОдинаковые болезни у родственников\\nНевозможность создать семью\\nРанние смерти в роду\", \"when_title\": \"Когда нужна помощь\", \"when_to_contact\": \"Если вы заметили закономерности в судьбах родственников\\nЕсли проблемы повторяются из поколения в поколение\", \"consultation_title\": \"Работа с проклятием\", \"consultation_process\": \"Изучение истории рода\\nДиагностика\\nСнятие проклятия\\nУстановка защиты\", \"cta_title\": \"Хотите разорвать цепь?\", \"cta_text\": \"Запишитесь на консультацию.\", \"cta_button\": \"Снять проклятие\", \"additional_title\": \"Снятие проклятия: разрыв родовых программ и тяжёлых обетов\", \"additional_text\": \"Проклятие — самое серьёзное негативное воздействие из всех известных в эзотерической практике. Оно отличается от порчи тем, что часто работает не на одного человека, а на весь род: переходит от родителей к детям, повторяет одни и те же сценарии (ранние смерти, разорения, неудачные браки, тяжёлые болезни) из поколения в поколение. Самостоятельно справиться с такой программой почти невозможно — нужна работа сильного специалиста с глубоким видением.\\n\\nЛучшие специалисты, представленные на официальном сайте «битва экстрасенсов», специализируются именно на снятии тяжёлых программ. Каждый практикующий маг и каждая ясновидящая в нашей команде владеет собственными методами работы с проклятиями: кто-то использует молитвенные практики, кто-то — древние обряды, кто-то — энергетическую правку родового канала. Главное, что объединяет специалистов, — высокая квалификация и личная ответственность за результат.\\n\\nКонсультация экстрасенса по поводу проклятия всегда начинается с подробной беседы. Специалист изучает родовую историю клиента: повторяющиеся сценарии у родственников, ранние трагедии, причины, по которым «не везёт по линии». Параллельно проводится энергетическая диагностика, позволяющая увидеть саму программу — её форму, силу, источник, привязки. Только после этого подбирается метод снятия. Иногда нужны 1–2 сеанса, иногда — длительная пошаговая работа на несколько месяцев.\\n\\nЕсли в вашей семье из поколения в поколение повторяются одни и те же беды, если важные жизненные двери для вас всегда оказываются закрытыми, а интуиция давно подсказывает «здесь что-то не так», не игнорируйте этот сигнал. Запишитесь на консультацию: профессиональное снятие проклятия способно не только облегчить вашу собственную судьбу, но и подарить лучший сценарий вашим детям и внукам. Это вклад в благополучие всего рода — и одно из самых сильных решений, которые человек может принять в своей жизни.\\n\\nОсобенно важна такая работа для родителей и тех, кто только планирует ребёнка. Невостребованная родовая программа неизбежно перейдёт по линии — и ваш ребёнок окажется в той же ловушке, в которой годами бились вы. Снимая проклятие при жизни, человек буквально освобождает следующие поколения от груза, который должен был достаться им «по наследству». Этот шаг — один из самых благородных и далеко идущих в эзотерической практике, и многие клиенты отмечают, что именно желание защитить детей стало решающим в обращении к специалисту.\"}','2026-03-06 17:33:19'),
('e2911ab2-a69b-4bbb-921b-ba238bc82f6f','topic-sglaz','{\"title\": \"Сглаз\", \"description\": \"Сглаз — это непреднамеренное негативное воздействие, вызванное завистью или сильными эмоциями.\", \"symptoms_title\": \"Симптомы сглаза\", \"symptoms\": \"Внезапная усталость\\nГоловные боли\\nРезкая смена настроения\\nПроблемы со сном\\nНеудачи в делах\", \"when_title\": \"Когда обращаться\", \"when_to_contact\": \"Если негатив появился после похвалы\\nЕсли успехи сменились неудачами\", \"consultation_title\": \"Снятие сглаза\", \"consultation_process\": \"Диагностика\\nСнятие воздействия\\nВосстановление энергетики\\nУстановка защиты\", \"cta_title\": \"Чувствуете что-то не то?\", \"cta_text\": \"Запишитесь на диагностику.\", \"cta_button\": \"Снять сглаз\", \"additional_title\": \"Снятие сглаза: возврат лёгкости и энергии в повседневной жизни\", \"additional_text\": \"Сглаз — наиболее частое негативное воздействие, с которым сталкивается практически каждый человек хотя бы раз в жизни. В отличие от порчи или проклятия, он, как правило, не наводится осознанно: достаточно зависти, восхищения «через край» или просто сильного эмоционального удара со стороны другого человека. Однако «несерьёзность» источника не делает сглаз безобидным. Он способен украсть силы, испортить настроение на недели, спровоцировать ссоры и сбить с толку даже самого устойчивого человека.\\n\\nЦикл «экстрасенсы реванш», как и сам проект «битва экстрасенсов», знаменит тем, что показывает: даже самые «невидимые» воздействия имеют чёткую структуру и поддаются устранению. Опытная ведьма видит сглаз буквально с первых минут общения с клиентом — по голосу, взгляду, состоянию ауры. Дальше всё дело техники: специалист определяет, кто и при каких обстоятельствах «зацепил», есть ли усиление или это разовое явление, и подбирает метод очищения.\\n\\nПрофессиональная помощь экстрасенса при сглазе обычно занимает гораздо меньше времени, чем работа с порчей или проклятием. Чаще достаточно одного-двух сеансов, чтобы человек снова почувствовал себя собой: вернулась бодрость, нормализовался сон, ушла беспричинная тревожность, начали складываться рабочие и семейные дела. В сложных случаях, когда сглаз «впитался» давно и оброс дополнительными слоями, работа выстраивается поэтапно.\\n\\nПризнаки, по которым стоит насторожиться: внезапная усталость без причины, частые головные боли «из ниоткуда», ссоры с близкими на пустом месте, череда мелких неудач, чувство, что «всё валится из рук». Особенно внимательно к себе и детям стоит относиться после праздников, шумных компаний, появления на людях с радостной новостью. Не игнорируйте интуицию: запишитесь на короткую диагностику. Своевременное снятие сглаза занимает несколько дней, а возвращает порой месяцы полноценной жизни.\\n\\nОсобого внимания заслуживает сглаз у детей и домашних животных: они наиболее уязвимы к чужой энергетике, потому что ещё не имеют сформированной защиты. У ребёнка сглаз проявляется внезапной плаксивостью, отказом от еды, нарушением сна, у животного — апатией, болезнями без причин. В этих случаях специалист использует мягкие, щадящие методики — выкатывание яйцом, заговорённую воду, простые материнские молитвы, которым может научиться сама мама. Снятие проходит быстро и без побочных эффектов, а атмосфера в доме почти сразу становится спокойнее и теплее.\"}','2026-03-06 17:33:19'),
('f1830b60-6c64-4920-985d-1d3428cd2d0c','contacts','{\"page_title\":\"Контакты\",\"page_subtitle\":\"Свяжитесь с нами для записи на консультацию\"}','2026-03-06 17:33:19');
INSERT INTO `participants` VALUES
('0a1b0a8c-ae8b-4a65-9b05-9c9f2b7c59fb','vlad-cherevatyy','Влад Череватый','Победитель 23 сезона «Битвы экстрасенсов»','Молодой и сильный экстрасенс-медиум, победитель 23 сезона «Битвы экстрасенсов». Работает с тёмной энергетикой и тонкими состояниями человека, проводит диагностику и создаёт защитные амулеты.','Влад Череватый — победитель 23 сезона проекта «Битва экстрасенсов», один из самых ярких и обсуждаемых участников последних лет. Его появление на проекте сразу привлекло внимание зрителей благодаря необычной подаче, уверенности и нестандартному подходу к выполнению испытаний. Влад родился в Украине и с юности, по его словам, сталкивался с ощущением присутствия сил, которые сложно объяснить с точки зрения логики.\n\nНа проекте Череватый проявил себя как практик, работающий с тёмной энергетикой и тонкими состояниями человека. Его методы отличались прямотой и глубиной: он не просто описывал происходящее, а пытался докопаться до причины, показывая скрытые процессы и внутренние конфликты людей. Именно эта способность видеть ситуацию шире и глубже позволила ему уверенно пройти испытания и занять первое место.\n\nОтдельное внимание Влад уделяет взаимодействию с внутренним состоянием человека, его страхами, переживаниями и тем, что обычно скрыто от постороннего взгляда. В своей практике он сочетает интуитивное восприятие с жёстким, иногда даже провокационным стилем общения, который, по его словам, помогает быстрее вывести человека на осознание проблемы.\n\nПосле победы в шоу Влад Череватый активно продолжил развивать свою практику. Он работает с людьми как в личном формате, так и дистанционно, помогая разобраться в сложных жизненных ситуациях, понять причины происходящего и найти дальнейшее направление. Многие отмечают, что после общения с ним меняется не только взгляд на проблему, но и общее восприятие себя и своей жизни.\n\nНесмотря на неоднозначное отношение аудитории, Влад остаётся одной из самых обсуждаемых фигур проекта «Битва экстрасенсов». Его подход вызывает как интерес, так и споры, однако именно это делает его работу заметной и отличающейся от других.\n\nДанная страница является личной страницей помощи Влада Череватого.\n\nЗдесь вы имеете возможность:\n\n• Лично связаться и пообщаться с Владом Череватым.\n• Записаться на личный прием к Владу Череватому.\n\nДля того, чтобы получить помощь, консультацию либо записаться на личный прием к Владу Череватому, вам нужно:\n\n1. Нажать на кнопку «Обратиться».\n2. Заполните форму — это необходимо, чтобы Влад мог с вами связаться.\n3. Ждите звонок!!!','/api/uploads/vlad-cherevatyy-new.jpg','[\"Медиум\",\"Экстрасенс\"]',1,8,'2026-03-06 17:47:45'),
('510cc3de-0901-490b-bb7e-01257af330de','viktoriya-raidos','Виктория Райдос','Победительница 16 сезона «Битвы экстрасенсов»','Экстрасенс-медиум, победительница 16 сезона «Битвы экстрасенсов». Обладает редким даром связи с потусторонним миром. Проводит спиритические сеансы, считывает информацию по фотографиям и предметам, помогает в поиске пропавших людей.','Виктория Райдос — победительница 16 сезона проекта «Битва экстрасенсов», медиум и практик, работающий с темами родовой памяти и глубинных связей между прошлым и настоящим. Родом из Москвы, во взрослом возрасте переехала в Санкт-Петербург, где живёт и работает.\n\nЕё практика строится не только на интуиции, но и на умении анализировать происходящее, соединяя эмоциональное восприятие с логикой. Виктория уделяет особое внимание родовым сценариям, считая, что многие жизненные трудности имеют свои корни в прошлом семьи, в повторяющихся моделях и неразрешённых ситуациях.\n\nВо время участия в «Битве экстрасенсов» Виктория Райдос проявила себя как сильный и уверенный участник. Её отличала способность глубоко погружаться в задачу, точно передавать информацию и сохранять внутреннюю устойчивость даже в сложных испытаниях. Победа в проекте стала подтверждением её уровня и профессионализма.\n\nПосле завершения шоу Виктория продолжила практику, сосредоточившись на индивидуальной работе с людьми. К ней обращаются с различными жизненными ситуациями: вопросы личной жизни, внутренние переживания, повторяющиеся проблемы, ощущение тупика или потери направления. В своей работе она помогает увидеть причины происходящего и понять, какие шаги необходимо предпринять дальше.\n\nЕё подход отличается внимательностью к деталям и стремлением не просто дать ответ, а помочь человеку разобраться в себе и своей ситуации на более глубоком уровне.\n\nДанная страница является личной страницей помощи Виктории Райдос.\n\nЗдесь вы можете:\n\n• Связаться с Викторией Райдос и обсудить свою ситуацию\n\n• Записаться на личный приём или дистанционную консультацию\n\nЧтобы обратиться за помощью:\n\n1. Нажмите на кнопку «Обратиться»\n\n2. Заполните форму — это необходимо, чтобы Виктория могла с вами связаться и разобраться в вашей ситуации\n\n3. Ожидайте обратной связи\n\nПосле отправки заявки с вами свяжутся для уточнения деталей и дальнейшей работы.','/api/uploads/viktoriya-raidos-new.jpg','[\"Медиум\",\"Экстрасенс\"]',1,3,'2026-03-06 17:47:45'),
('6511bedc-22c4-4938-8b19-f538a197f4ab','oleg-sheps','Олег Шепс','Победитель 21 сезона «Битвы экстрасенсов»','Потомственный маг и практикующий оккультист. Владеет техниками церемониальной магии и энергетической защиты. Специализируется на снятии сложных негативных воздействий и создании мощных защитных барьеров.','Олег Шепс — победитель 21 сезона проекта «Битва экстрасенсов», медиум, который продолжил семейную линию, связанную с изучением тонких энергий и восприятием скрытых процессов. Он родился в Самаре и с раннего возраста, по его словам, ощущал необычные проявления, которые постепенно сформировали его интерес к развитию собственных способностей.\n\nОсобенность подхода Олега заключается в сочетании эмоциональной чувствительности и внутренней концентрации. Он работает с восприятием энергии человека, его состояния и окружающих факторов, которые могут оказывать влияние на жизнь и происходящие события. В своей практике он уделяет внимание не только самим проблемам, но и их глубинным причинам.\n\nНа проекте «Битва экстрасенсов» Олег Шепс проявил себя как участник, способный быстро включаться в процесс и точно передавать информацию. Его отличала открытость, искренность и высокая вовлечённость в каждое испытание, что позволило ему уверенно пройти этапы и в итоге занять первое место.\n\nПосле победы в проекте Олег продолжил активно развивать свою практику. К нему обращаются люди с различными жизненными вопросами: личные отношения, внутренние переживания, сложные ситуации, когда важно понять причины происходящего и найти решение.\n\nВ своей работе Олег стремится не просто дать ответ, а помочь человеку осознать ситуацию, увидеть возможные пути выхода и изменить направление своей жизни. Его подход ориентирован на понимание и постепенное выравнивание внутреннего состояния.\n\nДанная страница является личной страницей помощи Олега Шепса.\n\nЗдесь вы можете:\n\n• Связаться с Олегом Шепсом и обсудить свою ситуацию\n• Записаться на личный приём или дистанционную консультацию\n\nЧтобы обратиться за помощью:\n\n1. Нажмите на кнопку «Обратиться»\n2. Заполните форму — это необходимо, чтобы Олег мог с вами связаться и разобраться в вашей ситуации\n3. Ожидайте обратной связи\n\nПосле отправки заявки с вами свяжутся для уточнения деталей и дальнейшей работы.','/api/uploads/oleg-sheps-new.jpg','[\"Медиум\",\"Экстрасенс\"]',1,6,'2026-03-06 17:47:45'),
('a6d90f03-6e43-49c6-ad17-3b291f4c05f8','elena-golunova','Елена Голунова','Финалистка 13 сезона «Битвы экстрасенсов»','Сильнейшая ясновидящая России. Финалистка 13 сезона «Битвы экстрасенсов». Работает с энергетикой человека, проводит точную диагностику жизненных ситуаций и помогает найти выход из самых сложных обстоятельств.','Елена Голунова — одна из самых известных участниц проекта «Битва экстрасенсов», финалистка 13 сезона, запомнившаяся зрителям своей прямотой, жёсткой подачей и уверенностью в каждом слове. В отличие от многих участников, она никогда не стремилась понравиться — её стиль всегда был честным, строгим и по делу, что и вызвало сильный отклик у аудитории.\n\nЕлена Валерьевна родилась в Новосибирске. По её собственным словам, ещё в детстве она начала ощущать то, что другие не замечают: изменения в энергетике людей, внутренние состояния и скрытые процессы, происходящие вокруг. С возрастом эти способности только усиливались, формируя её как практика, работающего не поверхностно, а глубоко — на уровне причин.\n\nВ своей работе Елена Голунова открыто говорит о том, что взаимодействует с тёмной энергетикой и родовыми программами. Она подчёркивает, что её дар передаётся по наследственной линии, и именно поэтому её методы направлены не только на устранение внешних проблем, но и на проработку их источника. В её практике особое внимание уделяется таким вопросам, как родовые блоки, негативные воздействия, повторяющиеся жизненные сценарии и скрытые энергетические привязки.\n\nВо время участия в «Битве экстрасенсов» Елена проявила себя как один из самых сильных и устойчивых участников. Она уверенно проходила испытания, часто демонстрируя точные и жёсткие ответы там, где другие сомневались. Её подход не строится на эмоциях — он основан на анализе, опыте и глубоком понимании происходящего.\n\nПосле проекта Елена продолжила частную практику и стала одной из самых востребованных специалистов среди людей, которые ищут не просто слова поддержки, а реальные ответы и изменения в жизни. К ней обращаются с самыми разными ситуациями: личная жизнь, сложные жизненные периоды, вопросы здоровья, финансовые трудности, непонятные состояния и ощущения.\n\nДанная страница является личной страницей помощи Елены Голуновой.\n\nЗдесь вы можете:\n\n• Связаться с Еленой Голуновой и получить консультацию по своей ситуации\n\n• Записаться на личный приём или дистанционную работу\n\nЧтобы обратиться за помощью:\n\n1. Нажмите кнопку «Обратиться»\n\n2. Заполните форму — это необходимо, чтобы Елена могла с вами связаться и помочь в вашей ситуации\n\n3. Ожидайте обратной связи\n\nПосле отправки заявки с вами свяжутся для уточнения деталей и дальнейшей работы.','/api/uploads/elena-golunova-new.jpg','[\"Ведьма\",\"Ясновидящая\"]',1,1,'2026-03-06 17:47:45'),
('bff728e9-87bd-4ad4-9226-663b60f94401','zuliya-radzhabova','Зулия Раджабова','Победительница 2 сезона «Битвы экстрасенсов»','Целительница и ясновидящая с восточными корнями. Владеет техниками энергетического целительства и духовных практик Востока. Помогает восстановить здоровье, гармонизировать отношения и обрести душевное равновесие.','Зулия Раджабова — победительница 2 сезона проекта «Битва экстрасенсов», одна из самых узнаваемых и запоминающихся участниц ранних сезонов шоу. Её путь начался задолго до телевизионной известности: родом из Дагестана, Зулия с детства отмечала у себя особую чувствительность к людям и происходящим событиям. По её словам, она рано начала замечать вещи, которые оставались незаметными для окружающих, и постепенно научилась понимать и интерпретировать эти ощущения.\n\nВо время участия в «Битве экстрасенсов» Зулия продемонстрировала уверенность, спокойствие и точность в выполнении заданий. Её подход отличался сосредоточенностью, вниманием к деталям и умением глубоко погружаться в ситуацию. Именно это позволило ей не только успешно проходить испытания, но и завоевать доверие зрителей, что в итоге привело её к победе.\n\nПосле проекта Зулия Раджабова продолжила развивать свою практику, сосредоточившись на индивидуальной работе с людьми. В своей деятельности она уделяет особое внимание эмоциональному состоянию человека, внутренним переживаниям и жизненным обстоятельствам, которые могут влиять на текущее положение дел. Её подход основан на внимательном анализе ситуации и стремлении помочь человеку увидеть скрытые аспекты происходящего.\n\nЗулия известна своим спокойным и уравновешенным стилем общения. Она не делает резких выводов, а предпочитает поэтапно разбирать проблему, помогая человеку самостоятельно осознать причины происходящего и найти выход из сложной ситуации. Многие отмечают, что после общения с ней появляется ощущение ясности и внутреннего спокойствия.\n\nДанная страница является личной страницей помощи Зулии Раджабовой.\n\nЗдесь вы имеете возможность:\n\n• Лично связаться и пообщаться с Зулией Раджабовой.\n• Записаться на личный прием к Зулии Раджабовой.\n\nДля того, чтобы получить помощь, консультацию либо записаться на личный прием к Зулии Раджабовой, вам нужно:\n\n1. Нажать на кнопку «Обратиться».\n2. Заполните форму — это необходимо, чтобы Зулия могла с вами связаться.\n3. Ждите звонок!!!','/api/uploads/zuliya-radzhabova-new.jpg','[\"Ясновидящая\",\"Экстрасенс\"]',1,7,'2026-03-06 17:47:45'),
('e4b20f5e-d327-4f5a-8d82-c66ab7c9f5b4','aleksandr-sheps','Александр Шепс','Победитель 14 сезона «Битвы экстрасенсов»','Один из сильнейших экстрасенсов России, победитель 14 сезона «Битвы экстрасенсов». Обладает мощным даром ясновидения и телепатии. Работает с кармой, прошлыми жизнями и энергетическими потоками.','Александр Шепс — победитель 14 сезона проекта «Битва экстрасенсов», медиум, работающий с темами контакта с иным миром и тонкими энергетическими процессами. Он родился в Самаре и, по его словам, с раннего возраста сталкивался с явлениями, которые сложно объяснить с точки зрения обычного восприятия.\n\nСвою практику Александр Шепс выстраивает на взаимодействии с миром духов. Он утверждает, что способен получать информацию через тонкие каналы восприятия, что позволяет ему видеть то, что скрыто от обычного взгляда. В его работе важную роль играет не только сам процесс получения информации, но и правильная интерпретация увиденного.\n\nНа проекте «Битва экстрасенсов» Александр выделялся уверенностью, спокойствием и способностью точно передавать детали. Его прохождение испытаний сопровождалось высокой точностью и стабильными результатами, что в итоге привело его к победе. Зрители отмечали его сосредоточенность и глубину погружения в каждую задачу.\n\nПосле завершения участия в шоу Александр Шепс продолжил развивать свою практику и стал активно работать с людьми. К нему обращаются с различными вопросами: личные отношения, сложные жизненные ситуации, внутренние переживания, поиск ответов и понимания происходящего.\n\nВ своей работе Александр стремится не только передать информацию, но и помочь человеку разобраться в ситуации, увидеть скрытые причины и принять решения, которые могут изменить дальнейший ход событий.\n\nДанная страница является личной страницей помощи Александра Шепса.\n\nЗдесь вы можете:\n\n• Связаться с Александром Шепсом и обсудить свою ситуацию\n• Записаться на личный приём или дистанционную консультацию\n\nЧтобы обратиться за помощью:\n\n1. Нажмите на кнопку «Обратиться»\n2. Заполните форму — это необходимо, чтобы Александр мог с вами связаться и разобраться в вашей ситуации\n3. Ожидайте обратной связи\n\nПосле отправки заявки с вами свяжутся для уточнения деталей и дальнейшей работы.','/api/uploads/aleksandr-sheps-new.jpg','[\"Медиум\",\"Экстрасенс\"]',1,5,'2026-03-06 17:47:45'),
('e9fabf23-fa87-439f-a9c8-902409219269','angelina-izosimova','Ангелина Изосимова','Финалистка 23 сезона «Битвы экстрасенсов»','Потомственная ведьма с уникальным даром чтения судеб. Владеет древними славянскими практиками, работает с родовыми программами и кармическими узлами. Помогает избавиться от негативных воздействий и обрести внутреннюю силу.','Ангелина Изосимова — финалистка 23 сезона проекта «Битва экстрасенсов», которая запомнилась зрителям своим спокойствием, внутренней собранностью и внимательным отношением к каждой детали. В отличие от более эмоциональных участников, Ангелина всегда демонстрировала сдержанный и вдумчивый подход, делая акцент не на эффекте, а на точности.\n\nО её личной биографии известно немного, однако именно это и формирует вокруг неё особое ощущение закрытости и концентрации на практике. По имеющейся информации, Ангелина работает через интуитивное восприятие и чувствование энергетического состояния человека. Она уделяет большое внимание внутренним ощущениям, изменениям в поведении и скрытым факторам, которые могут влиять на жизненные ситуации.\n\nВ процессе работы Ангелина Изосимова не спешит с выводами — она постепенно анализирует происходящее, выстраивая полную картину проблемы. Такой подход позволяет ей замечать нюансы, которые часто остаются вне внимания. Именно благодаря этому многие обращающиеся отмечают её точность и способность «попадать в суть» даже сложных ситуаций.\n\nНа проекте «Битва экстрасенсов» Ангелина проявила себя как участник, предпочитающий последовательную и аккуратную работу. Она не стремилась к громким заявлениям, но стабильно показывала результат, вызывая доверие у зрителей. После завершения участия в шоу она продолжила частную практику, сосредоточившись на индивидуальной работе с людьми.\n\nК Ангелине обращаются в ситуациях, когда важно разобраться в происходящем без лишнего давления: проблемы в личной жизни, внутренние переживания, неопределённость, повторяющиеся жизненные трудности. Её подход направлен на понимание причин и постепенное выравнивание ситуации.\n\nДанная страница является личной страницей помощи Ангелины Изосимовой.\n\nЗдесь вы можете:\n\n• Связаться с Ангелиной Изосимовой и обсудить свою ситуацию\n\n• Записаться на личный приём или дистанционную консультацию\n\nЧтобы обратиться за помощью:\n\n1. Нажмите кнопку «Обратиться»\n\n2. Заполните форму — это необходимо, чтобы Ангелина могла с вами связаться и разобраться в вашей ситуации\n\n3. Ожидайте обратной связи\n\nПосле отправки заявки с вами свяжутся для уточнения деталей и дальнейшей работы.','/api/uploads/angelina-izosimova-new.jpg','[\"Целитель\",\"Экстрасенс\"]',1,2,'2026-03-06 17:47:45'),
('efbd6d96-4c59-448d-a546-c9595a02c26b','nadezhda-shevchenko','Надежда Шевченко','Финалистка 17 сезона «Битвы экстрасенсов»','Ясновидящая и таролог с многолетним опытом. Работает через карты Таро и интуитивное считывание. Специализируется на вопросах любви, карьеры и финансового благополучия. Известна высокой точностью прогнозов.','Надежда Шевченко — финалистка 17 сезона проекта «Битва экстрасенсов», практик, работающий с ритуальными и энергетическими методами. Она получила широкую известность благодаря своему яркому стилю, эмоциональной подаче и уверенности в работе с тонкими процессами, которые, по её словам, напрямую влияют на судьбу человека.\n\nНа протяжении участия в проекте Надежда привлекала внимание тем, что использовала не только интуитивное восприятие, но и обрядовые элементы, символику и специальные ритуалы. Её подход отличался глубиной и погружением в процесс, что позволяло ей раскрывать скрытые аспекты ситуаций и находить причины происходящего.\n\nВ своей практике Надежда Шевченко делает акцент на работе с энергетикой человека, его внутренним состоянием и внешними воздействиями. Она считает, что многие проблемы — будь то личная жизнь, финансовые трудности или ощущение застоя — могут быть связаны с накопленным негативом или влиянием извне.\n\nПосле участия в «Битве экстрасенсов» Надежда продолжила активно заниматься частной практикой. К ней обращаются люди, которые сталкиваются с непростыми жизненными ситуациями, когда стандартные решения не дают результата и требуется более глубокий подход.\n\nЕё работа направлена не только на выявление проблемы, но и на постепенное изменение ситуации. Многие отмечают, что после взаимодействия с ней начинают по-другому смотреть на происходящее и находят выход даже из затяжных жизненных трудностей.\n\nДанная страница является личной страницей помощи Надежды Шевченко.\n\nЗдесь вы можете:\n\n• Связаться с Надеждой Шевченко и обсудить свою ситуацию\n\n• Записаться на личный приём или дистанционную консультацию\n\nЧтобы обратиться за помощью:\n\n1. Нажмите на кнопку «Обратиться»\n\n2. Заполните форму — это необходимо, чтобы Надежда могла с вами связаться и разобраться в вашей ситуации\n\n3. Ожидайте обратной связи\n\nПосле отправки заявки с вами свяжутся для уточнения деталей и дальнейшей работы.','/api/uploads/nadezhda-shevchenko-new.jpg','[\"Ведьма\",\"Ясновидящая\"]',1,4,'2026-03-06 17:47:45');
INSERT INTO `reviews` VALUES
('04a4df32-eaa6-4461-af90-94ea19a8e556','elena-golunova','Кристина, 25','','Я жила в постоянном, липком страхе и паранойе. Мой бывший парень никак не мог смириться с нашим окончательным расставанием. Он маниакально преследовал меня, часами караулил у подъезда, присылал жуткие голосовые сообщения с угрозами, резал шины на моей машине по ночам. Полиция только разводила руками — говорили, что нет состава преступления, вот когда убьет, тогда и приходите. Я панически боялась просто выходить из дома в магазин. В полном отчаянии я стала искать сильную магическую защиту. По многочисленным отзывам поняла, что сибирская ведьма Елена Голунова — это именно тот властный человек, который может жестко поставить на место такого неадеквата. Я нашла ее официальный контакт в сети и записалась на прием. Елена выслушала меня и провела сложный обряд зеркальной защиты. Она уверенно сказала, что теперь абсолютно всё зло, которое он мне желает и делает, будет моментально возвращаться к нему самому в троекратном размере. Я не знаю, как именно работает эта магия, но через неделю он сильно сломал ногу, потом у него начались серьезные проблемы с законом на работе, и он навсегда исчез из моей жизни. Я наконец-то дышу свободно и не оглядываюсь на улице!',5,1,'2026-03-23 12:04:00'),
('0b8bb3a9-2dbe-11f1-a618-1e4a3e6dea57','vlad-cherevatyy','Михаил, 38','','Я получил в наследство от двоюродного дяди коллекционную Волгу. Радости не было предела, пока я не начал на ней ездить. Каждый раз, когда я садился за руль, меня словно кто-то гипнотизировал. Я выезжал за город и ехал в сторону заброшенной деревни, вообще не контролируя процесс. Очухивался только на глухой грунтовке. Жена была в шоке, думала, что у меня помутнение рассудка. Решили искать помощь, так как продавать раритет было жалко, да и страшно кому-то отдавать такое. Стали искать экстрасенса, читали отзывы. Нас зацепил Влад Череватый, его жесткий подход из битвы сильнейших внушал доверие. Нашли официальный сайт Влада, узнали стоимость приема. Запись была плотной, но мы попали. Влад в Москве посмотрел фото машины и усмехнулся. Сказал, что дядя спрятал в обшивке сиденья старинный клад, заговоренный на кровь, и машина везла меня туда, где он его выкопал. Влад помог снять эту жуткую привязку. Мы вскрыли сиденье и реально нашли тайник с монетами! Машина теперь ездит нормально.',5,1,'2026-03-23 19:25:00'),
('0b8bb5b8-2dbe-11f1-a618-1e4a3e6dea57','vlad-cherevatyy','Анна, 32','','Работать свадебным фотографом — моя страсть, но моя карьера чуть не разрушилась из-за странного проклятия. Как только я пыталась сфотографировать свою младшую сестру с ее новым парнем, объектив моей дорогой камеры просто трескался. Я сменила три объектива! Думала, брак стекла, перепады температур, но это происходило только при наведении на них. Когда треснуло четвертое стекло, я поняла, что это мистика. Мы стали искать экстрасенс влад череватый отзывы, так как давно следили за ним. Узнали через телефон цены, написали в ватсап его команде. На онлайн-встрече ясновидящий сразу сказал, что этот парень — энергетический вампир, на котором висит порча на смерть, и оптика просто не выдерживает такого черного фона. Влад провел диагностику и жесткий ритуал отсечения сестры от этого человека. Через неделю они расстались, парень уехал. Я снова могу снимать сестру, камеры целы, а Владу огромное спасибо за помощь!',5,1,'2026-03-23 19:24:00'),
('0b8bd3ec-2dbe-11f1-a618-1e4a3e6dea57','vlad-cherevatyy','Константин, 45','','Со мной начала происходить абсолютно неконтролируемая дичь. Каждые выходные я брал лопату и маниакально рыл ямы у себя на даче. Я не искал клад, мне не нужны были грядки. Я просто копал до изнеможения, стирая руки в кровь, словно мной кто-то управлял. Жена рыдала, соседи крутили пальцем у виска. Я сам себя боялся. Психиатр выписал таблетки, но тяга копать была сильнее. Решили, что нужна нетрадиционная помощь. Зашли на сайт Влада Череватого, оставили заявку. Узнать сколько стоит прием было несложно, мы быстро связались с администратором. Влад принял нас онлайн. Чернокнижник Влад Череватый рассмеялся своим фирменным смехом и сказал, что на участок мне подкинули заговоренную землю с могилы самоубийцы, и мертвяк заставляет меня рыть ему новую яму. Он дал четкие инструкции, как отжечь эту дрянь с помощью свечей и соли. Я выполнил ритуал. В те же выходные лопату в руки больше не брал, тяга исчезла полностью.',5,1,'2026-03-23 19:23:00'),
('0b8bd47f-2dbe-11f1-a618-1e4a3e6dea57','vlad-cherevatyy','Ирина, 29','','Я волонтер, часто беру бездомных животных на передержку. И вдруг в моей квартире началось безумие. Пять котов разных возрастов одновременно сели напротив одной пустой стены в коридоре и стали неотрывно смотреть в одну точку. Они отказывались есть, пить, просто сидели и смотрели, иногда шипели. Я простучала стену, думала там мыши — ничего. Животные начали истощаться. Я поняла, что они видят то, чего не вижу я. Стала искать контакты экстрасенса. Нашла информацию, как попасть на прием к Владу Череватому. Узнала стоимость, оформила запись. Влад провел онлайн-консультацию. Он посмотрел через камеру на эту стену и сказал, что там открылся стихийный портал, через который в квартиру лезет бесовщина, а коты, как стражи, держат оборону, жертвуя собой. Влад провел мощный дистанционный ритуал закрытия портала. Коты одновременно выдохнули, развернулись и пошли к мискам! Это было просто потрясающе, его сила невероятна.',5,1,'2026-03-23 19:22:00'),
('0b8bd4e1-2dbe-11f1-a618-1e4a3e6dea57','vlad-cherevatyy','Сергей, 40','','Моя пекарня славилась лучшим хлебом на закваске. Но внезапно хлеб начал кровоточить. Это не метафора. При разрезании свежей буханки внутри оказывались ярко-красные, влажные пятна, похожие на кровь, с запахом ржавчины. Санэпидемстанция брала пробы, говорили про красную плесень, мы дезинфицировали всё помещение пять раз, сменили муку, воду, даже пекарей. Ничего не помогало, бизнес умирал. Жена настояла на поиске колдуна. Выбрали Влада Череватого, так как он работает с жестким негативом. Нашли официальный адрес в Москве, узнали цену и приехали. Влад даже не стал разводить церемонии. Он сказал, что это порча на разорение через кровь животного, которую подмешали в затирку для швов на полу. Чернокнижник дал ритуал очищения пространства. Мы выжгли эти швы паяльной лампой, как он сказал. На следующий день хлеб получился идеальным. Бизнес спасен, конкуренты остались с носом.',5,1,'2026-03-23 19:21:00'),
('0b8bd53c-2dbe-11f1-a618-1e4a3e6dea57','vlad-cherevatyy','Татьяна, 52','','Никогда не покупайте старинные вещи с темной историей. Я приобрела напольные часы девятнадцатого века. Как только они пробили полночь в первый раз, из моей закрытой шкатулки пропало дорогое кольцо. Я перерыла весь дом. Через три дня оно лежало на видном месте. Затем пропали серьги, потом брошь. Вещи исчезали и возвращались, но после их возвращения я чувствовала жуткий упадок сил. Стало ясно, что в доме завелся полтергейст-воришка. Я стала искать экстрасенса, читала отзывы про Влада Череватого. Связалась через официальный сайт, узнала сколько стоят услуги. Влад консультировал нас дистанционно. Он сказал, что к часам привязан бес-барабашка, который питается энергией золота и моей паникой. Влад Череватый провел жесткий обряд усмирения беса. Часы он велел продать коллекционерам, предварительно очистив. Я всё сделала. Пропажи прекратились, здоровье восстановилось.',5,1,'2026-03-23 19:20:00'),
('0b8bef44-2dbe-11f1-a618-1e4a3e6dea57','vlad-cherevatyy','Оксана, 31','','Я занимаюсь индивидуальным пошивом свадебных платьев, это моя любимая работа. Но полгода назад начался мистический саботаж. Как только я садилась шить именно белое свадебное платье, иголки в швейной машинке ломались одна за другой. Я сменила пять машинок, покупала самые дорогие титановые иглы — они разлетались на куски. При этом обычную повседневную одежду я шила без проблем. Клиентки начали уходить, я теряла огромные деньги. Поняла, что это порча на мое дело. Знакомая дала мне контакт Влада Череватого. Я написала администраторам в ватсап, дождалась приема. Влад был очень конкретен. Сказал, что порчу сделала завистливая бывшая подруга, которой я отказалась шить платье бесплатно. Влад снял эту блокировку и поставил на мои руки защиту. В тот же вечер я села за машинку и прошила сложнейший корсет без единой сломанной иглы! Огромное спасибо за помощь.',5,1,'2026-03-23 19:19:00'),
('0b8befc4-2dbe-11f1-a618-1e4a3e6dea57','vlad-cherevatyy','Игорь, 37','','Моя история звучит как бред, но это разрушало мою жизнь. После вступления в наследство и получения крупной суммы от деда, у меня начались проблемы с голосом. Как только я пытался обсудить с женой, куда вложить эти деньги, мой голос менялся: я начинал говорить с сильным, грубым кавказским акцентом, хотя я коренной москвич. Я не мог это контролировать, слова сами вылетали изо рта. Логопеды и неврологи были в тупике. Жена пугалась меня. Я решил искать мистическую причину и наткнулся на официальный сайт экстрасенса Влада Череватого. Узнал стоимость приема в Москве и записался. Ясновидящий Влад сразу увидел, что деньги дед выиграл у человека нерусской национальности нечестным путем, и на этих финансах висело проклятие. Влад провел сложный ритуал очищения денежного канала и снятия этого морока. Мой голос восстановился сразу же после сеанса! Мы благополучно купили недвижимость.',5,1,'2026-03-23 19:18:00'),
('0b8bf01c-2dbe-11f1-a618-1e4a3e6dea57','vlad-cherevatyy','Валерия, 28','','Мы с мужем купили новую квартиру, всё было прекрасно, пока не началась чертовщина в ванной. Как только мой муж включал горячую воду, чтобы принять душ, из крана начинал идти ледяной кипяток, пар шел, а вода была обжигающе холодной! При этом, когда мылась я, вода была нормальной температуры. Сантехники меняли смесители, проверяли трубы — ничего. Муж стал мыться в фитнес-клубе, начались ссоры, он не хотел приходить домой. Я стала искать экстрасенса, так как поняла, что нас пытаются развести. Выбрала Влада Череватого по отзывам. Узнала через телефон цены, записались. Влад по видеосвязи сказал, что это остуда, которую подкинули нам в вентиляцию в виде заговоренной мертвой воды в пузырьке. Влад Череватый научил нас, как найти и уничтожить эту дрянь, и дистанционно почистил квартиру. Вода стала нормальной в тот же день. Семья спасена!',5,1,'2026-03-23 19:17:00'),
('0b8bf06e-2dbe-11f1-a618-1e4a3e6dea57','vlad-cherevatyy','Полина, 25','','Я театральная актриса, получила главную роль своей мечты. Но на первой же репетиции на сцене исторического театра у меня начался жуткий, безостановочный чих. Я не могла произнести ни реплики, глаза слезились. Выходила за кулисы — чих прекращался. Аллергологи делали пробы на пыль, софиты, ткани — аллергии нет. Режиссер грозился отдать роль дублерше. Я была в отчаянии. Моя костюмерша, женщина опытная, сказала, что это театральная порча. Я стала судорожно искать, где принимает Влад Череватый. Нашла официальную страницу, связалась с помощниками, умоляла о срочном приеме. Влад посмотрел мою ауру и сказал, что мне в туфли подсыпали кладбищенский прах, заговоренный на отторжение сцены. Чернокнижник провел отжиг негатива и поставил мощный щит. Туфли я выбросила. На следующий день я отыграла репетицию идеально, ни разу не чихнув. Премьера прошла с ошеломительным успехом!',5,1,'2026-03-23 19:16:00'),
('0b8bf0bb-2dbe-11f1-a618-1e4a3e6dea57','vlad-cherevatyy','Надежда, 48','','Я занимаюсь разведением редких сортов роз, это дело всей моей жизни. Но в этом сезоне произошло нечто жуткое. Мои белоснежные розы начали распускаться абсолютно черными бутонами, от которых исходил резкий запах серы и гнили. Весь сад пропах этим кошмаром. Агрономы разводили руками, почва и удобрения были в норме. Я поняла, что это не биология, а магия. Стала искать контакты сильного экстрасенса. Нашла отзывы о Владе Череватом, меня впечатлила его работа с темными энергиями. Записалась на онлайн-консультацию. Влад сказал, что моя завистливая соседка полила кусты водой, которой обмывали покойника, чтобы уничтожить мой труд. Ясновидящий дал мне строгие инструкции, какими травами окурить сад и как почистить землю солью. Я всё выполнила в точности. Следующая волна бутонов раскрылась идеальным белым цветом, запах серы исчез без следа.',5,1,'2026-03-23 19:15:00'),
('0b8bf109-2dbe-11f1-a618-1e4a3e6dea57','vlad-cherevatyy','Денис, 33','','Я Senior разработчик, пишу сложные программы. Но месяц назад начался ад. Ровно в 3:33 ночи огромный кусок моего кода просто удалялся с сервера. Я ставил защиты, делал бекапы на разные физические носители, менял пароли. Ничего не помогало. Код исчезал, как будто его стирал призрак. Из-за этого мы срывали релиз проекта стоимостью в миллионы. Я не спал неделями, почти сошел с ума. Мой тимлид в шутку предложил найти мага. Я от безысходности загуглил экстрасенс влад череватый отзывы официальный сайт. Узнал стоимость приема и записался. Влад принял меня онлайн. Он усмехнулся и сказал, что мой бывший коллега, уволенный со скандалом, навел техно-порчу через подаренную мне флешку, к которой привязал мелкого беса-вредителя. Влад Череватый провел ритуал экзорцизма этой флешки. Я ее разбил и сжег. Удаления кода прекратились в ту же ночь. Релиз сдан!',5,1,'2026-03-23 19:14:00'),
('0b8bf158-2dbe-11f1-a618-1e4a3e6dea57','vlad-cherevatyy','Мария, 27','','Это было похоже на фильм ужасов. Я шла по улице и случайно взглянула на витрину магазина. Мое отражение было одето в грязное, изодранное свадебное платье, хотя на мне были джинсы и футболка. Я остановилась в шоке, потерла глаза — отражение в платье смотрело на меня и плакало. Я начала панически бояться зеркал и окон. Вместе с этим от меня без причины ушел жених. Я поняла, что на меня навели какой-то жуткий морок. Подруга помогла найти контакты экстрасенса Влада Череватого. Мы оформили запись на личную встречу в Москве, так как я была в истерике. Влад посмотрел на меня и сказал, что это порча на одиночество и безумие, которую сделала бывшая моего жениха. Влад провел очень сложный, тяжелый ритуал с зеркалами, разрубив эту черную связь. Выходя от него, я посмотрела в зеркало в коридоре — и увидела обычную себя! Отражения больше не пугают, а жених вернулся с извинениями через месяц.',5,1,'2026-03-23 19:13:00'),
('0b8c25fe-2dbe-11f1-a618-1e4a3e6dea57','vlad-cherevatyy','Роман, 35','','Я столкнулся с невероятно странной проблемой. Любая моя обувь, даже самые дорогие итальянские ботинки, стиралась до дыр на левой подошве ровно за один день носки. Из-за этого перекоса у меня начались жуткие боли в спине и суставах. Ортопеды делали снимки, походка идеальная, ноги одинаковой длины. Я разорялся на обуви и обезболивающих. Моя мама сказала, что это порча на закрытие дорог. Я решил проверить эту версию и стал искать сильного мага. Влад Череватый из битвы экстрасенсов внушал доверие. Нашел официальный сайт, узнал цену и связался. На онлайн-консультации Влад подтвердил мамину догадку. Конкурент подбросил мне в кабинет заговоренную землю. Влад Череватый провел мощный дистанционный обряд отсечения негатива. Я купил новые кроссовки и ношу их уже три месяца — подошва стирается равномерно! Боли в спине тоже прошли.',5,1,'2026-03-23 19:12:00'),
('0b8c26bb-2dbe-11f1-a618-1e4a3e6dea57','vlad-cherevatyy','Алексей, 42','','Я ювелир с двадцатилетним стажем, делаю обручальные кольца на заказ. Внезапно все мои работы начали чернеть. Счастливые молодожены звонили мне в панике через неделю после свадьбы: золото 585 пробы темнело прямо на их пальцах, оставляя грязные следы. Я менял поставщиков металла, химичил с лигатурой, отдавал на экспертизу — золото было идеальным. Репутация рушилась, пошли возвраты. Я понимал, что прокляты мои руки или мастерская. Жена нашла отзывы про Влада Череватого. Мы узнали стоимость приема в Москве и поехали к нему. Влад просканировал меня и сказал, что это порча на разорение от старого конкурента, который навел ее через подаренные мне инструменты. Влад провел жесткий отжиг негатива с моих рук и мастерской. Я выбросил те инструменты. С тех пор ни одно кольцо не потемнело. Мой бизнес снова процветает.',5,1,'2026-03-23 19:11:00'),
('0b8c2719-2dbe-11f1-a618-1e4a3e6dea57','vlad-cherevatyy','Дарья, 34','','Я пишу детективные романы. В новой книге главного злодея я списала со своего токсичного бывшего отчима. И вдруг моя любимая дорогая перьевая ручка начала протекать черными чернилами исключительно тогда, когда я писала имя этого персонажа! Ручка пачкала руки, заливала страницы. При написании других слов она писала идеально. Я меняла чернила, чистила перо — бесполезно. Из-за этого я впала в творческий ступор. Поняла, что отчим как-то энергетически блокирует меня. Стала искать, как попасть на прием к Владу Череватому. Оставила контакт на сайте, нас свели онлайн. Влад сразу увидел эту гнилую связь. Отчим был сильным энергетическим вампиром и не давал мне закончить книгу, чувствуя угрозу разоблачения. Чернокнижник Влад обрубил этот вампирский канал и поставил мне защиту. В тот же вечер я дописала главу без единой кляксы. Книга стала бестселлером!',5,1,'2026-03-23 19:10:00'),
('0b8c2773-2dbe-11f1-a618-1e4a3e6dea57','vlad-cherevatyy','Елена, 29','','Мой муж был в ужасе, когда начал находить меня по ночам в гостиной. Я спала с открытыми глазами и плела из нашей одежды, штор и проводов странные, сложные корзины и узлы. Утром я ничего не помнила, а пальцы были стерты до мозолей. Неврологи ставили сомнамбулизм, но таблетки делали меня овощем днем, а ночью я снова плела эти жуткие узлы. Семья рушилась от недосыпа и страха. Мы стали искать сильного практика. Нашли информацию про Влада Череватого, узнали цену приема. Записались на онлайн-встречу. Влад посмотрел на фото этих узлов и сказал, что это древняя порча-наузница на сумасшествие, которую сделала свекровь, чтобы муж сдал меня в клинику. Влад Череватый провел сложнейший ритуал развязывания этих кармических узлов. Муж сжег все мои ночные поделки по его инструкции. Больше я по ночам не встаю, сплю спокойно.',5,1,'2026-03-23 19:09:00'),
('0b8c27c8-2dbe-11f1-a618-1e4a3e6dea57','vlad-cherevatyy','Кирилл, 31','','Я работаю на удаленке в своей квартире. Месяц назад мои умные часы начали показывать пульс 0 ударов в минуту, как только я садился за рабочий стол. При этом я чувствовал себя нормально, хотя и была легкая слабость. Я поменял трое часов разных брендов — результат один. В других комнатах или на улице пульс измерялся идеально. Я стал бояться своего рабочего места, продуктивность упала до нуля. Девушка сказала, что там явно зона мертвой энергии. Мы стали искать контакты экстрасенса. Выбрали Влада Череватого по хорошим отзывам. Узнали стоимость и записались онлайн. Ясновидящий попросил навести камеру на стол. Он сказал, что в кресло зашит подклад с кладбищенской землей — порча на застой в делах от бывшей девушки. Влад дистанционно провел чистку. Кресло я выбросил. На новом кресле часы показывают стабильные 70 ударов. Я снова работаю без страха.',5,1,'2026-03-23 19:08:00'),
('0b8c281f-2dbe-11f1-a618-1e4a3e6dea57','vlad-cherevatyy','Виктория, 30','','Моя карьера визажиста чуть не закончилась судом. Внезапно у трех моих клиенток подряд на следующий день после макияжа появилась жуткая аллергическая сыпь на лбу. Но самое страшное — сыпь была в форме четкого, ровного креста! Косметика была дорогой, гипоаллергенной, кисти стерилизовались. Девушки грозили мне полицией и судами, моя репутация была уничтожена. Я была в панике и отчаянии. Знакомая таролог посоветовала найти сильного чернокнижника, чтобы снять порчу на бизнес. Я нашла сайт Влада Череватого, оставила заявку. Нас проконсультировали онлайн. Влад сразу сказал, что конкурентка подменила мне флакон с мицеллярной водой, добавив туда настой с кладбищенского перекрестка. Влад Череватый провел мощный обряд очищения моего рабочего места и рук. Я полностью сменила все средства. Больше никаких крестов и аллергий ни у кого не было. Мое имя очищено, клиенты вернулись.',5,1,'2026-03-23 19:07:00'),
('0b8c28ba-2dbe-11f1-a618-1e4a3e6dea57','vlad-cherevatyy','Олег, 44','','Я коллекционирую редкий винил. В моей коллекции сотни пластинок. Но появилась пугающая аномалия: каждый раз, когда на улице начинался дождь, любая пластинка на моем дорогом проигрывателе начинала играть в обратную сторону! При этом диск крутился правильно. Из колонок доносились жуткие, сатанинские звуки. В сухую погоду всё играло нормально. Инженеры проверили аппаратуру — всё идеально. Я боялся находиться дома в непогоду. Жена забила тревогу и нашла экстрасенс влад череватый отзывы в интернете. Мы узнали, как попасть к нему, и записались. Влад принял нас онлайн. Он рассмеялся и сказал, что я купил с рук проклятую пластинку, к которой привязан мелкий бес, реагирующий на перепады атмосферного давления. Влад вычислил этот диск дистанционно и провел ритуал изгнания. Пластинку я сжег. Теперь в дождь я наслаждаюсь нормальной музыкой.',5,1,'2026-03-23 19:06:00'),
('0b8c4e62-2dbe-11f1-a618-1e4a3e6dea57','vlad-cherevatyy','Наталья, 38','','Наша семья перестала нормально питаться дома. Любой суп, который я варила, на вкус становился как пересоленная морская вода. Я вообще перестала добавлять соль, меняла воду, кастрюли, продукты — бесполезно. Муж и дети не могли это есть, мы стали питаться в кафе, тратя огромные деньги. В квартире появилась атмосфера скандалов и раздражения. Я поняла, что это порча на дом. Стала искать контакты магов, нашла официальный сайт Влада Череватого. Узнала стоимость приема, записалась. Влад по видеосвязи посмотрел на мою кухню и сразу сказал, что нам под дверь подлили мертвую воду со слезами вдовы. Это была порча на горе и слезы в семье. Чернокнижник Влад Череватый дал мне мощный ритуал очищения дома со свечами и полынью. Я всё вычистила. В тот же вечер я сварила борщ, и он был идеальным! Семья снова собирается за одним столом.',5,1,'2026-03-23 19:05:00'),
('0b8c4ecb-2dbe-11f1-a618-1e4a3e6dea57','vlad-cherevatyy','Алиса, 25','','Мой телефон сошел с ума. Я печатала обычные сообщения друзьям, а Т9 автозаменял русские слова на какие-то жуткие латинские заклинания. Я сбрасывала телефон до заводских настроек, меняла клавиатуры, даже купила новый смартфон — автозамена латынью продолжалась! Друзья пугались моих сообщений, парень решил, что я в секте. Жизнь превратилась в кошмар. Подруга силой заставила меня искать экстрасенса. Мы нашли Влада Череватого, так как он работает с бесами. Узнали цену и оставили заявку на онлайн-прием. Влад посмотрел на меня и сказал, что я случайно вступила в перепалку в сети с настоящим практиком темной магии, и тот кинул на меня цифрового беса-мороку. Влад провел жесткий ритуал отсечения этого паразита. Как только мы закончили сеанс, я написала сообщение маме — всё было на чистом русском языке без единого латинского слова. Моя психика спасена.',5,1,'2026-03-23 19:04:00'),
('0b8c4f1e-2dbe-11f1-a618-1e4a3e6dea57','vlad-cherevatyy','Павел, 40','','Я нашел на улице странную старую монету. Поднял ее, и она словно приросла к ладони. Монета начала адски жечь кожу, пахло паленым мясом. Но как только я пытался разжать пальцы и выбросить ее, у меня темнело в глазах, и я падал в обморок от резкого падения давления. Я ходил с зажатым кулаком трое суток, не спал от боли, рука опухла. Врачи хотели ампутировать пальцы, думая, что это неизвестная инфекция. Жена в панике начала звонить экстрасенсам. Мы нашли контакты Влада Череватого, умоляли о срочном приеме. Приехали в Москву. Ясновидящий Влад сразу увидел этот ужас. Это был страшный переклад смертельной болезни. Влад провел тяжелейший обряд с кровью и огнем, заставив сущность отпустить мою руку. Монета упала на пол черная как уголь. Боль исчезла мгновенно! Ожог зажил за пару недель. Если бы не он, я бы остался инвалидом.',5,1,'2026-03-23 19:03:00'),
('0b8c4f6f-2dbe-11f1-a618-1e4a3e6dea57','vlad-cherevatyy','Ксения, 28','','Я профессиональная балерина. Перед важнейшим конкурсом начался мистический саботаж: ленты на моих пуантах развязывались сами по себе ровно в тот момент, когда начинала играть музыка для моего выступления. Я завязывала их намертво, пришивала нитками — нитки лопались, ленты разлетались. Из-за этого я дважды жестко упала и чуть не сломала лодыжку. Конкурс был под угрозой, я рыдала в гримерке. Мой хореограф сказала, что это порча на провал. Я стала гуглить, где принимает Влад Череватый. Нашла сайт, узнала стоимость онлайн-консультации. Влад сразу назвал имя моей конкурентки из труппы, которая нашептала проклятие на мои ленты. Чернокнижник провел дистанционный ритуал очищения и поставил мне мощную защиту на ноги. На конкурсе ленты держались как железные, я оттанцевала идеально и взяла гран-при! Бесконечно благодарна Владу за помощь.',5,1,'2026-03-23 19:02:00'),
('0b8c4fbe-2dbe-11f1-a618-1e4a3e6dea57','vlad-cherevatyy','Артем, 39','','Я работаю сомелье в элитном ресторане. У нас была важная дегустация для иностранных инвесторов. Я открыл бутылку коллекционного вина за несколько тысяч евро, налил в бокал, попробовал — это был чистый уксус. Открыл вторую, третью — всё вино из этой партии превратилось в кислятину. При этом, когда я наливал вино обычному посетителю, оно было великолепным. Уксус появлялся только тогда, когда я обслуживал этих конкретных инвесторов. Сделка срывалась, меня хотели уволить с волчьим билетом. Я понял, что на сделку наложен морок. Стал искать сильного экстрасенса. Нашел отзывы о Владе Череватом, связался через Ватсап. На онлайн-приеме Влад сказал, что конкурент инвесторов сделал подклад-крадник на срыв всех их договоров. Ясновидящий дистанционно провел отжиг негатива с нашего ресторана и поставил щит. На следующей дегустации вино было божественным, инвесторы подписали контракт, а мне выписали огромную премию!',5,1,'2026-03-23 19:01:00'),
('0d2525f9-016c-4010-b7f2-9bd9db08e106','elena-golunova','Алексей, 39','','За один неполный год я умудрился попасть в четыре очень серьезные автомобильные аварии. Причем я опытный водитель с двадцатилетним безаварийным стажем, всегда езжу крайне аккуратно и по правилам. Машины разбивались просто в хлам, я чудом оставался жив, отделываясь тяжелыми переломами и сотрясениями мозга. Страховые компании уже отказывались со мной работать, внося в черные списки. Я стал панически бояться садиться за руль, начал ездить на такси. Мой лучший друг посоветовал обратиться к эзотерике, сказал, что это очень похоже на наведенное проклятие. Я начал гуглить \"экстрасенс новосибирск елена голунова\" и искать, как к ней можно попасть на консультацию. Оставил подробную заявку через официальную форму. На приеме Елена сразу, глядя мне в глаза, увидела истинную причину. Оказалось, я случайно перешел дорогу очень влиятельному и злому человеку в бизнесе, и он заказал на меня порчу на смерть именно через аварии на дороге. Елена сняла этот страшный негатив и поставила на меня мощную защиту. С тех пор прошло почти два спокойных года. Я снова вожу машину с удовольствием, и ни одной, даже самой мелкой царапины на бампере!',5,1,'2026-03-23 12:10:00'),
('13cbf47b-a9d5-4dc9-afe7-c180d4bbbf05','elena-golunova','Андрей, 44','','Меня неожиданно и подло обвинили в серьезном экономическом преступлении, которого я никогда не совершал. Бывшие партнеры по бизнесу подставили меня по полной программе, виртуозно сфабриковали финансовые документы. Мои дорогие адвокаты давали крайне неутешительные прогнозы — мне реально светил большой срок с конфискацией. Я был в полном отчаянии, не знал, что делать, семья в слезах готовилась к худшему исходу. Жена тайком от меня начала искать ясновидящую, чтобы хоть как-то прояснить ситуацию. Нашла официальную страницу Елены Голуновой, узнала, сколько стоят ее услуги, и записала меня на прием в Москве. Я шел туда без всякой надежды, просто чтобы успокоить истерзанную жену. Но то, что произошло в кабинете, не поддается никакой здравой логике. Экстрасенс в мельчайших деталях описала схему, по которой меня подставили, назвала имена людей, которые прятались в тени. Она дала четкий совет, где именно искать недостающие черновые документы, доказывающие мою абсолютную невиновность. И мы их нашли! В старом пыльном архиве, о котором все давно забыли. Суд меня полностью оправдал. Эта помощь была поистине бесценной.',5,1,'2026-03-23 12:12:00'),
('1f3c4b5f-45b0-4ccb-9a92-6524edf76799','elena-golunova','Екатерина, 27','','Мой семилетний сын начал просыпаться каждую божью ночь с дикими, истеричными криками. Он показывал пальцем в темный угол комнаты и плакал, что там стоит страшный черный человек и смотрит на него. Сначала мы с мужем думали, что это просто бурные детские фантазии и кошмары, водили к детскому неврологу, пили легкие успокоительные. Но становилось только хуже, ребенок начал таять на глазах, отказывался есть, боялся оставаться один даже ярким днем. Я была на грани нервного срыва. На одном форуме мамочек мне в личные сообщения посоветовали обратиться за нетрадиционной помощью. Я долго искала информацию, сверяла адреса. Выбор пал на Елену. Нашла ее контактный номер, написала длинное умоляющее сообщение. Администраторы вошли в наше тяжелое положение и нашли для нас окошко для онлайн-встречи. Елена Голунова работала с нами дистанционно. Она объяснила, что ребенок очень энергетически чувствительный и реально видит то, что мы не замечаем. Провела чистку квартиры и поставила мощную защиту на сына. В ту же ночь он впервые за долгое время спал спокойно до самого утра.',5,1,'2026-03-23 12:19:00'),
('2de6d40d-e727-41ac-b884-1ce1fe90dbb5','elena-golunova','Анна, 34','','Я была в полном отчаянии, когда поняла, что в нашей семье мужчины уходят один за другим. Сначала дед, потом отец, а когда брат попал в странную аварию, я поняла — это не просто злой рок. Знакомые посоветовали не тянуть и обратиться к специалисту, но я очень долго сомневалась, боялась нарваться на шарлатанов. Искала информацию в интернете, читала отзывы реальных людей, пока не наткнулась на имя экстрасенса Елены Голуновой. Сразу почувствовала, что мне нужна именно она. Нашла официальный сайт, оставила заявку на прием. Ждала ответа дня три, уже думала, что не получится попасть к ней. Но мне перезвонили! Консультация перевернула мою жизнь. Елена Валерьевна с первых минут сказала такие вещи о моем брате, которые никто, кроме нашей семьи, знать физически не мог. Она провела огромную работу. С тех пор прошло полгода. Брат полностью поправился, в семье наступило спокойствие. Я безмерно благодарна этой потрясающей женщине за то, что она помогла и вытащила нас из этого бесконечного кошмара.',5,1,'2026-03-23 12:25:00'),
('35f3b3fd-a80a-4b96-af4a-da172c165b38','elena-golunova','Юлия, 29','','Семь долгих лет мы с любимым мужем пытались завести ребенка. Прошли абсолютно все возможные медицинские обследования, сменили пять платных клиник, сделали два мучительных ЭКО — и все безрезультатно. Врачи только разводили руками и говорили: \"Вы оба абсолютно здоровы, пробуйте еще, ждите\". А у меня уже не было ни моральных, ни физических сил на эти ожидания. Я каждую ночь горько плакала в подушку, глядя на чужих детей. В какой-то момент я поняла, что традиционная медицина тут бессильна. Стала искать информацию про сильных экстрасенсов, читала отзывы реальных людей ночами напролет. Поняла, что внутренне доверяю только одному человеку. Елена Голунова — официальный сайт, короткая заявка, томительное ожидание своей очереди. На приеме Елена Валерьевна была сурова, но очень справедлива. Она увидела глубокую старую обиду моей матери на отца, которая неосознанно энергетически блокировала мое собственное материнство. Мы долго и тяжело работали над этим, я выполняла сложные духовные задания. Спустя четыре месяца после нашей совместной работы я увидела заветные две полоски на тесте! Сейчас нашей долгожданной доченьке уже полгода.',5,1,'2026-03-23 12:13:00'),
('37aa2cb9-ec38-47c6-aedd-b7db393aeb79','elena-golunova','Михаил, 45','','Всё началось с того, что мой бизнес, который я строил десять лет потом и кровью, начал рушиться буквально на глазах. Поставщики кидали, крупные клиенты уходили без объяснения причин, проверки шли одна за другой. Я не спал ночами, залез в огромные долги и кредиты. Жена, видя мое ужасное состояние, сама начала искать ясновидящую. Она всегда смотрела проект \"Битва сильнейших\", верила в это и настояла, чтобы мы попробовали. Я скептик до мозга костей, но терять было уже нечего. Мы узнали, сколько стоит прием, нашли официальный контакт и оформили запись. Когда я оказался у Голуновой в Москве, мой скептицизм испарился в первые же пять минут разговора. Она не задавала никаких наводящих вопросов, просто жестко и четко описала моего бывшего партнера, который, как оказалось, провел ритуал на разорение. Елена дала четкие инструкции, что делать дальше. Я выполнил всё до мелочей. Сейчас мои деньги снова работают, долги закрыты, а тот партнер сам оказался под следствием.',5,1,'2026-03-23 12:24:00'),
('413f559e-0648-44ac-b018-0a12cc355a79','elena-golunova','Роман, 28','','В свои 28 лет я внезапно и без видимых причин потерял абсолютно всякий интерес к жизни. Уволился с престижной, высокооплачиваемой работы, расстался с прекрасной невестой, полностью перестал общаться с друзьями. Я просто лежал целыми днями на диване в темной комнате и тупо смотрел в потолок. Врачи уверенно ставили клиническую депрессию, выписывали горсти антидепрессантов, но они делали из меня бесчувственного овоща. Моя мама в слезах умоляла меня попробовать нетрадиционные методы лечения. Она сама нашла контакты, выяснила, как принимает экстрасенс Елена Голунова, и организовала мне онлайн-консультацию. Мне было абсолютно все равно, я согласился только ради спокойствия матери. Но во время видеозвонка произошло нечто совершенно необъяснимое. Елена словно заглянула мне прямо в душу. Она увидела, что я по глупости забрал на себя чужой тяжелый кармический груз во время туристической поездки в аномальную зону пару лет назад. Она провела сложный ритуал отсечения этой связи. Буквально на следующее утро я проснулся с ясной головой, полным сил и забытым желанием жить. Сейчас я открыл свой успешный бизнес и снова по-настоящему счастлив.',5,1,'2026-03-23 12:08:00'),
('4b911668-3886-4918-8bd6-82b65a5c7f97','elena-golunova','Алиса, 26','','Наша долгожданная свадьба была полностью, до основания разрушена за неделю до самого торжества. Мой жених внезапно и без причин попал в реанимацию с неизвестной врачам инфекцией, выбранный нами ресторан сгорел ночью дотла, а у меня из закрытой квартиры украли дорогущее свадебное платье. Казалось, весь мир ополчился против нашего союза. Мама жениха была абсолютно уверена, что это сильный сглаз или порча от бывшей, очень завистливой девушки моего суженого. Мы решили не рисковать его жизнью и срочно обратиться к профессионалу. Узнали через знакомых, как записаться, сколько стоят услуги. Елена Голунова приняла нас по видеосвязи, так как я ни на шаг не могла отойти от жениха в больнице. Она сразу подтвердила, что на нас была сделана очень сильная, профессиональная порча на разрушение союза и болезни. Елена провела дистанционную чистку и велела мне самой сделать несколько простых, но очень важных защитных ритуалов. Вы не поверите, но жениху стало значительно лучше на следующий же день! Врачи были просто в шоке от такой быстрой, нереальной динамики выздоровления. Свадьбу мы в итоге сыграли очень скромно, в кругу семьи, но самое главное — мы вместе, живы и счастливы!',5,1,'2026-03-23 12:03:00'),
('56a1ec4d-d09a-4b6e-8731-d7f6e6232343','elena-golunova','Владимир, 42','','Кризис среднего возраста ударил по мне со страшной, разрушительной силой. В 42 года я с ужасом понял, что живу абсолютно чужую, навязанную мне жизнь. От работы физически тошнит, семья стала просто скучной привычкой, а внутри — звенящая, невыносимая пустота. Я начал по вечерам сильно пить, появились навязчивые мысли бросить всё, развестись и уехать жить в глушь одному. Пытался найти ответы и помощь у модных психологов, но это были просто пустые, долгие разговоры ни о чем. Мой старый друг посоветовал обратиться к человеку, который реально видит скрытое от обычных глаз. Я долго и скептически изучал официальный сайт Елены Голуновой, читал разные отзывы. Наконец, пересилил себя и оформил онлайн-встречу. Елена Валерьевна, известная мне по проекту битва сильнейших, с первых же суровых слов расставила всё по своим местам в моей голове. Она жестко указала мне на мое истинное предназначение, которое я упорно и трусливо игнорировал всю свою жизнь в угоду родителям и обществу. Она дала мне мощный энергетический толчок и вернула уверенность в себе. Я кардинально сменил сферу деятельности, занялся реставрацией старинной мебели. И знаете, жизнь заиграла такими яркими красками, о которых я даже и не мечтал в юности.',5,1,'2026-03-23 12:05:00'),
('6b22e663-b6a4-4306-b9a2-2105e4f04cb9','elena-golunova','Дарья, 32','','В нашем новом, долгожданном загородном доме начали происходить пугающие и странные вещи. Сначала мы с мужем списывали непонятные шаги на чердаке на мышей, а холодные, резкие сквозняки — на плохую строительную изоляцию. Но когда начали сами по себе включаться электроприборы среди ночи и с грохотом падать картины со стен, стало по-настоящему страшно. Мой пес сутками сидел забившись под кроватью и жалобно скулил, отказываясь есть. Жить там стало просто невыносимо, мы думали съезжать. Я начала гуглить, кто может помочь очистить дом от этой чертовщины. Поисковик выдал информацию, где принимает экстрасенс Елена Голунова. Я заполнила форму на сайте, чтобы связаться с ней. Мне перезвонили и назначили дату. Елена приехала к нам лично. Это было невероятно мощно и жутко одновременно. Она нашла гнилой подклад в фундаменте дома — кто-то из обиженных рабочих во время стройки заложил туда заговоренные предметы на разорение и беды хозяевам. После ее ритуалов дом словно выдохнул и ожил. Стало тепло, уютно, собака снова стала веселой и активной. Мы наконец-то можем спать спокойно в своем доме.',5,1,'2026-03-23 12:14:00'),
('85cf29e1-67e2-41b9-a8d4-35581e021e2f','elena-golunova','Мария, 35','','Бесконечные долги просто душили меня со всех сторон, не давая вздохнуть. Я брала новые микрозаймы, чтобы закрыть старые кредиты, работала на трех работах без выходных, но деньги словно утекали сквозь пальцы в никуда. Казалось, я попала в какую-то черную воронку бедности, из которой нет выхода. В какой-то момент появились самые страшные мысли от бессилия, настолько я устала бороться за выживание. Знакомая, видя мое жуткое состояние, дала мне контакт и сказала просто: \"Напиши ей, она вытаскивает и не из такого\". Это была ясновидящая Елена Голунова. Я очень сомневалась, боялась обмана, но все же решила рискнуть. Узнала стоимость приема, заняла последнюю возможную сумму у брата и записалась. Елена Валерьевна оказалась очень прямолинейным, волевым человеком. Она с ходу заявила, что у меня наглухо перекрыт финансовый канал из-за старой порчи на нищету, которую сделала бывшая свекровь. Работа была тяжелой физически и морально, я четко выполняла все ее строгие указания. Буквально через месяц мне неожиданно предложили высокооплачиваемую должность, о которой я даже мечтать боялась. Сейчас я полностью свободна от всех долгов и живу спокойно.',5,1,'2026-03-23 12:15:00'),
('89ec4166-34f0-48b4-8a17-566f051bc3af','elena-golunova','Елена, 36','','Я всегда нутром чувствовала, что свекровь меня тихо недолюбливает, но старалась не придавать этому значения ради мира в семье. Мы жили отдельно, виделись редко. Однако со временем отношения с любимым мужем стали резко и необъяснимо портиться. Он начал придираться по малейшим пустякам, стал необоснованно агрессивным, полностью перестал обращать на меня внимание как на любимую женщину. А однажды я случайно нашла в кармане его зимней куртки странный холщовый мешочек с сухими травами и землей. Тут-то мне и стало по-настоящему не по себе. Я стала искать в сети, что это может значить. Наткнулась на страшную информацию про кладбищенский приворот и черные рассорки. Решила, что медлить больше нельзя ни дня. Узнала номер телефона, по которому можно записаться к сильной колдунье Елене Голуновой. Цена приема меня совершенно не смутила, я спасала свою семью и мужа. Елена сразу подтвердила мои опасения — свекровь делала магические остуды, чтобы развести нас любой ценой. Мы провели глубокую чистку, я поставила зеркальную защиту на наш брак. Муж изменился до неузнаваемости, снова стал тем заботливым человеком, за которого я выходила замуж. А свекровь внезапно переехала жить в другой город и больше не лезет в нашу жизнь.',5,1,'2026-03-23 12:11:00'),
('a082a87c-d3e6-418b-bf0d-011414d6ac13','elena-golunova','Марина, 43','','Узнать о грязной измене мужа — это как получить неожиданный удар ножом в спину. Но когда я через общих знакомых узнала, что его молодая любовница обратилась к черной магии, чтобы окончательно увести его из семьи, мне стало по-настоящему страшно за его жизнь. Он стал сам на себя не похож: сильно похудел, перестал спать, постоянно болел непонятными простудами, но тянулся к ней как привязанный на невидимом поводке. Я поняла, что обычными слезами и уговорами тут точно не помочь. Стала внимательно изучать отзывы в интернете и искать сильного, проверенного мастера. Ясновидящая Елена Голунова сразу вызвала у меня доверие своей невероятной силой и бескомпромиссностью. Я нашла ее официальный сайт, уточнила стоимость приема в Москве и записалась на ближайшую дату. Елена Валерьевна подтвердила наличие черного приворота на муже, сделанного дилетантом, что было еще опаснее. Работа была очень долгой и тяжелой, мне самой пришлось многое переосмыслить в своем поведении. Но мы справились с этой бедой. Любовница навсегда исчезла из нашей жизни, муж восстановился физически, просил прощения на коленях со слезами. Наша семья спасена и сохранена.',5,1,'2026-03-23 12:09:00'),
('aae566ff-2c47-11f1-b559-6e7639eedb4b','oleg-sheps','Евгения, 34','','Я никогда не думала, что впаду в такую глубокую депрессию из-за работы. Я шла к должности финансового директора пять лет, а когда получила ее, внутри всё просто выгорело. Каждое утро я плакала в машине перед офисом. Я не понимала, что со мной происходит, ведь это была моя мечта! Психолог диагностировал выгорание, но отпуск не помог. Я чувствовала, что проблема зарыта где-то глубже. Знакомая посоветовала поискать помощи у людей, которые видят энергетику. Я давно следила за проектом битва сильнейших, и экстрасенс Олег Шепс всегда вызывал у меня симпатию своим современным подходом. Нашла его официальный сайт, узнала стоимость приема и оставила заявку. Ждала ответа дня три. Мы общались онлайн. Олег сразу увидел суть: я достигала этих высот не для себя, а чтобы доказать строжайшему отцу, что я чего-то стою. И когда цель была достигнута, моя личная энергия просто закончилась, потому что это был не мой путь. Он помог мне перестроить внутренние приоритеты и снять этот блок. Сейчас я ушла в консалтинг, работаю на себя и абсолютно счастлива.',5,1,'2026-03-23 17:25:00'),
('aae6ac92-2c47-11f1-b559-6e7639eedb4b','oleg-sheps','Илья, 42','','Мой строительный бизнес начал буксовать на ровном месте. Крупные заказчики внезапно отказывались от проектов на этапе подписания договоров, инвесторы замораживали финансирование. При этом сметы и качество у нас были лучшими в регионе. Я просто бился головой о невидимую стену. Нервы сдавали, начались ссоры с женой. Именно она настояла на том, чтобы мы обратились к специалисту. Она перерыла весь интернет, читала отзывы реальных людей и нашла информацию про Олега Шепса. Мы узнали, как записаться на прием в Москве. На личной встрече Олег не стал нагнетать мистику. Он просто поговорил со мной и просканировал мою ситуацию. Оказалось, я сам подсознательно блокировал развитие бизнеса из-за дикого страха повторить судьбу своего старшего брата, который обанкротился десять лет назад. Этот скрытый страх считывался партнерами на интуитивном уровне. Ясновидящий провел работу с моим подсознанием, снял эту разрушительную программу. Через месяц мы выиграли огромный тендер. Дела снова пошли в гору.',5,1,'2026-03-23 17:24:00'),
('aae7ef12-2c47-11f1-b559-6e7639eedb4b','oleg-sheps','Мария, 29','','Я попала в какой-то замкнутый круг в отношениях. Все мои романы развивались по одному и тому же сценарию: сначала безумная любовь, а через полгода мужчина начинал меня обесценивать, контролировать каждый шаг, и в итоге мы расставались со скандалом. Я чувствовала себя сломанной куклой и была уверена, что на мне какой-то сглаз на одиночество. Сестра скинула мне ссылку на официальный сайт Олега Шепса. Я очень сомневалась, но всё же решила написать в Ватсап его администраторам. Мне повезло, нашлось окно для онлайн-встречи. Олег Олегович сразу отмел все мои фантазии про порчи. Он очень мягко, но уверенно показал мне, что я сама излучаю энергию жертвы из-за глубоких детских травм, и именно эта неуверенность притягивает ко мне манипуляторов. Мы провели несколько сеансов, экстрасенс помог мне восстановить личные границы и поверить в свою ценность. Я полностью изменила свое поведение. Сейчас я встречаюсь с абсолютно адекватным, заботливым мужчиной.',5,1,'2026-03-23 17:23:00'),
('aae7f007-2c47-11f1-b559-6e7639eedb4b','oleg-sheps','Дмитрий, 38','','Никому не пожелаю пережить то чувство вины, которое сжирало меня после развода. Мы расстались с женой по моей инициативе, всё было честно, без измен, мы просто стали чужими людьми. Но после того, как я ушел, она впала в сильную депрессию, а я начал винить себя за разрушенную семью. Я не мог спать, не мог строить новые отношения, всё время оглядывался назад. Психотерапия давала лишь временное облегчение. Друг посоветовал обратиться к магам. Я стал искать в сети, где принимает экстрасенс Олег Шепс, так как слышал о нем много хорошего. Нашел официальный контакт, узнал цены и записался. Олег принял меня в Москве. Он не стал меня осуждать. Он объяснил, что между нами осталась мощная, нездоровая энергетическая привязка, основанная на жалости и чувстве долга, которая не дает жить нам обоим. Он провел ритуал отсечения этих деструктивных связей. Мне стало физически легче дышать прямо в его кабинете! Бывшая жена вскоре нашла новую работу, а я смог отпустить прошлое.',5,1,'2026-03-23 17:22:00'),
('aae7f074-2c47-11f1-b559-6e7639eedb4b','oleg-sheps','Светлана, 45','','Моя пятнадцатилетняя дочь стала для меня абсолютно чужим человеком. Она закрылась в себе, перекрасила волосы в черный цвет, начала грубить и постоянно сидела в телефоне. Любые мои попытки поговорить заканчивались истериками и хлопаньем дверьми. Я очень боялась, что она попала в плохую компанию или начала употреблять запрещенные вещества. В школе разводили руками. Я была в полном отчаянии и решила искать помощи у экстрасенсов, читала отзывы кто обращался с проблемами подростков. Выбрала Олега Шепса за его эмпатию. Узнала через сайт стоимость приема и записалась на онлайн-диагностику. Олег не просил приводить к нему дочь. Он настроился на ее энергетику через фотографию и рассказал мне то, от чего я разрыдалась. Оказалось, дочку сильно травили в классе из-за ее внешности, а она скрывала это от меня, боясь показаться слабой. Вся ее агрессия была защитной реакцией. Олег подсказал мне, какими именно словами начать с ней разговор, чтобы она открылась. Мы проговорили с ней всю ночь. Сейчас мы перевели ее в другую школу, и мой ребенок снова стал счастливым.',5,1,'2026-03-23 17:21:00'),
('aae7f0e7-2c47-11f1-b559-6e7639eedb4b','oleg-sheps','Антон, 31','','Я всегда был отличным специалистом, но как только дело доходило до публичных выступлений или защиты проектов перед руководством, меня накрывала паника. Голос дрожал, ладони потели, я забывал текст. Из-за этого меня несколько раз обходили с повышением, назначая руководителями более бойких, но менее компетентных коллег. Я ходил на курсы ораторского мастерства, но внутренний зажим никуда не уходил. Понял, что блок кроется на энергетическом уровне. Стал гуглить, как попасть на прием к Олегу Шепсу. Нашел его страницу, оставил свои данные. Мне перезвонили и назначили встречу. Олег сразу увидел, откуда растут ноги у моего страха. В младших классах учительница жестоко высмеяла меня перед всей школой на утреннике, и мое подсознание связало публичность с болью и унижением. Экстрасенс провел работу по перезаписи этой установки и наполнению меня уверенностью. На следующей же презентации я выступил так блестяще, что генеральный директор лично пожал мне руку. Должность начальника отдела теперь моя.',5,1,'2026-03-23 17:20:00'),
('aae7f14b-2c47-11f1-b559-6e7639eedb4b','oleg-sheps','Оксана, 27','','Бесконечные долги и кредитные карты душили меня, хотя я зарабатываю очень приличные деньги. Я просто не могла остановиться: скупала брендовую одежду, дорогую косметику, ненужные гаджеты. Как только на карту падали деньги, я испытывала физическую потребность их потратить. В итоге я оказалась в глубокой финансовой яме. Психологи говорили про компульсивное расстройство, но я не могла с собой справиться. Коллега дала мне совет обратиться к специалисту по энергетике. Я нашла отзывы про Олега Шепса, узнала, сколько стоят его услуги, и записалась на онлайн-консультацию. Олег Олегович был очень прямолинеен. Он сказал, что я пытаюсь заткнуть вещами огромную внутреннюю пустоту и отсутствие любви к себе. Я покупала не одежду, я покупала мимолетную эмоцию радости, потому что моя собственная энергия была на нуле. Он помог мне проработать эту травму и научил техникам наполнения себя без внешних костылей. Прошло полгода. Я закрыла половину кредитов и спокойно прохожу мимо торговых центров.',5,1,'2026-03-23 17:19:00'),
('aae80dbe-2c47-11f1-b559-6e7639eedb4b','oleg-sheps','Виктор, 50','','Кризис среднего возраста ударил по мне с невероятной силой. У меня была прекрасная семья, закрытая ипотека, стабильная работа, но я просыпался каждое утро с мыслью: Неужели это всё? Жизнь казалась пресной, серой, лишенной всякого смысла. Я забросил хобби, перестал общаться с друзьями, начал по вечерам злоупотреблять алкоголем. Жена, спасая меня, сама нашла в интернете официальный сайт Олега Шепса и записала меня на прием в Москве. Я поехал туда без всякого энтузиазма. Но экстрасенс буквально встряхнул меня. Он не стал жалеть меня, а жестко показал, что я живу по чужим сценариям, забыв про свои истинные желания, которые я похоронил еще в юности ради стабильности. Олег дал мне мощный энергетический импульс, пробудил забытые амбиции. Я вспомнил, как сильно любил столярное дело. Сейчас я арендовал небольшую мастерскую, делаю мебель на заказ, и у меня горят глаза! Я снова чувствую вкус к жизни.',5,1,'2026-03-23 17:18:00'),
('aae80e38-2c47-11f1-b559-6e7639eedb4b','oleg-sheps','Дарья, 33','','Мой синдром самозванца чуть не уничтожил мою карьеру. Меня пригласили на должность арт-директора в крупное международное агентство. Это был шанс всей жизни, но вместо радости я испытывала дикий, парализующий страх. Мне казалось, что я обманщица, что скоро все поймут мою некомпетентность и с позором уволят. Я работала по шестнадцать часов в сутки, перепроверяя каждую мелочь, и довела себя до нервного истощения. Мой парень понял, что я на грани срыва, и предложил нестандартный подход. Мы стали читать реальные отзывы про экстрасенсов, кто работает с психологическими блоками. Нам откликнулся Олег Шепс. Я оформила заявку на сайте. Пообщались онлайн. Олег очень четко считал мое состояние. Он увидел глубокий страх критики, который перекрывал мой творческий поток. Экстрасенс помог мне гармонизировать внутренние энергии, снял напряжение и научил доверять своей интуиции. Я успокоилась, перестала микроменеджить команду, и мои проекты стали выигрывать международные награды. Огромная благодарность.',5,1,'2026-03-23 17:17:00'),
('aae80e97-2c47-11f1-b559-6e7639eedb4b','oleg-sheps','Роман, 28','','Я музыкант, пишу музыку для рекламы и кино. Но полгода назад я просто сел за клавиши и понял, что внутри меня абсолютный вакуум. Я не мог написать ни одной стоящей мелодии, все звучало вторично и скучно. Заказчики начали уходить, я терял деньги и уверенность в себе. Пробовал менять обстановку, ездил в горы — не помогало. Творческий блок стоял намертво. Знакомая из тусовки посоветовала сходить к Олегу Шепсу, сказала, что он отлично помогает людям искусства. Я нашел его контакт, узнал стоимость приема и записался на личную встречу. Олег посмотрел на меня и сказал, что мой канал вдохновения забит бытовым негативом и завистью коллег, с которыми я недавно разорвал контракт. Они буквально пожелали мне пустоты. Ясновидящий провел чистку моей энергетики и снял эти ментальные оковы. Я приехал домой, сел за инструмент, и музыка просто полилась из меня сама! Я написал лучший саундтрек в своей жизни за одну ночь.',5,1,'2026-03-23 17:16:00'),
('aae80eed-2c47-11f1-b559-6e7639eedb4b','oleg-sheps','Алина, 36','','Моя свекровь методично разрушала мою жизнь. Она не использовала магию, она просто действовала психологически: постоянно критиковала меня при муже, давала непрошеные советы, приходила в наш дом как хозяйка. Муж разрывался между нами, но чаще принимал ее сторону, чтобы избежать скандалов. Я чувствовала себя чужой в собственной семье, началась бессонница. Я не знала, как выстроить границы, не разрушив брак. Стала искать помощь в сети. Узнала, где принимает Олег Шепс, и оставила заявку на официальном сайте. На онлайн-консультации Олег всё разложил по полочкам. Он объяснил, что свекровь энергетически вампирит меня, провоцируя на эмоции, а я покорно отдаю ей свои силы. Он не делал никаких отворотов, он просто научил меня правильно выстраивать энергетический щит и реагировать на ее слова так, чтобы она теряла к этому интерес. Я начала применять его техники. И чудо произошло: как только я перестала внутренне реагировать, свекровь резко сократила свои визиты и стала общаться со мной гораздо уважительнее.',5,1,'2026-03-23 17:15:00'),
('aae80f4d-2c47-11f1-b559-6e7639eedb4b','oleg-sheps','Кирилл, 39','','Полгода назад я попал в дурацкую аварию — просто притерлись бамперами в пробке. Никто не пострадал, ущерб минимальный. Но с того дня у меня появился панический страх вождения. Я садился за руль, и у меня начинали трястись руки, сердце колотилось, я не мог дышать. Пришлось поставить машину в гараж и ездить на метро, теряя кучу времени. Я злился на себя, но ничего не мог поделать. Психологи не помогали. Коллега на работе посоветовал найти сильного экстрасенса. Я пересмотрел отзывы кто обращался с фобиями и выбрал Олега Шепса. Узнал цену и записался в Москве. Олег объяснил, что во время удара я испытал микро-шок, и мое подсознание записало машину как источник смертельной угрозы, заблокировав эту сферу. Он провел очень глубокий сеанс, очистив эмоциональный фон от этого переживания. На следующий день я с замиранием сердца взял ключи, завел машину... и абсолютно спокойно доехал до офиса. Страх испарился!',5,1,'2026-03-23 17:14:00'),
('aae80fa9-2c47-11f1-b559-6e7639eedb4b','oleg-sheps','Надежда, 41','','Я годами безуспешно боролась с лишним весом. Диеты, тренажерные залы, марафоны похудения — я скидывала пять килограмм и набирала десять. Моя жизнь превратилась в вечную борьбу с холодильником. Любой стресс на работе я моментально заедала. Эндокринологи разводили руками, гормоны были в норме. Я поняла, что пищевая зависимость сидит в голове. Стала искать нетрадиционные методы. Нашла страницу экстрасенса Олега Шепса, отзывы людей меня очень воодушевили. Связалась через Ватсап, договорилась об онлайн-приеме. Олег Олегович не стал говорить мне про калории. Он увидел, что мой жир — это энергетическая броня, которой я защищаюсь от внешнего мира после тяжелого предательства в прошлом. Я боялась снова стать привлекательной, чтобы не столкнуться с мужским вниманием и новой болью. Мы проработали эту застарелую травму. После сеансов у меня просто исчезла тяга к заеданию эмоций. Я начала худеть легко и естественно, без насилия над собой.',5,1,'2026-03-23 17:13:00'),
('aae83377-2c47-11f1-b559-6e7639eedb4b','oleg-sheps','Сергей, 35','','Моя прокрастинация дошла до катастрофических масштабов. Я брал отличные, дорогие проекты на фрилансе, и просто не мог заставить себя их начать. Я смотрел сериалы, убирал квартиру, делал что угодно, лишь бы не садиться за работу. В итоге срывал сроки, извинялся, терял клиентов и репутацию. Я считал себя просто ленивым неудачником. Девушка, видя мои страдания, записала меня к Олегу Шепсу, так как знала о нем по битве сильнейших. Я пошел на прием в Москве без особой веры. Но Олег перевернул мое сознание. Он объяснил, что это не лень, а колоссальный подсознательный страх успеха. Я боялся, что если сделаю всё идеально, ко мне будут предъявлять еще более высокие требования, с которыми я не справлюсь. Эта установка блокировала мою волю. Экстрасенс помог мне разорвать этот порочный круг мыслей и вернуть контроль над своей энергией. Я пришел домой и за вечер закрыл проект, который висел месяц. Сейчас я работаю продуктивно и без срывов.',5,1,'2026-03-23 17:12:00'),
('aae83400-2c47-11f1-b559-6e7639eedb4b','oleg-sheps','Татьяна, 48','','Когда мой младший сын уехал учиться в другой город, моя жизнь потеряла смысл. Я стала классической жертвой синдрома опустевшего гнезда. Я бродила по пустой квартире, плакала над детскими фотографиями, постоянно звонила детям, раздражая их своей гиперопекой. Отношения с мужем испортились, мы стали как соседи. Я чувствовала себя старой и никому не нужной. В интернете я случайно наткнулась на официальный сайт Олега Шепса и решила, что мне нужен свежий взгляд на мою жизнь со стороны. Узнала стоимость приема, записалась онлайн. Олег был невероятно чутким. Он показал мне, что я всю свою энергию вливала в детей, абсолютно забыв о себе. Он помог мне перенаправить этот энергетический поток внутрь, на свое собственное развитие. Я записалась на курсы ландшафтного дизайна, о которых мечтала двадцать лет, мы с мужем начали путешествовать по выходным. Олег вернул мне меня саму. Я безмерно благодарна.',5,1,'2026-03-23 17:11:00'),
('aae83455-2c47-11f1-b559-6e7639eedb4b','oleg-sheps','Павел, 30','','Мы с родной сестрой всегда недолюбливали друг друга, но после смерти отца наши отношения превратились в открытую войну. Мы ругались из-за каждой мелочи, делили наследство с криками и взаимными оскорблениями. Я чувствовал, что эта злоба выжигает меня изнутри, у меня начались проблемы с желудком на нервной почве. Но уступить я не мог из принципа. Моя невеста не выдержала этих скандалов и поставила условие: либо я решаю эту проблему, либо мы расстаемся. Она же и дала мне контакт Олега Шепса. Я нашел информацию, как попасть на прием. На личной встрече экстрасенс не стал разбирать наши юридические вопросы. Он сказал, что мы с сестрой делим не деньги, мы до сих пор бьемся за любовь и внимание отца, которого нам обоим не хватало в детстве. Это осознание ударило меня как током. Олег помог мне отпустить эту детскую обиду и снять энергетический блок. Я первый позвонил сестре и извинился. Мы смогли спокойно договориться и сохранили родственные связи.',5,1,'2026-03-23 17:10:00'),
('aae834f5-2c47-11f1-b559-6e7639eedb4b','oleg-sheps','Екатерина, 32','','За месяц до долгожданной свадьбы меня накрыла дикая, необъяснимая паника. Я смотрела на свое свадебное платье и начинала задыхаться от ужаса. Мне хотелось отменить торжество, сбежать, бросить любимого человека, хотя объективных причин для этого не было — жених был идеальным. Я изводила его своими сомнениями, мы начали ругаться. Я не понимала, что со мной происходит. Подруга посоветовала найти ясновидящего, чтобы разобраться в себе. Отзывы реальных людей привели меня к Олегу Шепсу. Я оставила заявку на официальном сайте, меня проконсультировали онлайн. Олег Олегович сразу увидел корень проблемы. Оказалось, это сработала мощная психосоматика и родовая травма — мои родители развелись с жутким скандалом, когда я была маленькой, и мое подсознание связало брак с болью и разрушением. Экстрасенс провел глубокую работу, успокоил мой энергетический фон и помог разделить мой путь и путь родителей. Паника отступила. Свадьба прошла великолепно, и сейчас я абсолютно счастлива в браке.',5,1,'2026-03-23 17:09:00'),
('aae8355c-2c47-11f1-b559-6e7639eedb4b','oleg-sheps','Максим, 44','','Я оказался в очень странной ситуации. Пытался продать свою старую машину почти полгода. Цену снизил уже до смешного, перекупы звонили, приезжали, смотрели и... уезжали без объяснения причин. Машина была в хорошем техническом состоянии, но как будто заколдованная. Эта машина была связана у меня с очень тяжелым периодом в жизни: я ездил на ней в больницу к больной матери, в ней же переживал тяжелый развод. Знакомый автомеханик в шутку сказал, что тачка пропитана моими слезами, вот ее и не берут. Я воспринял это всерьез и стал искать экстрасенса. Нашел, где принимает Олег Шепс в Москве, узнал цену и записался. Олег посмотрел на фото машины и подтвердил: металл отлично впитывает энергетику, и машина буквально фонила тяжестью и депрессией, что отпугивало людей на интуитивном уровне. Он дистанционно провел энергетическую чистку автомобиля и посоветовал мне самому мысленно с ней попрощаться. Я сделал всё, как он сказал. Вы не поверите, через два дня приехал парень и забрал машину вообще без торга.',5,1,'2026-03-23 17:08:00'),
('aae835b4-2c47-11f1-b559-6e7639eedb4b','oleg-sheps','Валерия, 26','','Всю свою сознательную жизнь я чувствовала себя паршивой овцой в семье. Мои родители и старший брат — успешные юристы, люди строгих правил. А я творческий человек, художник, вечно витающая в облаках. Меня постоянно критиковали, обесценивали мои достижения, давили авторитетом. Из-за этого у меня развился жуткий комплекс неполноценности, я боялась выставлять свои работы, перебивалась случайными заработками. Я понимала, что мне нужно сепарироваться, но эмоционально была привязана к их одобрению. Решила обратиться за помощью к Олегу Шепсу, так как видела, как тонко он работает с психологией в битве сильнейших. Оформила онлайн-запись на официальном сайте. Олег был очень эмпатичен. Он помог мне обрезать эти нездоровые энергетические путы, через которые семья подавляла мою волю. Он вернул мне веру в мой талант. После наших сеансов я наконец-то смогла сказать родителям нет и переехала в другой город. Сейчас я готовлю свою первую персональную выставку!',5,1,'2026-03-23 17:07:00'),
('aae854ec-2c47-11f1-b559-6e7639eedb4b','oleg-sheps','Олег, 37','','Я просто сжигал свои деньги собственными руками. Каждая моя попытка инвестировать или открыть новый проект заканчивалась полным крахом. Я вкладывался в акции прямо перед их падением, открывал кофейню прямо перед локдауном. Друзья уже шутили, что я ходячий анти-индикатор успеха. Но мне было не до смеха, я терял накопления семьи. Я понимал, что дело не в экономике, а в моем каком-то внутреннем магните для неудач. Стал искать помощи. Отзывы про Олега Шепса меня очень заинтересовали. Узнал стоимость услуг, записался на прием. На встрече Олег Олегович сразу вытащил наружу мой глубокий внутренний конфликт: я подсознательно ненавидел богатых людей из-за старой семейной установки, что большие деньги — это грязь и опасность. Мое подсознание просто спасало меня от этой грязи, заставляя терять прибыль. Экстрасенс помог мне перепрограммировать это убеждение. Спустя несколько месяцев я сделал очень удачное вложение, которое принесло отличный доход. Черная полоса закончилась.',5,1,'2026-03-23 17:06:00'),
('aae8556b-2c47-11f1-b559-6e7639eedb4b','oleg-sheps','Юлия, 40','','Я жила с огромным камнем на душе. Три года назад меня жестоко предала лучшая подруга, с которой мы дружили со школы. Она поступила очень подло в финансовом вопросе. Мы перестали общаться, но я не могла ее простить. Эта злоба и обида сжирали меня каждый день. Я вела с ней мысленные диалоги, засыпала в гневе. У меня начались серьезные проблемы с желчным пузырем, врачи говорили, что это от нервов. Я поняла, что эта ненависть убивает меня саму. Стала искать, кто может помочь отпустить обиду. Нашла официальный сайт экстрасенса Олега Шепса. Записалась на онлайн-консультацию. Олег очень мягко показал мне, как эта энергетическая зацепка вытягивает мои жизненные силы. Он не заставлял меня ее любить, он просто помог мне забрать свою энергию обратно и обрубить этот канал. Я проплакала весь сеанс, но потом почувствовала невероятное облегчение. Боли в правом боку прошли, а я больше ни разу не вспоминала о той женщине.',5,1,'2026-03-23 17:05:00'),
('aae855c7-2c47-11f1-b559-6e7639eedb4b','oleg-sheps','Артем, 25','','Я профессиональный легкоатлет, бегаю спринт. Был в отличной форме, готовился к важному чемпионату. Но на одной из тренировок получил обидную, нелепую травму мышцы. Физически я восстановился за месяц, врачи дали зеленый свет. Но психологически я сломался. Как только я вставал на стартовые колодки, у меня начиналась паника, ноги становились ватными, я боялся снова порвать мышцу и показывал ужасное время. Тренер разводил руками. Моя спортивная карьера висела на волоске. Знакомый спортивный психолог неформально посоветовал мне обратиться к Олегу Шепсу. Я узнал, как попасть на прием в Москве. На личной встрече Олег объяснил, что мое тело запомнило боль, и этот энергетический спазм блокирует мои физические возможности. Экстрасенс провел мощную работу по очищению моего ментального поля от страха и вернул мне настрой победителя. На первых же соревнованиях после сеанса я побил свой личный рекорд! Я вернулся в спорт сильнее, чем был.',5,1,'2026-03-23 17:04:00'),
('aae85624-2c47-11f1-b559-6e7639eedb4b','oleg-sheps','Лидия, 52','','Моя квартира превратилась в склад ненужных вещей. Я не могла выбросить абсолютно ничего: старые билеты, порванную одежду, сломанную технику, сувениры от бывших коллег. Мне казалось, что если я это выброшу, я потеряю часть своей жизни. Эта привычка появилась после смерти мужа. Квартира задыхалась от хлама, а я задыхалась в ней, страдая от одиночества и хронической усталости. Дочь ругалась со мной, пыталась навести порядок, но у меня начинались настоящие истерики. Она же и записала меня на онлайн-прием к Олегу Шепсу, оплатив стоимость консультации. Олег Олегович был невероятно терпелив. Он объяснил, что я пытаюсь законсервировать прошлое, потому что боюсь будущего, а старые вещи хранят мертвую энергетику, которая не пускает в мою жизнь ничего нового. Он дал мне силы и психологическую поддержку, чтобы начать отпускать прошлое. После его сеансов я сама собрала и вынесла на помойку десять мешков хлама. В квартире стало легко дышать, и я впервые за много лет захотела сделать ремонт и пригласить гостей.',5,1,'2026-03-23 17:03:00'),
('aae85680-2c47-11f1-b559-6e7639eedb4b','oleg-sheps','Константин, 34','','Я застрял в своем маленьком родном городе. Мне предложили потрясающую работу в Москве, о которой я мечтал годами: отличная зарплата, перспективы, крутая компания. Но я тянул с ответом неделями. Меня сковал животный страх. Я боялся, что не справлюсь, что большой город меня сломает, что я останусь там один. Из-за этих сомнений я начал плохо спать и срываться на близких. Я понимал, что если откажусь, то буду жалеть об этом до конца жизни. Мой друг посоветовал мне найти ясновидящего, чтобы разобраться в себе. Отзывы про Олега Шепса привели меня на его официальный сайт. Оставил контакт в Ватсап, дождался онлайн-сеанса. Олег сразу увидел мою проблему. Он сказал, что мой страх — это иллюзия, навязанная гиперопекающей матерью, которая всегда говорила, что я без нее пропаду. Он помог мне обрезать этот энергетический поводок и дал огромный заряд уверенности в собственных силах. На следующий день я подписал оффер и купил билет в Москву. Сейчас я успешно работаю и счастлив, что решился!',5,1,'2026-03-23 17:02:00'),
('aae856db-2c47-11f1-b559-6e7639eedb4b','oleg-sheps','Анна, 38','','Мой брак трещал по швам из-за моего собственного поведения. У меня замечательный, любящий муж, но я постоянно устраивала ему скандалы на пустом месте. Я придиралась к мелочам, провоцировала его на конфликты, а потом сама же плакала и просила прощения. Это был какой-то изматывающий эмоциональный аттракцион. Муж устал и предложил пожить отдельно. Я была в ужасе от перспективы развода. Психотерапевт диагностировал тревожное расстройство, но разговоры не помогали изменить реакции. Я решила искать экстрасенса. Нашла информацию про Олега Шепса, узнала цены и записалась на личный прием. Олег посмотрел на меня и сразу выявил суть: у меня был глубочайший, панический страх быть брошенной. Своими скандалами я подсознательно проверяла мужа на прочность — выдержит ли он меня такую плохую, не уйдет ли. Экстрасенс провел работу по гармонизации моего эмоционального фона, успокоил эту внутреннюю истерику и помог обрести уверенность в себе. Я перестала изводить мужа, в наш дом вернулись спокойствие и любовь. Огромное спасибо!',5,1,'2026-03-23 17:01:00'),
('ac523ed0-d549-4940-a3fa-7f889645f9ae','elena-golunova','Сергей, 55','','Мое личное обращение к этому выдающемуся человеку было связано с очень деликатной, опасной и сложной бизнес-ситуацией, о которой я до сих пор не могу говорить открыто и в деталях. На кону стояли не только моя многолетняя деловая репутация и огромные деньги, но и физическая безопасность всей моей семьи. Мои беспринципные конкуренты играли не по правилам, используя мощное, целенаправленное негативное воздействие через черных магов. Я человек очень прагматичный, привык верить только цифрам, но когда факты говорят сами за себя, приходится верить в невидимое. Изучил официальный сайт, посмотрел отзывы серьезных людей. Елена Голунова — это не просто известный экстрасенс с экрана телевизора, это настоящий, несгибаемый воин света. Попасть на прием было крайне непросто, запись на месяцы вперед, но мне пошли навстречу из-за критичной срочности вопроса. То, как она работает, вызывает глубочайшее, искреннее уважение. Она не только быстро нейтрализовала нависшую угрозу, но и поставила такую железобетонную защиту на мой бизнес и близких, что теперь любые нападки и происки конкурентов просто отскакивают от меня. Я искренне благодарен Елене Валерьевне за ее титанический труд, абсолютную честность и невероятную силу. Она реально спасает человеческие судьбы на краю пропасти.',5,1,'2026-03-23 12:01:00'),
('ad91ae5f-2db8-11f1-a618-1e4a3e6dea57','zuliya-radzhabova','Маргарита, 42','','Я хочу сказать огромное, искреннее спасибо за то, что моя семья не оказалась на улице с огромными долгами. Мой муж, человек абсолютно равнодушный к азарту, внезапно начал играть в онлайн-казино. Сначала по мелочи, а потом стал спускать всю зарплату, набрал микрозаймов. У него были стеклянные глаза, он перестал общаться с детьми, постоянно сидел в телефоне. Мы были на грани развода и потери единственного жилья. Я плакала ночами, не понимая, как идеальный отец превратился в игромана за пару месяцев. Сестра посоветовала не рубить сплеча и поискать мистическую причину, напомнила про шоу битва экстрасенсов, которое мы раньше часто смотрели. Я стала искать информацию в сети и наткнулась на отзывы о Зулии Раджабовой. Зашла на ее официальный сайт, чтобы узнать, как попасть на прием. Ждала ответа с замиранием сердца. На онлайн-консультации ясновидящая сразу сказала, что это не просто зависимость. Муж случайно перешел дорогу конкуренту по бизнесу, и тот сделал сильный переклад разорения через подклад в его рабочем столе. Зулия дистанционно провела сложнейшую работу по очищению финансового канала мужа и снятию этой черной зависимости. Спустя две недели он сам в ужасе удалил все приложения и заблокировал счета. Долги мы сейчас потихоньку отдаем, но главное — он вернулся в семью!',5,1,'2026-03-23 18:25:00'),
('ad91cfd4-2db8-11f1-a618-1e4a3e6dea57','zuliya-radzhabova','Ольга, 28','','Если честно, я вообще не верила в магию и порчи, пока не столкнулась с этим лично. У меня всегда были шикарные, длинные волосы ниже талии, моя главная гордость. Но около полугода назад начался кромешный ад. Каждое утро я просыпалась с тем, что мои волосы на затылке сбивались в плотный, непробиваемый колтун. Я распутывала его часами со слезами и бальзамами, вырывая куски волос, а на следующее утро всё повторялось снова. Трихологи выписывали дорогие маски, но ничего не менялось. Пришлось обрезать волосы под каре, но колтуны стали появляться даже на коротких прядях! Я впала в глубокую депрессию, стала постоянно носить шапки. Подруга, увидев мои слезы, сказала, что это классический ведьмин сглаз. Мы стали гуглить экстрасенс зулия раджабова отзывы, так как она славится работой с тяжелой женской энергетикой. Нашли контакты, узнали стоимость приема и записались. Зулия Раджабова приняла меня в Москве. Она даже не стала задавать лишних вопросов, просто посмотрела на меня и сказала, что это дело рук моей бывшей свекрови, которая люто ненавидела меня за развод с ее сыном. Ясновидящая провела мощный обряд отсечения негатива. После этого сеанса мои волосы перестали путаться вообще! Сейчас я снова их отращиваю, и они идеально гладкие.',5,1,'2026-03-23 18:24:00'),
('ad91d080-2db8-11f1-a618-1e4a3e6dea57','zuliya-radzhabova','Николай, 45','','Всё началось с того, что моя небольшая частная пекарня оказалась на грани полного краха. Мы пекли лучший хлеб в районе, использовали дорогие фермерские продукты, лучшие дрожжи. Но внезапно тесто просто перестало подниматься. Оно превращалось в тяжелый, кислый камень. Мы меняли поставщиков муки, уволили технолога, вызывали мастеров для проверки всех печей — оборудование было абсолютно исправно. Я терпел колоссальные убытки, выбрасывая по сто килограмм сырого теста каждый божий день. Жена в слезах сказала, что это не физика, а чья-то черная зависть. Я человек прагматичный, но от безысходности решил проверить эту странную версию. Стал искать, как записаться на прием к сильному специалисту. Вышел на контакты Зулии. Узнал через телефон цену услуг. Ясновидящая согласилась посмотреть наше помещение по видеосвязи. Зулия сразу, не раздумывая, указала на вентиляционную решетку над главным тестомесом. Мы сняли ее и обомлели: там лежал маленький мешочек с могильной землей и ржавыми гвоздями. Конкуренты из соседней сетевой булочной сделали подклад на разорение бизнеса. Экстрасенс Зулия Раджабова дистанционно почистила наше помещение и поставила зеркальную защиту. На следующий день тесто поднялось как сумасшедшее! Пекарня спасена, клиенты снова с нами.',5,1,'2026-03-23 18:23:00'),
('ad91d0f2-2db8-11f1-a618-1e4a3e6dea57','zuliya-radzhabova','Светлана, 33','','Сейчас я четко понимаю, что это было настоящее спасение свыше. Моя новорожденная дочка категорически отказывалась брать грудь. Как только я пыталась ее покормить, она начинала дико выгибаться, кричать до посинения, словно молоко было отравлено. При этом из бутылочки она ела смесь абсолютно спокойно. Врачи-педиатры разводили руками, говорили про особенности строения или колики, консультанты по грудному вскармливанию ничем не смогли помочь. Мое молоко перегорало, я рыдала сутками напролет от бессилия и чувства вины. Моя бабушка посмотрела на это и сказала, что на мне сильная остуда материнства. Она сама нашла в интернете официальный сайт, где можно было связаться с экстрасенсом. Мы решили обратиться к Зулии Раджабовой. Оставили заявку на онлайн-консультацию из-за срочности. Зулия была невероятно эмпатична. Она увидела, что во время беременности моя бывшая, бездетная подруга из лютой зависти сделала мне переклад пустоты через подаренные пинетки. Ясновидящая провела очень мягкую, но мощную чистку моего биополя и разорвала этот черный канал. Я не могла в это поверить, но буквально через час после сеанса дочка спокойно взяла грудь и уснула! Это настоящее чудо.',5,1,'2026-03-23 18:22:00'),
('ad91f353-2db8-11f1-a618-1e4a3e6dea57','zuliya-radzhabova','Виктор, 39','','Хочу поделиться своей историей, которая едва не стоила мне успешной карьеры. Я работаю архитектором, проектирую сложные здания. И вдруг у меня развилась дикая, необъяснимая фобия открытых дверей. Я не мог находиться в помещении, если там не были плотно закрыты и заперты все двери. На совещаниях у меня начинались панические атаки, нехватка воздуха, если кто-то оставлял дверь в кабинет приоткрытой. Я срывал важные переговоры, бегал закрывать за всеми двери. Коллеги стали смотреть на меня как на сумасшедшего, руководство намекало на увольнение по медицинским показаниям. Психиатр выписал сильные транквилизаторы, от которых я просто спал на ходу. Моя девушка спасла меня. Она стала читать отзывы кто обращался со странными фобиями к магам. Нас очень впечатлила Зулия Раджабова. Мы узнали стоимость, записались на личную встречу в Москве. Зулия посмотрела на меня и сказала: Ты боишься не дверей, ты боишься того, что за ними. Оказалось, я случайно принес с объекта старый заговоренный ключ, который открыл в моем поле энергетический портал для низших сущностей. Экстрасенс провела ритуал запечатывания и уничтожила этот предмет. Страх исчез в тот же день без следа!',5,1,'2026-03-23 18:21:00'),
('ad91f478-2db8-11f1-a618-1e4a3e6dea57','zuliya-radzhabova','Екатерина, 27','','Мой идеальный жених превратился в агрессивного монстра ровно за месяц до нашей долгожданной свадьбы. Человек, который пылинки с меня сдувал, вдруг начал кричать по любому мелкому поводу, оскорблять меня, а однажды в ярости разбил зеркало в прихожей кулаком. В его глазах была какая-то стеклянная, звериная злоба. Я собирала вещи в слезах, отменяла ресторан, не понимая, как я могла так ошибаться в человеке целых три года. Моя будущая свекровь, золотая женщина, умоляла меня не спешить. Она была уверена, что его приворожили. Мы стали срочно искать сильную ясновидящую. Нашли страницу Зулии Раджабовой, меня впечатлил ее опыт в битва экстрасенсов. Связались с администраторами, оформили запись на прием онлайн, так как я боялась выходить из дома. Зулия сразу всё подтвердила — на жениха был сделан очень грязный, кладбищенский приворот на крови. Сделала его бывшая девушка, которая решила разрушить нашу жизнь. Зулия Раджабова провела сложнейший обряд очищения и снятия этого морока. Первые два дня жениху было физически плохо, его трясло, но потом он проснулся с ясной головой. Он плакал на коленях, прося прощения. Свадьбу мы сыграли, сейчас ждем первенца!',5,1,'2026-03-23 18:20:00'),
('ad91f4ed-2db8-11f1-a618-1e4a3e6dea57','zuliya-radzhabova','Денис, 34','','Никому не пожелаю пережить то, что происходило со мной каждый вечер пятницы. Я работаю менеджером, возвращаюсь домой одним и тем же маршрутом. Но полгода назад я начал терять память именно по пятницам. Я выходил из офиса, шел к метро, а дальше — темнота. Очухивался я глубокой ночью на другом конце города, без телефона, без денег, грязный и замерзший. Я не помнил, где был и что делал. Врачи подозревали микроинсульты, делали МРТ, но мозг был абсолютно здоров. Жена думала, что я завел любовницу или начал пить, хотя я вообще не употребляю алкоголь. Семья рушилась. Мой брат посоветовал не игнорировать мистику и найти экстрасенса. Мы стали гуглить отзывы о Зулии Раджабовой. Зашли на официальный сайт, узнали цены и записались. На встрече в Москве Зулия была очень серьезна. Она сказала, что на меня навели порчу на блуд и потерю разума. Это сделала женщина, которой я когда-то отказал в повышении. Ясновидящая провела жесткий ритуал отсечения этого воздействия и поставила зеркальную защиту. С тех пор прошло четыре месяца. Я спокойно возвращаюсь домой каждый день, провалы в памяти больше не повторялись ни разу.',5,1,'2026-03-23 18:19:00'),
('ad91f557-2db8-11f1-a618-1e4a3e6dea57','zuliya-radzhabova','Алина, 31','','Я профессиональная танцовщица, солистка балета. Мои ноги — это мой хлеб и смысл всей жизни. И в самом разгаре театрального сезона у меня начались дикие, нестерпимые боли в икрах. Боль была такой, словно мне в мышцы вбивают раскаленные гвозди. Я не могла стоять на пуантах, каждое движение вызывало слезы. Спортивные хирурги разводили руками: МРТ идеальное, связки целы, никаких воспалений нет. Мне кололи блокады, но они не давали эффекта. Меня сняли со всех спектаклей, карьера была окончена. В полном отчаянии я решила искать нетрадиционные методы. Отзывы в интернете вывели меня на имя Зулии Раджабовой. Я связалась с ней через контакт на сайте, умоляла о срочном онлайн-приеме. Зулия посмотрела на меня и сразу спросила про странные лужи в гримерке. Я обомлела! Действительно, месяц назад я наступила в какую-то непонятную мыльную лужу возле своего шкафчика. Экстрасенс сказала, что это была мертвая вода с кладбища, переклад болезни от завистливой конкурентки. Зулия Раджабова провела мощную дистанционную чистку. Жгучая боль ушла прямо во время сеанса! Через неделю я вернулась к репетициям.',5,1,'2026-03-23 18:18:00'),
('ad91f5b4-2db8-11f1-a618-1e4a3e6dea57','zuliya-radzhabova','Игорь, 48','','Меня преследовал какой-то абсурдный, но невероятно разрушительный злой рок. Моя личная подпись на всех важных бумажных договорах начала исчезать. Я расписывался дорогой ручкой, чернилами, шариковой — неважно. Через пару дней на месте моей подписи оставалось лишь едва заметное бледное пятно, как будто ее стерли ластиком. Из-за этого у меня сорвалось несколько крупных международных контрактов, юристы партнеров обвиняли меня в мошенничестве с исчезающими чернилами. Моя деловая репутация была уничтожена. Я понимал, что физика и химия здесь бессильны, это был какой-то направленный негатив. Партнер по бизнесу посоветовал найти сильного мага. Я изучил информацию про ясновидящую Зулию Раджабову. Нашел официальный сайт, узнал стоимость приема. Приехал к ней лично в Москве с этими документами. Зулия даже не удивилась. Она сказала, что на меня сделана порча на стирание личности и крах бизнеса. Меня заказал бывший конкурент. Она провела сложный ритуал восстановления моей энергетики и отжига этого негатива. На следующий день я подписал новый контракт обычной ручкой. Прошел год — подпись стоит намертво!',5,1,'2026-03-23 18:17:00'),
('ad91f613-2db8-11f1-a618-1e4a3e6dea57','zuliya-radzhabova','Татьяна, 36','','Наша долгожданная покупка квартиры-мечты обернулась настоящим фильмом ужасов. Квартира была с отличным ремонтом, но стоило нам туда въехать, как начался ад. Мы постоянно находили на полу в коридоре мокрые, грязные следы босых мужских ног. Причем мы живем на пятнадцатом этаже, замки сложные, сигнализация молчала. Я отмывала полы с хлоркой, но на следующее утро следы появлялись снова. Мои дети стали панически бояться выходить из своей комнаты по ночам. Муж дежурил с битой, но никого не видел. Мы были на грани сумасшествия. Я решила искать помощь у экстрасенсов, специализирующихся на чистке помещений. Выбрала Зулию Раджабову. Узнала через сайт, как можно попасть на прием. Зулия провела нам онлайн-консультацию. Она попросила показать эти следы по камере. Ясновидящая сразу сказала, что здесь жил мужчина, который трагически погиб в воде, и его неупокоенная душа возвращается в свой дом, не понимая, что мертва. Зулия провела масштабный спиритический ритуал, отправила душу к свету и запечатала портал. С тех пор полы абсолютно чистые, в квартире стало светло и тепло!',5,1,'2026-03-23 18:16:00'),
('ad921c8d-2db8-11f1-a618-1e4a3e6dea57','zuliya-radzhabova','Сергей, 40','','Моя история может показаться кому-то смешной, но мне было страшно. Я начал слышать свои собственные мысли с задержкой в пару секунд. Я думал о чем-то, а потом отчетливо слышал эту же фразу шепотом прямо у себя в голове чужим, скрипучим голосом. Это свело бы с ума кого угодно. Я перестал нормально спать, боялся думать, стал заторможенным на работе. Психиатр выписал мне нейролептики, поставив под вопросом начальную стадию шизофрении. Но таблетки только делали меня сонным, а шепот оставался. Моя жена, верящая в тонкие материи, сама нашла отзывы про Зулию Раджабову. Она уговорила меня записаться на прием, оплатила стоимость. Мы приехали в Москву. Экстрасенс Зулия Раджабова посмотрела мою ауру и успокоила — это не сумасшествие. Оказалось, я по глупости подобрал на улице красивый металлический амулет, к которому был привязан астральный паразит-повторюшка. Эта сущность питалась моей паникой. Зулия провела жесткий ритуал отсечения. Как только она закончила, этот мерзкий шепот исчез навсегда. Я снова стал здоровым человеком.',5,1,'2026-03-23 18:15:00'),
('ad921d94-2db8-11f1-a618-1e4a3e6dea57','zuliya-radzhabova','Надежда, 29','','Никогда не берите свадебные букеты от малознакомых людей! На моей свадьбе одна дальняя родственница мужа буквально всучила мне роскошный букет из черных калл. Я не придала этому значения. Но с того самого дня моя жизнь пошла под откос. У меня начались жуткие, непроходимые женские болезни, о которых врачи говорили с недоумением. Муж внезапно охладел ко мне, мы стали спать в разных комнатах через месяц после свадьбы! В доме постоянно пахло гнилой водой. Я поняла, что без магии тут не обошлось. Начала искать, кто может снять свадебную порчу. Официальный сайт Зулии Раджабовой вызвал огромное доверие. Я связалась с администраторами, узнала цены и оформила запись на онлайн. Зулия подтвердила мои самые страшные опасения. Эта родственница сделала мощный переклад своего одиночества и болезней на мой брак через те самые цветы. Ясновидящая провела очень сложную, многоэтапную чистку моей женской энергетики. Я выполняла все ее домашние ритуалы. Буквально через две недели мое здоровье полностью восстановилось, муж снова стал ласковым. Сейчас мы ждем малыша!',5,1,'2026-03-23 18:14:00'),
('ad921df1-2db8-11f1-a618-1e4a3e6dea57','zuliya-radzhabova','Роман, 35','','В свои 35 лет я внезапно стал абсолютно седым за одну единственную ночь. Я лег спать с темными волосами, а утром проснулся совершенно белым, как лунь. Никакого стресса, потрясений или испуга накануне не было. Анализы крови были идеальными. Вместе с сединой пришла жуткая, свинцовая тяжесть на плечах, из-за которой я начал сильно сутулиться, превращаясь в старика. Коллеги на работе шарахались от меня. Моя мама была в ужасе и сказала, что это сильная порча на извод. Она сама нашла контакты сильного практика, так как помнила ее по телевизору. Это была Зулия Раджабова. Мы приехали к ней на личный прием в Москве. Экстрасенс не стала лить воду. Она сразу сказала, что мой лучший друг, которому я недавно одолжил крупную сумму денег, не захотел их отдавать и заказал у черного мага порчу на быстрое старение и смерть. Зулия провела мощный обряд возврата негатива и отжига. Сутулость и тяжесть ушли прямо в кабинете. Волосы, конечно, пришлось закрашивать, но новая беда ко мне больше не липла. Друг, кстати, попал в серьезную аварию через неделю. Всё возвращается.',5,1,'2026-03-23 18:13:00'),
('ad921e5a-2db8-11f1-a618-1e4a3e6dea57','zuliya-radzhabova','Мария, 43','','Мы удочерили прекрасную девочку пяти лет из детского дома. Всё было хорошо первые пару месяцев. Но потом начались странности. Дочка стала постоянно рисовать черным карандашом одно и то же страшное, искаженное лицо с пустыми глазами. Она прятала эти рисунки под подушку, а по ночам разговаривала с кем-то в темноте. Наши домашние коты начали шипеть на ребенка и прятаться под диван. Дочка стала агрессивной, кусалась. Детский психолог не смог пробиться сквозь эту стену. Я поняла, что ребенок принес с собой какую-то сущность из прошлого. Стала искать отзывы реальных людей о помощи экстрасенсов с детьми. Выбрала Зулию Раджабову. Узнала через контакт на сайте, как можно связаться онлайн, чтобы не пугать ребенка поездками. Зулия посмотрела на девочку по видео и всё поняла. К ребенку был привязан дух ее биологической матери, которая вела маргинальный образ жизни и умерла от передозировки. Эта сущность не давала девочке жить нормально. Зулия провела очень бережный, но сильный ритуал экзорцизма и защиты. После этого дочка перестала рисовать монстров, коты снова спят с ней рядом. У нас снова счастливая семья!',5,1,'2026-03-23 18:12:00'),
('ad921eb0-2db8-11f1-a618-1e4a3e6dea57','zuliya-radzhabova','Алексей, 38','','Моя история связана с машинами и сплошной мистикой. Я работаю торговым представителем, вся жизнь за рулем. И вдруг я начал попадать в аварии. За полгода — четыре ДТП! Причем сценарий всегда был абсолютно идентичным: в меня врезались исключительно в правую заднюю дверь, когда я стоял на светофоре. Машины были разные, перекрестки разные, но удар всегда приходился в одну точку. Страховые компании уже занесли меня в черный список. Я панически боялся выезжать на дорогу. Друг посоветовал найти сильного ясновидящего, сказал, что это наведенный негатив. Я вбил в поиск экстрасенс зулия раджабова отзывы и решил довериться ей. Нашел официальный сайт, узнал цену приема и записался. Приехал в Москву. Зулия Раджабова сразу раскинула свои карты и сказала: На тебя сделана порча на закрытие дорог и аварию. Кто-то очень хочет, чтобы ты перестал работать. Оказалось, это козни моего завистливого коллеги, который метил на мое место. Зулия сняла этот блок, почистила мою ауру и дала защитный оберег в машину. Езжу уже год без единой царапины!',5,1,'2026-03-23 18:11:00'),
('ad921f0e-2db8-11f1-a618-1e4a3e6dea57','zuliya-radzhabova','Дарья, 32','','Никогда не думала, что обычная лужа может стать причиной инвалидности. Я возвращалась домой с работы и случайно перешагнула через странную мыльную лужу у подъезда, в которой валялись какие-то ржавые монеты. На следующее утро я не смогла встать с кровати. Мои ноги от коленей до ступней горели адским огнем, суставы опухли до невероятных размеров. Я кричала от боли. Ревматологи кололи гормоны, подозревали острый артрит, но анализы крови были чистыми! За неделю я оказалась в инвалидном кресле. Моя мама поняла, что это переклад болезни, и начала срочно искать мага. Нашла информацию о Зулии Раджабовой. Мы умоляли администраторов о срочном онлайн-приеме. Зулия посмотрела на мои ноги по видеосвязи и подтвердила — я наступила в сильную порчу, которую соседка скинула на безденежье и болезнь ног. Ясновидящая провела очень мощный дистанционный обряд отжига и перевода негатива на воск. Вы не поверите, но отек начал спадать прямо к вечеру! Через три дня я смогла самостоятельно ходить. Ее сила просто невероятна.',5,1,'2026-03-23 18:10:00'),
('ad921f86-2db8-11f1-a618-1e4a3e6dea57','zuliya-radzhabova','Константин, 45','','Всё в моем доме начало бить меня током. Буквально всё. Я дотрагивался до дверной ручки — получал сильный разряд. Открывал холодильник — меня отбрасывало. Даже вода из-под крана щипала руки! Жена и дети ходили по квартире абсолютно спокойно, никаких проблем с проводкой электрики не нашли. Я стал психованным, ходил по дому в резиновых перчатках. Из-за этого постоянного напряжения у меня начались проблемы с сердцем. Я понял, что это моя личная энергетика сошла с ума. Стал искать, как записаться к специалисту по биополю. Выбрал экстрасенса Зулию Раджабову. Нашел официальный сайт, оставил свои контакты. На приеме в Москве Зулия посмотрела на меня и сказала, что на мне висит сильный энергетический пробой, крадник, который вызвал замыкание моей ауры. Кто-то из подчиненных воровал мою удачу. Зулия провела сложный обряд заземления и восстановления защитного кокона. Статическое электричество пропало сразу же, как я вышел из ее кабинета. Я больше не бьюсь током и живу нормальной жизнью.',5,1,'2026-03-23 18:09:00'),
('ad9249fb-2db8-11f1-a618-1e4a3e6dea57','zuliya-radzhabova','Анна, 30','','Я профессиональный парфюмер, создаю авторские ароматы. Мое обоняние — это мой дар. Но после одной выставки в Париже я вдруг начала чувствовать везде один и тот же запах — запах гниющих яблок. Еда, духи, цветы, люди — всё пахло для меня тухлятиной. Я не могла есть, меня постоянно тошнило, я потеряла способность работать. Врачи разводили руками, МРТ мозга ничего не показало. Мой бизнес рушился. Я впала в глубокую депрессию. Коллега по цеху посоветовала найти экстрасенса, сказала, что это явно порча на лишение способностей. Я стала изучать отзывы о Зулии Раджабовой. Узнала стоимость приема, записалась на онлайн. Зулия сразу увидела корень проблемы. Оказалось, моя главная конкурентка подарила мне на выставке красивый шарф, пропитанный мертвой водой, чтобы перекрыть мои таланты. Ясновидящая провела дистанционную чистку и велела немедленно сжечь этот шарф. Как только он превратился в пепел, мерзкий запах исчез! Ко мне вернулось мое тонкое обоняние, я снова создаю духи.',5,1,'2026-03-23 18:08:00'),
('ad924a7e-2db8-11f1-a618-1e4a3e6dea57','zuliya-radzhabova','Владимир, 51','','Моя семья столкнулась с невероятно странным проклятием. В нашем доме внезапно начали размножаться осы. Они строили огромные гнезда внутри стен, на балконе, под подоконниками. Мы вызывали дезинсекторов каждую неделю, заливали всё ядом, но осы возвращались снова и снова в невероятных количествах. Они стали агрессивными, искусали младшего сына до анафилактического шока. Жить в доме стало смертельно опасно. Жена плакала и говорила, что нас выживают. Я не верил в мистику, но вариантов не осталось. Нашел в интернете отзывы реальных людей про Зулию Раджабову. Связался через контакт на официальном сайте. Зулия провела нам онлайн-консультацию. Она сказала, что это старое проклятие на рой, на разрушение домашнего очага, которое активировалось, когда мы сделали перепланировку и задели несущую стену, где был замурован подклад от прежних хозяев. Экстрасенс провела мощный обряд очищения пространства и научила нас, как правильно энергетически запечатать дом. Осы исчезли за два дня и больше никогда не появлялись! Мы наконец-то в безопасности.',5,1,'2026-03-23 18:07:00'),
('ad924ad7-2db8-11f1-a618-1e4a3e6dea57','zuliya-radzhabova','Елизавета, 38','','Я почти потеряла своего старшего брата. Он просто вышел с работы в пятницу вечером и бесследно исчез. Телефон выключен, друзья ничего не знают. Полиция приняла заявление, но действовала очень вяло, мол, взрослый мужчина, загулял. Прошла неделя, мы с мамой сходили с ума от горя и неизвестности, обзвонили все больницы и морги. В полном отчаянии я стала искать помощь у ясновидящих. Многие рекомендовали Зулию Раджабову как специалиста по поиску людей. Мы умоляли администраторов о срочном приеме. Нас приняли в Москве. Зулия взяла фотографию брата, закрыла глаза и очень уверенно сказала: Жив. Но не в себе. Находится в старом заброшенном доме возле железнодорожных путей, станция на букву В. Она описала местность до мельчайших деталей. Мы передали эту информацию волонтерам-поисковикам. И вы не поверите, они нашли его именно там, в поселке Водники! Брат был в состоянии глубокой амнезии после удара по голове. Если бы не точное видение Зулии, он бы просто замерз там насмерть. Она спасла ему жизнь!',5,1,'2026-03-23 18:06:00'),
('ad924b2e-2db8-11f1-a618-1e4a3e6dea57','zuliya-radzhabova','Тимур, 33','','За месяц до важнейших Олимпийских отборочных соревнований я, профессиональный гимнаст, внезапно потерял чувство равновесия. Я просто не мог ровно пройти по бревну, меня шатало на ровном месте, я постоянно падал и получал микротравмы. Вестибулярный аппарат сошел с ума. Врачи спортивного диспансера не находили никаких патологий, списывали всё на дикий стресс и переутомление. Но я знал, что это не усталость. Тренер был в панике, моя карьера рушилась. Моя мама настояла на визите к экстрасенсу. Мы нашли официальный сайт Зулии Раджабовой, узнали цены и записались. Зулия Раджабова посмотрела на меня и сказала, что на мне висит сильный крадник удачи и координации. Его сделал мой напарник по команде, который очень хотел занять мое место. Он подсыпал мне в магнезию заговоренную пыль. Ясновидящая провела мощный обряд снятия этого блока и вернула мне мою энергию. На следующей тренировке я выполнил сложнейшие элементы идеально! Отбор я прошел блестяще.',5,1,'2026-03-23 18:05:00'),
('ad924b82-2db8-11f1-a618-1e4a3e6dea57','zuliya-radzhabova','Валерия, 42','','Никогда не надевайте чужие старинные вещи! На юбилей свекровь подарила мне роскошное антикварное ожерелье с изумрудами. Как только я начала его носить, у меня появилось постоянное, удушающее чувство тревоги. Но самое страшное началось позже: на моей шее, прямо под ожерельем, стали появляться красные царапины, которые складывались в ровные буквы чужого алфавита. Это было жутко. Врачи выписывали мази от аллергии, но буквы только ярче проступали. Я поняла, что без магии тут не обошлось. Стала искать сильного специалиста. Отзывы об экстрасенсе Зулии Раджабовой внушали доверие. Нашла, как записаться на онлайн-прием. Зулия попросила показать ожерелье по видео. Она сразу побледнела и сказала: Сними это немедленно! Это вещь с покойницы, на ней лежит родовое проклятие на удушье. Ясновидящая провела сложный ритуал отсечения некротической привязки и дала инструкции, как очистить и безопасно избавиться от этого украшения. Царапины сошли за три дня, удушье исчезло навсегда.',5,1,'2026-03-23 18:04:00'),
('ad924bd8-2db8-11f1-a618-1e4a3e6dea57','zuliya-radzhabova','Игорь, 36','','Я оказался в полном тупике. Моя успешная карьера юриста рухнула из-за одной странной фобии. Я внезапно перестал мочь читать текст, написанный красным шрифтом или с красными печатями. У меня начиналась жуткая мигрень, буквы плыли, меня тошнило. Вся юридическая документация была для меня закрыта. Я не мог работать, взял длительный больничный. Окулисты и неврологи смеялись, говорили про переутомление. Я решил искать мистическую причину. Нашел официальную страницу экстрасенса Зулии Раджабовой. Оставил контакт, узнал стоимость приема. Приехал к ней лично. Зулия раскинула карты и сказала, что на меня навели порчу на слепоту и карьерный крах. Сделала это клиентка, дело которой я не смог выиграть в суде. Она использовала кладбищенскую землю. Зулия Раджабова провела очень сильный ритуал чистки огнем. Я не знаю, как это работает, но на следующее утро я спокойно открыл папку с красными пометками и прочитал всё без малейшей головной боли! Моя работа спасена.',5,1,'2026-03-23 18:03:00'),
('ad924c33-2db8-11f1-a618-1e4a3e6dea57','zuliya-radzhabova','Оксана, 28','','Мои платья начали гнить прямо в шкафу. Это не моль и не сырость. Я покупала новые, дорогие шелковые платья, вешала в гардеробную, а через неделю находила их в огромных дырах с почерневшими краями, как будто их прожгли кислотой. При этом одежда мужа висела рядом в идеальном состоянии. Я была в ужасе, ущерб шел на сотни тысяч. Подруга сказала, что это сильная порча на женское одиночество и уродство, чтобы я ходила в лохмотьях. Я стала срочно искать, кто может помочь. Наткнулась на отзывы о Зулии Раджабовой. Записалась через администраторов на онлайн-прием. Зулия подтвердила мои опасения. Оказалось, бывшая девушка моего мужа не смирилась с его уходом и сделала подклад-иглу, зашив ее в подкладку моего любимого пальто. Ясновидящая дала мне точные инструкции, как найти и уничтожить эту иглу. После того как я всё сделала по ее правилам и Зулия провела чистку квартиры, мои вещи перестали портиться. Я снова могу носить красивые платья и быть спокойной за свою семью.',5,1,'2026-03-23 18:02:00'),
('ad927e68-2db8-11f1-a618-1e4a3e6dea57','zuliya-radzhabova','Антон, 45','','Я успешный ресторатор, владею несколькими заведениями. Но в одном из них, самом прибыльном, начала происходить катастрофа. Весь дорогой элитный алкоголь в баре начал за ночь превращаться в кислый уксус. Закрытые, запечатанные бутылки вина и коньяка за тысячи долларов утром оказывались скисшими. Поставщики клялись, что с партией всё отлично, температура в норме. Я терпел гигантские убытки. Понял, что это диверсия конкурентов на тонком плане. Стал искать сильного практика по защите бизнеса. Нашел контакты Зулии Раджабовой. Узнал цену и пригласил ее в ресторан. Экстрасенс Зулия Раджабова прошла по залу и сразу указала на декоративную бочку в углу. Внутри оказался спрятан кусок тухлого мяса, замотанный в черные нитки. Мощная порча на разорение и гниение бизнеса! Зулия провела очищение помещения своими ритуалами, нейтрализовала подклад. С того дня ни одна бутылка больше не испортилась. Бизнес снова процветает. Ее сила действительно спасает людей.',5,1,'2026-03-23 18:01:00'),
('af0bae64-2847-11f1-9834-be0c34c0fde5','viktoriya-raidos','Маргарита, 38','','Всё началось после похорон моей бабушки. С того самого дня я перестала спать нормально. Каждую ночь мне снился один и тот же тягучий, липкий кошмар: она стояла у моей кровати и тянула ко мне свои ледяные руки, пытаясь забрать с собой. Я просыпалась в холодном поту, с жуткой тахикардией. Сначала списывала на стресс и горечь утраты, пила сильные успокоительные, но становилось только хуже. В квартире стало постоянно пахнуть сырой землей и какими-то старыми лекарствами. Я начала таять на глазах, начались проблемы на работе. Подруга, увидев мое состояние, просто силой заставила меня искать экстрасенса. Мы перерыли весь интернет, читали реальные отзывы кто обращался. Нас обеих зацепила Виктория Райдос — ее работа с родом и миром мертвых внушала огромное доверие. Нашли официальный сайт, оставили контактные данные для записи. Ждать пришлось около недели. На приеме Виктория была очень строга, но профессиональна. Она с порога сказала, что бабушка не ушла, потому что я по глупости положила в гроб свою личную вещь — любимый платок. Жрица культа предков провела сложнейший обряд отсечения некротической привязки. Делали всё очень четко по ее инструкции. Запах в квартире пропал в тот же вечер. Бабушка больше не приходила ни разу. Я безмерно благодарна этой потрясающей женщине за спасение моей жизни.',5,1,'2026-03-23 14:25:00'),
('af0be7bd-2847-11f1-9834-be0c34c0fde5','viktoriya-raidos','Алексей, 34','','Никому не пожелаю жить с ощущением надвигающейся, неизбежной смерти. В нашем роду по мужской линии происходила страшная, необъяснимая вещь: мой дед, отец и старший брат погибли ровно в 33 года при абсолютно разных, но нелепых обстоятельствах. Когда мне исполнилось 32, меня накрыла черная паранойя. Я боялся выходить из дома, бросил водить машину, вздрагивал от каждого шороха. Жизнь превратилась в ежедневное ожидание конца. Моя жена не выдержала этого напряжения и начала искать помощь. Она всегда смотрела проект битва экстрасенсов, поэтому сразу предложила обратиться к проверенным людям. Мы решили, что нам нужна именно Виктория Райдос, так как она специализируется на родовой карме. Узнали, сколько стоит прием, нашли официальный телефон и оформили запись. На личной встрече в Москве экстрасенс подтвердила наши самые страшные опасения. Она увидела старое родовое проклятие, брошенное на моего прадеда обиженной женщиной. Это была очень тяжелая, энергозатратная работа. Виктория использовала свою знаменитую книгу мертвых, вызывала духов рода. Я физически чувствовал, как с моих плеч спадает бетонная плита. Роковой рубеж в 33 года я прошел абсолютно спокойно. Сейчас мне 34, я жив, здоров, воспитываю сына и точно знаю, что на мне эта страшная цепочка прервалась навсегда.',5,1,'2026-03-23 14:24:00'),
('af0f31da-2847-11f1-9834-be0c34c0fde5','viktoriya-raidos','Ирина, 45','','Я была на грани полного, сокрушительного банкротства. Мой партнер по бизнесу скоропостижно скончался от сердечного приступа, и после этого всё пошло прахом. Проверки, суды, внезапные долги, отток клиентов — словно прорвало какую-то черную плотину. Но самым жутким было то, что я начала слышать его тяжелые шаги в нашем пустом офисе по вечерам. У меня реально ехала крыша от ужаса. Я поняла, что традиционными методами бизнес уже не спасти. Стала гуглить, кто может помочь в таких мистических ситуациях. Попалась на глаза страница экстрасенса Виктории Райдос. Почитала отзывы людей о ее приемах. Написала в Ватсап ее администраторам, объяснила срочность. Меня приняли очень быстро. Виктория сразу, без лишних вопросов, сказала, что мой партнер перед смертью провел ритуал на то, чтобы дело без него рухнуло, он был невероятно жадным до власти человеком и не хотел, чтобы компания досталась мне. Колдунья провела очищение офиса и жестко отправила его неупокоенную душу туда, где ей место. Поставила мне мощную защиту на деньги и контакт с новыми партнерами. Вы не поверите, но через три недели я выиграла крупный тендер, который перекрыл все мои убытки!',5,1,'2026-03-23 14:23:00'),
('af0f33cd-2847-11f1-9834-be0c34c0fde5','viktoriya-raidos','Наталья, 29','','С моим пятилетним сыном начало твориться нечто не поддающееся логике. Он завел себе воображаемого друга, которого называл странным старинным именем Архип. Сначала мы с мужем просто умилялись этой детской фантазии. Но потом начался сущий кошмар. Сын стал агрессивным, мог ударить меня, разбивал посуду, а на мои крики отвечал чужим, грубым голосом: Архип велел так сделать! Он перестал нормально спать, плакал, говорил, что этот дядя заставляет его делать плохие вещи. Детские психологи ничем не помогли, выписывали легкие успокоительные и говорили про возрастные кризисы. Я была на грани нервного срыва. Сестра посоветовала найти сильного практика. Мы начали читать отзывы кто обращался со странностями детей. Нам очень откликнулась Виктория. Узнали стоимость, оформили заявку через официальный сайт. Ждали онлайн-приема как манны небесной. Райдос даже через экран сразу увидела суть. Оказалось, в нашу квартиру недавно принесли старинную монету с блошиного рынка, к которой был привязан дух злого человека из прошлого века. Ребенок, будучи энергетически открытым, попал под его влияние. Ясновидящая дистанционно провела ритуал очищения и велела немедленно отнести монету на перекресток по строгим правилам. Мы всё сделали. В ту же ночь сын спокойно уснул, а про Архипа больше никогда не вспоминал.',5,1,'2026-03-23 14:22:00'),
('af0fa0d6-2847-11f1-9834-be0c34c0fde5','viktoriya-raidos','Денис, 41','','Я всегда считал себя человеком с железобетонной психикой, закоренелым прагматиком. Но то, что стало происходить со мной после переезда в пригород, сломало мою картину мира. Я начал страдать тяжелейшей формой лунатизма. И ладно бы я просто ходил по дому. Я просыпался глубокой ночью на улице, в нескольких километрах от дома, стоя босиком у ворот старого поселкового кладбища! Причем я не помнил, как открывал замки, как шел туда по холоду. Врачи разводили руками, выписывали тяжелые транквилизаторы, от которых я спал сутками, не мог работать. Жена плакала каждый день, боялась, что я однажды просто не вернусь. Она сама решила найти специалиста и написала администраторам Виктории Райдос. Мы узнали цены на прием, приехали в Москву. Экстрасенс выслушала меня с каменным лицом. Она разложила карты и сказала, что это зов мертвых. При строительстве нашего нового дома рабочие случайно зацепили старое неучтенное захоронение, и потревоженный дух тянул меня к себе как хозяина участка. Это звучало как бред, но факты были налицо. Жрица культа предков провела очень сложный обряд умиротворения духа на нашем участке. С тех пор прошло почти восемь месяцев. Ни одного эпизода лунатизма больше не было, я сплю как убитый в своей постели.',5,1,'2026-03-23 14:21:00'),
('af0fa1bc-2847-11f1-9834-be0c34c0fde5','viktoriya-raidos','Ольга, 35','','Никогда не берите чужие старинные украшения, даже если это наследство! Я усвоила этот урок слишком дорогой ценой. После смерти моей двоюродной бабки мне достался потрясающей красоты антикварный кулон с сапфиром. Я начала носить его не снимая, гордилась такой роскошью. И буквально через месяц моя жизнь покатилась в пропасть. Начались жуткие, непроходимые боли в позвоночнике, я не могла нормально ходить, врачи не находили грыж или защемлений, анализы были идеальные. Следом рухнули отношения с женихом, он ушел без объяснения причин. Я впала в отчаяние. Моя коллега по работе, видя, как я хромаю и плачу, посоветовала найти мага. Я стала изучать информацию в сети. Выбрала Викторию Райдос, потому что она работает с энергией рода и мертвых. Нашла ее контакт, записалась на личную встречу. Как только я переступила порог кабинета, Виктория посмотрела на мою грудь и велела немедленно снять кулон. Она сказала, что на этом камне висит проклятие на одиночество и болезни, которое бабка забрала на себя в молодости, а теперь оно перешло ко мне. Колдунья провела обряд очищения меня и жестко заблокировала негатив в камне. Я отдала его ей на уничтожение. Спина перестала болеть через два дня! Я в шоке от того, насколько это всё реально работает.',5,1,'2026-03-23 14:20:00'),
('af0fa235-2847-11f1-9834-be0c34c0fde5','viktoriya-raidos','Светлана, 28','','Связь между близнецами — это не миф, это страшная реальность. Моя сестра-близняшка трагически погибла в автокатастрофе два года назад. Мое горе было безмерным, но самое жуткое началось спустя сорок дней после ее смерти. Я начала физически чувствовать фантомные боли в тех местах, где у нее были переломы. У меня ни с того ни с сего начинала дико болеть грудная клетка, мне не хватало воздуха, я задыхалась так же, как она в свои последние минуты. Я обошла всех врачей, делала МРТ, КТ — я была абсолютно здорова физически. Психотерапия не давала никакого облегчения. Я просто медленно сходила с ума. Моя мама поняла, что медицина тут бессильна, и стала искать официальный сайт Виктории Райдос. Мы оставили заявку, ждали ответа, умоляли о срочности. Нас приняли онлайн. Ясновидящая сразу сказала, что душа сестры не может найти покой и из-за нашей сильнейшей связи близнецов случайно тянет из меня жизненную энергию, буквально забирая меня к себе. Райдос провела тяжелейший спиритический сеанс, мы правильно попрощались с сестрой, экстрасенс разорвала эту некротическую привязку. После этого сеанса боли ушли навсегда, а мне впервые за два года приснилась сестра, светлая и спокойная. Огромная помощь и благодарность.',5,1,'2026-03-23 14:19:00'),
('af0fa2a1-2847-11f1-9834-be0c34c0fde5','viktoriya-raidos','Вадим, 44','','Всё в моей жизни шло просто отлично, пока я не купил с рук шикарный дорогой автомобиль. Продавец отдавал его значительно ниже рыночной стоимости, сославшись на срочный переезд. Как только я сел за руль этой машины, в моей жизни началась черная полоса. Сначала я попал в две мелкие аварии на пустом месте. Потом начались жуткие головные боли именно в салоне авто. А однажды я нашел под водительским сиденьем странный тряпичный мешочек с иголками и землей. Тут мне стало по-настоящему жутко. Понял, что нужна помощь специалиста по тяжелой энергетике. Начал гуглить, читать реальные отзывы. Выбор сразу пал на Викторию. Нашел контактный телефон, узнал цены и записался. Приехал к ней в Москву прямо на этой машине. Экстрасенс Виктория Райдос даже в салон садиться не стала, просто провела рукой над капотом и сказала: Машина была в смертельном ДТП, а этот мешочек — подклад от родственников погибшего на месть и смерть новому владельцу. У меня просто волосы встали дыбом. Виктория провела жесткий ритуал отжига машины, уничтожила подклад по своим правилам и поставила на меня зеркальную защиту. С тех пор езжу спокойно, никаких проблем с автомобилем и здоровьем больше не возникало.',5,1,'2026-03-23 14:18:00'),
('af0fa306-2847-11f1-9834-be0c34c0fde5','viktoriya-raidos','Екатерина, 32','','Никогда бы не подумала, что обычная фотография может стать причиной жизненной катастрофы. На моем рабочем столе стояла рамка с нашим счастливым семейным фото с мужем. И вдруг я стала замечать странную вещь: мое лицо на этой напечатанной фотографии начало медленно выцветать и размываться, словно стираясь резинкой, хотя лицо мужа оставалось четким. Одновременно с этим я начала таять на глазах в реальности. Потеряла 15 килограмм за месяц, волосы выпадали клочьями, появилась постоянная слабость. Муж стал ко мне охладевать, начались ссоры. Знакомая бабушка в деревне сказала, что это порча на извод, и посоветовала искать сильную ведьму. Я перерыла интернет, посмотрела множество информации. Остановилась на имени ясновидящей Виктории Райдос. Зашла на официальный сайт, оставила заявку на прием. Повезло попасть быстро. На консультации Виктория посмотрела на это фото и прямо сказала: Это делает твоя близкая подруга, она вхожа в ваш дом и хочет занять твое место. Она провела ритуал на воду по фото. Снимала с меня эту дрянь долго и тяжело, я чувствовала холод по всему телу во время сеанса. Но результат был поразительным. Мое здоровье начало восстанавливаться уже через неделю, мы с мужем помирились, а та подруга внезапно перестала нам звонить и писать.',5,1,'2026-03-23 14:17:00'),
('af0fa36c-2847-11f1-9834-be0c34c0fde5','viktoriya-raidos','Роман, 39','','Молодость и глупость чуть не стоили мне разума. В студенческие годы мы с ребятами ради шутки играли с доской Уиджи, вызывали духов в старом заброшенном доме. Все посмеялись и забыли. Но спустя пятнадцать лет ко мне начали приходить последствия. Каждую ночь ровно в 3:15 я просыпался от ощущения, что на моей груди сидит что-то тяжелое и невидимое. Я не мог ни кричать, ни пошевелиться — классический сонный паралич, как говорили врачи. Но врачи не знали, что это нечто шептало мне на ухо жуткие вещи на непонятном языке. Я стал бояться засыпать, начал пить, появились мысли о суициде. Моя мама не могла на это смотреть и сама написала администраторам экстрасенса Виктории Райдос. Узнала, сколько стоит прием, и силой притащила меня к ней. Виктория, известная своими способностями из шоу битва сильнейших, была беспощадна в своей правде. Она сразу увидела ту детскую игру и сказала, что мы случайно открыли портал и привязали ко мне мелкого, но злого беса-паразита. Он ждал, пока моя энергетика ослабнет от стресса на работе, и начал жрать меня. Виктория провела жесткий ритуал изгнания. Это было самое страшное и одновременно спасительное событие в моей жизни. С тех пор я сплю абсолютно спокойно.',5,1,'2026-03-23 14:16:00'),
('af0fc788-2847-11f1-9834-be0c34c0fde5','viktoriya-raidos','Татьяна, 50','','Запах смерти преследовал меня повсюду. Это звучит как безумие, но куда бы я ни пошла — на работу, в магазин, в гости — я отчетливо чувствовала сладковатый, тошнотворный запах формалина и гниющих цветов. Никто из окружающих этого не чувствовал, только я. Я постоянно проветривала квартиру, мылась по три раза в день, но запах въелся мне в мозг. Психиатр поставил диагноз обонятельные галлюцинации и выписал таблетки. Но они не помогали. В какой-то момент я поняла, что это мистика. Стала искать помощи у тех, кто работает с тонкими материями. Вышла на официальный сайт Виктории Райдос, почитала отзывы реальных людей. Записалась на консультацию онлайн, так как живу далеко. Виктория выслушала меня и попросила показать комнату. Она указала на старый книжный шкаф и велела достать оттуда пыльный дневник моего покойного свекра. Оказалось, перед смертью он написал там проклятие в мой адрес, обвиняя в своих бедах. Эта ненависть не давала ему уйти, и он физически разлагал мою жизнь. Жрица культа предков научила меня, как правильно сжечь этот дневник и очистить помещение. Как только пепел развеялся по ветру, жуткий запах пропал навсегда. Я снова живу нормальной жизнью!',5,1,'2026-03-23 14:15:00'),
('af0fc815-2847-11f1-9834-be0c34c0fde5','viktoriya-raidos','Виктор, 45','','Моя семья столкнулась с невероятно страшной проблемой — земля буквально отвергала наш новый дом. Мы вложили все сбережения в постройку коттеджа за городом. Но как только мы въехали, начался ад. Фундамент стал трескаться без причины, стены пошли плесенью за неделю, постоянные короткие замыкания, вода в скважине внезапно стала отдавать ржавчиной и болотом. Но самое ужасное — на нашем участке не росло абсолютно ничего, даже сорняки сохли на корню. Местные жители обходили наш дом стороной. Сосед проговорился, что на этом месте в прошлом веке расстреливали людей. Мы были в шоке. Поняли, что строители нам ничего не скажут. Стали искать экстрасенса. Нашли телефон Виктории Райдос, узнали цены. Она приехала на участок лично. Это было сильно. Она прошлась по земле, читая что-то из своей книги, и подтвердила, что здесь земля пропитана кровью и страданием, неупокоенные души не дают нам тут жить. Виктория провела масштабный обряд успокоения мертвых и очищения земли. Поставила мощный барьер по периметру. Буквально через месяц прекратились проблемы с проводкой, вода стала чистой, а весной на участке взошел шикарный газон. Наш дом спасен!',5,1,'2026-03-23 14:14:00'),
('af0fc878-2847-11f1-9834-be0c34c0fde5','viktoriya-raidos','Алина, 31','','Никому не пожелаю пережить тот леденящий ужас, который испытывала я. У меня появилась паническая, необъяснимая фобия зеркал. Я не могла смотреть на свое отражение, потому что краем глаза постоянно замечала, что позади меня стоит высокая темная фигура мужчины. Как только я поворачивалась — никого не было. Я занавесила все зеркала в квартире, перестала краситься, боялась проходить мимо витрин на улице. Муж решил, что я схожу с ума от переутомления, хотел положить меня в клинику неврозов. Но моя мама тайком от него нашла информацию про сильную колдунью. Это была ясновидящая Виктория Райдос. Мама оформила запись на прием. На встрече Виктория даже не стала задавать наводящих вопросов. Она четко описала этого мужчину из зеркала — это был мой бывший начальник, который трагически погиб год назад. Оказалось, перед смертью он затаил на меня сильную злобу из-за рабочего конфликта и теперь приходил питаться моим страхом через отражающие поверхности. Экстрасенс провела очень сложный ритуал закрытия зеркальных порталов и отсекла эту связь. Я снова могу спокойно смотреть на себя в зеркало, тени исчезли. Огромное спасибо за помощь!',5,1,'2026-03-23 14:13:00'),
('af0fc8da-2847-11f1-9834-be0c34c0fde5','viktoriya-raidos','Игорь, 38','','Странные, пугающие метки начали появляться на моем теле по утрам. Я просыпался и находил на груди и руках глубокие, красные царапины, которые складывались в ровные кресты, похожие на могильные. Сначала я думал, что сам царапаю себя во сне, начал коротко стричь ногти, надевал на ночь плотные водолазки. Но царапины продолжали появляться под одеждой! Они горели огнем и очень долго не заживали. Жена была в панике, заставляла идти к дерматологу, но врачи только разводили руками. В интернете я случайно наткнулся на статью про подселения и порчи. Решил, что мне нужен экстрасенс Виктория Райдос, так как она специалист в этой сфере. Нашел официальный сайт, узнал стоимость приема. Связаться было несложно, администраторы ответили быстро. Виктория приняла меня в Москве. Она посмотрела на эти кресты и сказала, что это сильная кладбищенская порча на медленную смерть, которую заказала на меня бывшая любовница, не смирившаяся с моим уходом к жене. Виктория проводила сложный обряд очищения с использованием земли и огня. Это было жутко, но эффективно. Царапины перестали появляться на следующее утро, а старые зажили без следа за неделю.',5,1,'2026-03-23 14:12:00'),
('af0fc93f-2847-11f1-9834-be0c34c0fde5','viktoriya-raidos','Надежда, 42','','Наш старый, спокойный лабрадор внезапно сошел с ума. Он начал панически бояться одного конкретного угла в нашей гостиной. Он садился напротив него, шерсть вставала дыбом, и он начинал выть так протяжно и жутко, что у нас стыла кровь в жилах. Если кто-то из нас пытался подойти к этому углу, собака бросалась и пыталась оттащить нас за одежду. Вскоре после этого у меня начались жуткие мигрени, а муж потерял работу. Квартира наполнилась тяжелой, давящей энергетикой. Я поняла, что животные просто так не воют. Решила искать мага. Пересмотрела кучу отзывов, кто обращался за чисткой помещений. Выбрала Викторию Райдос. Узнала через официальный контакт, как можно попасть к ней. Нам назначили онлайн-встречу. Я показала ей этот угол по камере. Виктория сразу сказала: Там открыта энергетическая воронка. Кто-то принес вам в дом вещь с покойника. Мы начали искать и нашли за батареей в этом углу старую, грязную расческу с седыми волосами! Это был подклад от злой соседки. Виктория научила нас, как правильно уничтожить эту дрянь, и дистанционно закрыла воронку. Собака в тот же вечер спокойно легла спать в гостиной. Беды ушли из нашего дома.',5,1,'2026-03-23 14:11:00'),
('af0fc9a0-2847-11f1-9834-be0c34c0fde5','viktoriya-raidos','Мария, 36','','Невозможно передать словами боль матери, которая не может иметь детей, когда все медицинские показатели в норме. Пять лет бесконечных обследований, слез, два неудачных ЭКО. Но самое страшное было то, что все женщины в моем роду по материнской линии сталкивались с этой же бедой — мы все теряли детей на одном и том же сроке или годами не могли забеременеть. Врачи говорили про генетику, но я чувствовала, что дело в другом. Сестра посоветовала обратиться к нетрадиционным методам. Я стала изучать информацию про экстрасенса Викторию Райдос. Знаю ее по тв проектам как невероятно сильного специалиста по роду. Нашла официальный сайт, оставила заявку. Очередь была большая, но я дождалась. На личном приеме Виктория погрузилась в мою родовую память. Она увидела, что моя прапрабабушка совершила страшный грех, прокляв чужого ребенка, и это проклятие ударило по всему нашему женскому роду вплоть до седьмого колена. Это была колоссальная, тяжелая работа по отмаливанию и снятию родового негатива. Я выполняла множество практик. И вот, спустя восемь месяцев после работы с Викторией, я увидела две полоски на тесте! Беременность протекает идеально. Это настоящее чудо.',5,1,'2026-03-23 14:10:00'),
('af0fe869-2847-11f1-9834-be0c34c0fde5','viktoriya-raidos','Константин, 47','','Птицы стали вестниками моего личного ада. Всё началось с того, что в окно моего офиса на 15 этаже врезался черный ворон и разбился насмерть. Через день ситуация повторилась дома — голубь на полной скорости влетел в стекло на балконе. Птицы словно сошли с ума, они постоянно бились в мои окна, оставляя кровавые следы. Одновременно с этим рушилась моя жизнь: банк внезапно заблокировал все счета компании, налоговая начала жесткую проверку, от меня ушла жена. Я чувствовал, что вокруг меня сжимается кольцо. Мой заместитель посоветовал не игнорировать такие знаки и найти ясновидящего. Мы перерыли интернет, искали, кто реально может помочь. Нашли контакты Виктории Райдос. Я узнал цену приема и записался. Виктория выслушала меня и безапелляционно заявила, что птицы — это предупреждение от моих умерших предков о мощной порче на разорение и одиночество. Ее заказал мой прямой конкурент по бизнесу. Жрица культа предков провела жесткую чистку моей энергетики и поставила зеркальную защиту. Как только мы закончили работу, птицы перестали биться в окна. Вскоре счета разблокировали, а проверки закончились ничем. Жена вернулась через месяц.',5,1,'2026-03-23 14:09:00'),
('af0fe8e6-2847-11f1-9834-be0c34c0fde5','viktoriya-raidos','Евгения, 33','','Странные, жуткие вещи начали происходить со мной после покупки старинного зеркала на антикварной барахолке. Я всегда любила винтаж, но эта вещь оказалась проклятой. По ночам я начала слышать тихий плач, исходящий прямо из стекла. А однажды утром, посмотрев в него, я увидела позади своего отражения незнакомую комнату с обшарпанными обоями и петлей на потолке! Я с криком выбежала из квартиры. Спать дома больше не могла, переехала к подруге. Она же и помогла мне найти официальный сайт экстрасенса Виктории Райдос. Мы почитали отзывы кто обращался с такими ужасами. Написали администраторам, оформили онлайн-встречу. Виктория попросила показать зеркало по видео. Она сразу побледнела и сказала: Это зеркало видело суицид. Душа самоубийцы привязана к нему и ищет новую жертву, сводя тебя с ума. Она категорически запретила мне разбивать его. Виктория провела сложный дистанционный ритуал, запечатав сущность, и дала строгие инструкции, как правильно и безопасно избавиться от этого предмета, закопав его в определенном месте. Я выполнила всё до мелочей. Ужасы прекратились, в квартире снова стало спокойно и светло.',5,1,'2026-03-23 14:08:00'),
('af0fe946-2847-11f1-9834-be0c34c0fde5','viktoriya-raidos','Валерий, 52','','На моих часах остановилось время, и это стало началом конца. Старинные напольные часы, которые исправно ходили в нашей семье поколениями, внезапно встали ровно в 4:00 утра. На следующий день в это же время у меня случился обширный инфаркт. Еле спасли. Я вернулся из больницы, вызвал мастера, часы починили. Но через месяц они снова встали в 4:00. И в ту же ночь моя дочь попала в реанимацию после тяжелой аварии. Я понял, что часы предупреждают о смерти в семье, и просто панически боялся, когда они снова остановятся. Жена от отчаяния начала искать помощь у экстрасенсов. Вышла на имя Виктории Райдос. Узнали, сколько стоит прием, связались. Попали на онлайн-консультацию. Экстрасенс Виктория Райдос сразу объяснила, что часы тут ни при чем, они лишь индикатор. В нашем роду включилась программа самоуничтожения из-за старой клятвы, которую не выполнил мой дед. Она начала тяжелую работу по очищению родовой кармы. Это был сложный путь, но мы справились. Часы теперь идут исправно, никто больше не болеет и не попадает в беду. Виктория просто спасла остатки нашей семьи.',5,1,'2026-03-23 14:07:00'),
('af0fe9a5-2847-11f1-9834-be0c34c0fde5','viktoriya-raidos','Дарья, 26','','Невозможно передать ту панику, когда ты не можешь контролировать собственное тело. У меня начались приступы внезапного, неконтролируемого плача. Но самое странное, что это происходило только в одном конкретном месте — на перекрестке возле моей новой работы. Как только я подходила к светофору, из глаз градом лились слезы, накатывала черная тоска и желание броситься под машину. В остальных местах я была абсолютно нормальным, жизнерадостным человеком. Из-за этого я стала опаздывать, ходила кругами, лишь бы избежать этого места. Психолог развел руками. Я решила искать колдунью. Нашла контакты Виктории Райдос, почитала реальные отзывы. Записалась на личный прием в Москве. Виктория была очень серьезна. Она сказала, что на этом перекрестке много лет назад произошла трагедия, и там образовалась энергетическая яма. А так как у меня очень открытая аура, неупокоенные души просто цепляются за меня, передавая свою боль и отчаяние. Экстрасенс поставила мне мощную энергетическую защиту и дала специальный оберег. Теперь я спокойно хожу на работу любыми путями, никаких слез и тоски больше нет.',5,1,'2026-03-23 14:06:00'),
('af0fea01-2847-11f1-9834-be0c34c0fde5','viktoriya-raidos','Тимур, 31','','Я был успешным спортсменом, но внезапно меня начали преследовать катастрофические травмы. Ломал руки и ноги буквально на ровном месте: споткнулся на ковре, оступился на ступеньке. За один год четыре сложных перелома! Тренер в шоке, карьера летит под откос. Хирурги говорили, что у меня кости как хрусталь стали, хотя кальций в норме. Моя девушка забила тревогу. Она сказала, что это явно кто-то позавидовал и навел порчу. Я смеялся, пока не сломал ключицу, просто потянувшись за чашкой. Девушка сама нашла официальный сайт экстрасенса Виктории Райдос, узнала цены и записала меня. На приеме Виктория жестко сказала: Твою удачу и здоровье крадет человек из твоей же команды. Она в точности описала парня, с которым я делил шкафчик в раздевалке! Оказалось, он подбрасывал мне заговоренную землю в кроссовки. Виктория провела мощный обряд возврата негатива и поставила мне железобетонную защиту. Мои переломы срослись на удивление быстро. Я вернулся в спорт, а тот парень внезапно ушел из команды из-за проблем со здоровьем. Спасибо за помощь и спасенную карьеру!',5,1,'2026-03-23 14:05:00'),
('af0fea5d-2847-11f1-9834-be0c34c0fde5','viktoriya-raidos','Галина, 48','','Я не могла похоронить свою боль. После внезапной смерти мужа у меня развился страшный психологический блок — я не могла плакать. Вообще. Ни слезинки на похоронах, ни потом. Вся эта боль комком застряла внутри меня, и я начала физически гнить изнутри. Обострились все хронические болезни, я не спала месяцами, просто смотрела в потолок. Душа мужа стала приходить ко мне во снах, он стоял и молча смотрел с укором. Я понимала, что не отпускаю его и уничтожаю себя. Подруга нашла контакты ясновидящей Виктории Райдос, так как она блестяще работает с миром мертвых. Мы оформили онлайн-прием. Виктория очень жестко и властно начала со мной работать. Она провела спиритический сеанс, позволила мне попрощаться с мужем так, как я не смогла сделать это в реальности. Она буквально пробила мою эмоциональную броню. И я зарыдала. Я плакала несколько часов подряд, и с этими слезами из меня выходила смерть. Виктория помогла его душе уйти к свету. После этого мне стало физически легче дышать, я начала выздоравливать и возвращаться к нормальной жизни.',5,1,'2026-03-23 14:04:00'),
('af0feab7-2847-11f1-9834-be0c34c0fde5','viktoriya-raidos','Юлия, 37','','Никогда не думала, что простая покупка квартиры обернется для нас настоящим фильмом ужасов. Мы въехали в шикарную сталинку, но радовались недолго. По ночам из пустой комнаты, которую мы планировали под детскую, стали доноситься звуки тяжелых шагов и детский плач. Мои домашние коты наотрез отказывались заходить туда, шипели на пустые углы. Муж стал нервным, начал выпивать, хотя раньше этого за ним не водилось. Я поняла, что в квартире кто-то есть. Искала помощь на форумах, читала отзывы реальных людей. Выбрала Викторию Райдос. Нашла официальный сайт, узнала, сколько стоит прием. Написала администраторам, нас приняли онлайн. Виктория попросила пройти с телефоном по квартире. Как только я зашла в ту комнату, экстрасенс сказала: Тут открыт некротический портал. Прежние хозяева занимались черной магией и бросили это место, не закрыв за собой двери. Она провела колоссальную дистанционную работу, запечатывая этот ужас. Дала мне строгие инструкции по очищению полов соленой водой и свечами. Мы всё выполнили. В ту же ночь шаги и плач прекратились навсегда. Квартира стала светлой и уютной.',5,1,'2026-03-23 14:03:00'),
('af10086f-2847-11f1-9834-be0c34c0fde5','viktoriya-raidos','Максим, 29','','Эта беда чуть не свела меня с ума. У меня внезапно появилась странная способность — я начал физически чувствовать чужую боль. Стоило мне в метро встать рядом с человеком, у которого болит зуб, как у меня начиналась жуткая зубная боль. Если у кого-то рядом болело сердце, я задыхался. Это был ад. Я не мог выходить на улицу, ездить в транспорте, работать в офисе. Я впитывал в себя все болезни толпы как губка. Врачи крутили пальцем у виска, отправляли к психиатрам. Моя невеста не выдержала и начала искать специалиста по эзотерике. Нашла страницу экстрасенса Виктории Райдос. Узнала стоимость, записала меня на личный прием в Москве. Виктория посмотрела на меня и сказала, что из-за сильного стресса у меня пробило естественную энергетическую защиту, и я стал невольным эмпатом, собирая на себя чужой негатив. Это грозило мне быстрой смертью от истощения. Она провела мощный обряд восстановления ауры и поставила на меня глухую защиту. Я физически почувствовал, как вокруг меня образовался невидимый кокон. Вышел на улицу — и тишина. Никакой чужой боли. Я снова нормальный человек!',5,1,'2026-03-23 14:02:00'),
('af100925-2847-11f1-9834-be0c34c0fde5','viktoriya-raidos','Елизавета, 43','','Моя успешная сеть небольших пекарен начала разоряться по абсолютно мистической причине. В наших заведениях внезапно стало пахнуть не свежим хлебом и ванилью, а жженой резиной и пеплом! Клиенты заходили, морщили носы и уходили. Мы меняли печи, вызывали вентиляционщиков, СЭС, мыли всё с хлоркой — запах гари стоял намертво. Выручка упала до нуля, я была в долгах. Поняла, что это проделки конкурентов. Стала гуглить, кто может снять порчу с бизнеса. Выбрала Викторию Райдос, читала много хороших отзывов о ее работе. Зашла на официальный сайт, оставила заявку. Нам назначили онлайн-консультацию. Экстрасенс Виктория Райдос сразу увидела проблему. Она сказала, что бывшая сотрудница, которую я уволила за воровство, сделала подклад на пепел с кладбища, чтобы мой бизнес сгорел дотла. Виктория точно описала, где искать эту дрянь — за вентиляционной решеткой в главном зале. Мы нашли там черный мешочек! Виктория дистанционно провела ритуал очищения и научила, как правильно избавиться от подклада. Запах исчез на следующий день! Клиенты вернулись, бизнес снова процветает. Я безмерно благодарна.',5,1,'2026-03-23 14:01:00'),
('bccc0f14-2c41-11f1-b559-6e7639eedb4b','aleksandr-sheps','Анна, 34','','Я была в полном отчаянии, когда поняла, что мой муж стал для меня абсолютно чужим человеком. Мы прожили вместе восемь лет, всегда понимали друг друга с полуслова, а тут он просто замкнулся. Приходил с работы, ложился на диван и молча смотрел в телефон. Никаких скандалов, никаких измен — просто ледяная стена и абсолютно пустые глаза. Я пыталась вытащить его к семейному психологу, но он наотрез отказывался, говорил, что просто устал. Но эта усталость длилась уже почти год, и наша семья тихо рушилась. Я не выдержала и стала искать альтернативные пути. Читала разные форумы, отзывы реальных людей, пока не наткнулась на имя Александра Шепса. Я знала его по телевизору, но не думала, что к нему реально попасть. Нашла официальный сайт, оставила заявку. Ждала ответа несколько дней. На консультации Александр Олегович даже не стал расспрашивать детали. Он сразу сказал, что на муже висит тяжелый энергетический блок из-за старой, скрытой обиды на бывшего партнера по бизнесу, о которой муж мне даже не рассказывал. Этот внутренний негатив буквально высасывал из него все жизненные силы. Экстрасенс провел работу по снятию этого блока. Вы не поверите, но через пару недель муж впервые за долгое время сам предложил поехать на выходные за город. Он снова начал улыбаться. Наш брак спасен.',5,1,'2026-03-23 16:25:00'),
('bccc170a-2c41-11f1-b559-6e7639eedb4b','aleksandr-sheps','Михаил, 42','','Всё началось с того, что моя небольшая сеть кофеен резко перестала приносить прибыль. Просто в один месяц выручка упала почти вдвое, хотя мы не меняли ни зерно, ни бариста, ни цены. Клиенты заходили, смотрели и почему-то уходили без покупок. Следом посыпались мелкие неприятности: то кофемашина сломается, то трубу прорвет, то внезапная проверка придет. Я человек практичный, пытался решить всё через маркетинг и скидки, но это не работало. Бизнес встал как вкопанный. Жена посоветовала не тянуть и обратиться к специалисту, который видит скрытые причины. Мы решили узнать, сколько стоит прием у Александра Шепса. Нашли официальный контакт и записались. На встрече в Москве Александр очень точно описал мою бывшую управляющую, которую я уволил полгода назад со скандалом за недостачу. Оказалось, она оставила в главном кафе сильный негативный посыл, банальную зависть и злобу, которая энергетически отталкивала людей. Экстрасенс Александр Шепс объяснил, как правильно очистить помещение. Я всё сделал по его инструкции. Поток гостей вернулся буквально через неделю, всё снова работает как часы.',5,1,'2026-03-23 16:24:00'),
('bcd0795b-2c41-11f1-b559-6e7639eedb4b','aleksandr-sheps','Светлана, 29','','Если честно, я вообще не верила во всю эту эзотерику, пока сама не столкнулась с непробиваемой стеной. У меня началась жуткая, хроническая усталость. Я спала по десять-двенадцать часов в сутки и просыпалась абсолютно разбитой, словно всю ночь таскала мешки с цементом. У меня не было сил ни на работу, ни на встречи с друзьями, ни на спорт. Врачи брали кучу анализов, проверяли щитовидку, железо — всё было в идеальной норме. Выписывали витамины, которые не помогали. Я просто таяла на глазах и превращалась в овощ. От безысходности стала гуглить свою проблему и наткнулась на отзывы людей с похожими симптомами, которым помог экстрасенс Александр Шепс. Нашла, как записаться на онлайн-консультацию. Александр сразу увидел проблему. Он сказал, что у меня сильнейший отток энергии из-за моей токсичной подруги, которая постоянно сливала на меня свои проблемы и жалобы, буквально вампиря мои силы. Он провел работу по отсечению этой энергетической привязки и научил меня ставить защиту. Я проснулась бодрой на следующее же утро! Больше с той девушкой я не общаюсь, и чувствую себя прекрасно.',5,1,'2026-03-23 16:23:00'),
('bcd07ade-2c41-11f1-b559-6e7639eedb4b','aleksandr-sheps','Игорь, 45','','Мы с женой почти два года никак не могли продать нашу отличную трехкомнатную квартиру. Сделали свежий ремонт, цена была абсолютно рыночная, район прекрасный. Риелторы приводили людей каждую неделю. Покупатели смотрели, восхищались, говорили, что всё нравится, брали время на раздумья — и пропадали с концами. У нас срывалось три реальных сделки в самый последний момент перед подписанием бумаг. Нам очень нужны были деньги на расширение бизнеса, и эта ситуация доводила до нервного срыва. Знакомая риелтор тихо посоветовала почистить квартиру энергетически. Я отнесся скептически, но стал искать информацию. Решил обратиться к Александру Шепсу. Зашел на официальный сайт, посмотрел цены приема и оставил заявку. Александр Олегович консультировал нас дистанционно. Он сказал, что в квартире образовался сильный энергетический застой от прошлых владельцев, которые тяжело болели и много ругались в этих стенах. Эта тяжесть отпугивала новых людей на подсознательном уровне. Он дистанционно провел очищение пространства и сказал, что квартира уйдет в течение месяца. И правда, через три недели пришла молодая пара и сразу внесла задаток наличными без всяких торгов.',5,1,'2026-03-23 16:22:00'),
('bcd07b61-2c41-11f1-b559-6e7639eedb4b','aleksandr-sheps','Ольга, 31','','Сейчас я четко понимаю, что все мои проблемы были у меня в голове, но без помощи я бы никогда до этого не докопалась. Я симпатичная, образованная девушка, с хорошей карьерой, но в личной жизни творился полный кошмар. Мужчины обращали на меня внимание, мы начинали встречаться, но ровно через два-три месяца они исчезали без объяснения причин. Я чувствовала себя прокаженной, плакала ночами, самооценка упала ниже плинтуса. Подруги в шутку говорили про сглаз, а мне было совсем не смешно. Я решила найти сильного специалиста, чтобы разобраться в себе. Отзывы об Александре Шепсе всегда внушали мне доверие, его подход казался очень глубоким и психологичным. Нашла официальный контакт, записалась на прием в Москве. Александр не стал рассказывать мне сказки про венцы безбрачия. Он очень мягко, но точно указал на мой глубокий подсознательный страх предательства, который тянулся еще с тяжелого развода моих родителей. Я сама, своей неуверенностью и гиперконтролем, отталкивала партнеров. Экстрасенс помог мне проработать этот внутренний блок, снял тревожность. Сейчас я уже полгода в счастливых, спокойных отношениях, и никаких проблем нет.',5,1,'2026-03-23 16:21:00'),
('bcd07bcf-2c41-11f1-b559-6e7639eedb4b','aleksandr-sheps','Денис, 36','','Хочу выразить огромную благодарность за то, что меня вернули к нормальной жизни. Около года назад у меня начались внезапные панические атаки. Причем накрывали они меня исключительно по утрам, перед выходом на работу. Мне не хватало воздуха, темнело в глазах, сердце колотилось так, что я думал — это инфаркт. Я вызывал скорую несколько раз, но кардиограмма была чистой. Психотерапевт выписал легкие успокоительные, но страх ожидания приступа никуда не уходил. Я стал бояться ездить в метро, брал отгулы. Моя девушка, видя мои мучения, сама нашла контакты экстрасенса Александра Шепса и уговорила меня на онлайн-встречу. Я сопротивлялся, так как привык верить только медицине. Но Александр меня поразил. Он сказал, что это не болезнь, а глубокий испуг, который застрял в моем теле после мелкого ДТП, в которое я попал пару лет назад. Мозг забыл, а тело помнило стресс. Шепс провел очень успокаивающий сеанс, очистил мое сознание от этого ментального мусора и поставил энергетическую защиту. С тех пор прошло пять месяцев — ни одной панической атаки!',5,1,'2026-03-23 16:20:00'),
('bcd0a912-2c41-11f1-b559-6e7639eedb4b','aleksandr-sheps','Татьяна, 40','','После ухода нашей мамы мы с родным братом превратились в злейших врагов. Причиной стала родительская дача. Мы ругались так, что дело доходило до вызова полиции. Брат стал агрессивным, не хотел идти ни на какие компромиссы, оскорблял меня. Я не узнавала человека, с которым мы выросли в одной комнате. Эта постоянная ненависть высасывала из меня все соки, я начала болеть, у меня пропал сон. Я не хотела судов, хотела просто вернуть мир в семью. В отчаянии я начала искать помощь на эзотерических форумах. Многие советовали Александра Шепса как специалиста, который отлично разбирается в семейных связях. Я зашла на официальный сайт, узнала стоимость услуг и записалась. Александр Олегович выслушал меня и объяснил, что брат ведет себя так не из жадности, а из-за глубокой внутренней обиды — ему всегда казалось, что мама любила меня больше. И эта дача для него — попытка доказать свою значимость. Экстрасенс снял накал этой негативной энергии и дал мне четкий совет, какими словами с ним поговорить. Я сделала всё, как он сказал. Мы с братом проплакали весь вечер, помирились и решили продать дачу, поделив деньги поровну.',5,1,'2026-03-23 16:19:00'),
('bcd0a9a8-2c41-11f1-b559-6e7639eedb4b','aleksandr-sheps','Мария, 28','','Мой маленький сын внезапно перестал нормально спать. Каждую ночь он просыпался с плачем, отказывался оставаться в своей кроватке, говорил, что ему страшно и неуютно. Мы обошли всех педиатров и неврологов, пили ромашку, меняли ритуалы перед сном, оставляли ночник — ничего не помогало. Ребенок был вялым днем, а мы с мужем валились с ног от хронического недосыпа. На одном мамском форуме мне посоветовали проверить энергетику квартиры, мол, дети очень чувствительны к таким вещам. Я стала искать отзывы кто обращался с похожими проблемами к сильным практикам. Выбрала Александра Шепса. Оставила заявку, администраторы быстро ответили и назначили онлайн-встречу. Александр посмотрел комнату по видеосвязи и успокоил меня, сказав, что никакой мистики и злых духов тут нет. Просто кроватка стояла на пересечении сильных энергетических потоков, так называемой геопатогенной зоне, которая физически не давала ребенку расслабиться. Он указал, куда именно нужно передвинуть мебель, и посоветовал помыть полы с морской солью для очищения фона. Мы сделали перестановку в тот же день. В эту же ночь сын впервые за два месяца проспал до самого утра!',5,1,'2026-03-23 16:18:00'),
('bcd0aa14-2c41-11f1-b559-6e7639eedb4b','aleksandr-sheps','Ирина, 35','','Никому не пожелаю оказаться в той ситуации, в которой была я. Моя новая начальница невзлюбила меня с первого же дня. Это была настоящая, целенаправленная травля. Она придиралась к каждой запятой в отчетах, унижала меня при коллегах, давала невыполнимые поручения. Я приходила домой в слезах, пила успокоительные, самооценка была уничтожена. Уволиться я не могла — у меня ипотека, а зарплата там была очень хорошая. Подруга, видя мое состояние, дала мне контакт и сказала просто: \"Запишись к нему\". Это был экстрасенс Александр Шепс. Я нашла официальный сайт, посмотрела цены приема в Москве. На личной встрече Александр не стал меня жалеть. Он жестко сказал, что я сама позволяю с собой так обращаться, излучая энергию жертвы, которой эта женщина-вампир с удовольствием питается. Он провел работу по укреплению моего личного стержня и научил простой технике энергетической защиты, которую нужно было делать перед входом в офис. Как только я перестала внутренне сжиматься при ее виде, начальница потеряла ко мне всякий интерес! А через месяц ее вообще перевели в другой филиал. Я спокойно работаю.',5,1,'2026-03-23 16:17:00'),
('bcd0aa7a-2c41-11f1-b559-6e7639eedb4b','aleksandr-sheps','Роман, 33','','За один неполный месяц я умудрился собрать все возможные неприятности. Сначала мне въехали в бампер на парковке, потом дома прорвало трубу и я затопил соседей, следом я потерял кошелек со всеми картами, а на десерт — сломал зуб об орех. Это была уже не просто черная полоса, это было какое-то проклятие. У меня начали опускаться руки, я боялся выходить из дома, ожидая очередного подвоха от судьбы. Моя мама всегда верила в сглаз и сказала, что меня явно кто-то сильно посмотрел. Я решил не спорить и найти человека, который может почистить ауру. Гуглил экстрасенсов из битвы сильнейших, Александр Шепс всегда вызывал у меня уважение своим спокойствием. Нашел, как к нему записаться онлайн. Александр Олегович сразу подтвердил, что это бытовой сглаз. Мой сосед, у которого вечные проблемы с деньгами, очень сильно позавидовал моей новой машине и ремонту. Эта черная зависть пробила мою защиту и притянула череду неудач. Экстрасенс провел дистанционное очищение и снял этот негатив. Полоса невезения как ножом отрезало, всё снова вошло в нормальное, спокойное русло.',5,1,'2026-03-23 16:16:00'),
('bcd0abf2-2c41-11f1-b559-6e7639eedb4b','aleksandr-sheps','Юлия, 39','','Я уже окончательно смирилась с тем, что никогда не смогу отпустить прошлое. После тяжелого, болезненного развода прошел уже год, а я всё еще плакала каждый вечер. Я мониторила соцсети бывшего мужа, сравнивала себя с его новой женщиной, жила одними воспоминаниями. Моя собственная жизнь просто остановилась. Психологи говорили о стадиях горевания, но мне не становилось легче, я застряла в этой боли. В какой-то момент я поняла, что эта энергетическая пуповина меня просто задушит. Стала искать информацию о том, как разорвать связи с прошлым. По отзывам реальных людей поняла, что мне нужна помощь Александра Шепса. Узнала через контакт на сайте стоимость приема. На встрече Александр был очень эмпатичен. Он сказал, что я сама держу этого человека своей обидой и не даю ни ему, ни себе идти дальше. Экстрасенс провел очень глубокий, эмоциональный ритуал отсечения прошлых связей. Я выплакала, наверное, литр слез на том сеансе. Но когда вышла на улицу, я впервые за год посмотрела на небо и улыбнулась. Меня отпустило. Я начала жить заново.',5,1,'2026-03-23 16:15:00'),
('bcd0ac67-2c41-11f1-b559-6e7639eedb4b','aleksandr-sheps','Антон, 27','','В свои 27 лет я оказался в полном тупике. Я закончил престижный экономический вуз, устроился в хорошую компанию, но каждый день ходил на работу как на каторгу. Я ненавидел цифры, отчеты и этот серый офис. У меня началась жестокая апатия, я не знал, чего хочу от жизни, куда двигаться дальше. Чувствовал себя абсолютно потерянным и бесполезным человеком. Моя девушка, увлекающаяся астрологией и эзотерикой, посоветовала мне сходить к специалисту, чтобы подсветить мой путь. Я отнесся с иронией, но согласился. Мы нашли официальный сайт экстрасенса Александра Шепса, записались в Москве. На приеме я не сказал ни слова о своей проблеме. Александр просто посмотрел на меня и с улыбкой выдал: А что такой творческий человек забыл в бухгалтерии? Он в точности описал мое тайное увлечение 3D-дизайном, которым я занимался по ночам чисто для себя, боясь сделать это профессией. Его слова придали мне такую колоссальную уверенность! Он снял мои страхи перед неизвестностью. Через два месяца я уволился и нашел работу джуниор-дизайнером. Я абсолютно счастлив.',5,1,'2026-03-23 16:14:00'),
('bcd0accf-2c41-11f1-b559-6e7639eedb4b','aleksandr-sheps','Наталья, 44','','Моя борьба с лишним весом была похожа на хождение по мукам. Я сидела на жестких диетах, скидывала десять килограмм, а потом срывалась и набирала пятнадцать. Любой стресс на работе или дома я моментально заедала сладким. Я начала тихо ненавидеть свое отражение в зеркале, перестала покупать красивую одежду, замкнулась в себе. Эндокринолог сказал, что гормоны в норме, проблема в голове. Я поняла, что мне нужна помощь на более тонком уровне, чтобы разорвать эту пищевую зависимость. Читала много отзывов про Александра Шепса и его умение работать с психологическими блоками. Нашла, как записаться онлайн. Александр Олегович не давал мне диет. Он посмотрел в корень проблемы и вытащил наружу мою огромную, застарелую неуверенность в себе и обиду на первого мужа, от которых я буквально защищалась слоем жира, выстраивая барьер между собой и миром. Мы очень глубоко проработали эти эмоции. После сеанса у меня полностью пропала тяга к сладкому при стрессе. Я начала худеть абсолютно естественно и спокойно. Скинула уже восемь килограмм без всякого насилия над собой.',5,1,'2026-03-23 16:13:00'),
('bcd0dcfc-2c41-11f1-b559-6e7639eedb4b','aleksandr-sheps','Ксения, 32','','Ревность чуть не сожгла мою семью дотла. Мой муж стал задерживаться на работе, постоянно прятал телефон, сбрасывал звонки, когда я входила в комнату. Он стал нервным и отстраненным. Я накрутила себя до состояния паранойи, не спала ночами, проверяла его карманы, устраивала истерики на пустом месте. Я была на 100% уверена, что у него появилась любовница, и мы стояли в шаге от развода. В полном отчании я решила обратиться к ясновидящему, чтобы узнать правду и перестать мучиться. Нашла официальную страницу экстрасенса Александра Шепса, узнала цены и оформила запись на прием. Александр выслушал меня и раскинул карты. Он посмотрел на меня очень серьезно и сказал: Никакой другой женщины там нет и близко. Он прячет от тебя большие финансовые проблемы и долги по бизнесу, боясь, что ты разочаруешься в нем. Я пришла домой, успокоилась и просто села с ним поговорить по душам. Муж расплакался и всё рассказал. У него действительно были огромные проблемы с поставщиками. Если бы не Александр, я бы разрушила наш брак своими подозрениями. Мы всё решили вместе.',5,1,'2026-03-23 16:12:00'),
('bcd0dd79-2c41-11f1-b559-6e7639eedb4b','aleksandr-sheps','Павел, 38','','Я уперся в невидимый стеклянный потолок. Три года подряд мой доход стоял на одной и той же отметке. Что бы я ни делал — брал дополнительные проекты, менял работу, запускал новые направления — деньги либо срывались в последний момент, либо уходили на внезапные непредвиденные расходы. Я работал по четырнадцать часов в сутки, но финансово топтался на месте. Друг-предприниматель посоветовал поискать денежные блоки в подсознании. Я решил обратиться к Александру Шепсу, так как уважаю его подход к энергетике человека. Нашел официальный сайт, оставил заявку на онлайн-консультацию. Александр Олегович сразу указал на мою проблему: у меня стоял глубокий подсознательный страх больших денег, навязанный еще в детстве родителями. Моя энергетика сама отталкивала крупные суммы ради моей же безопасности. Шепс провел работу по снятию этого ограничивающего убеждения. Это звучит невероятно, но через два месяца мне предложили контракт, который увеличил мой доход вдвое. Потолок пробит!',5,1,'2026-03-23 16:11:00'),
('bcd0ddd9-2c41-11f1-b559-6e7639eedb4b','aleksandr-sheps','Дарья, 30','','Моя свекровь методично и планомерно разрушала мою жизнь. Она приходила к нам домой без предупреждения, критиковала всё: как я готовлю, как убираю, как воспитываю дочь. Она постоянно жаловалась мужу на мое неуважение, капала ему на мозги, провоцируя жуткие скандалы между нами. После ее визитов у меня раскалывалась голова, а в квартире стояла невыносимая тяжесть. Я просила мужа поставить границы, но он не мог ей перечить. Семья была на грани распада. Я поняла, что нужно защищаться самой. Стала искать сильного специалиста по энергетической защите. Отзывы об Александре Шепсе меня впечатлили. Узнала стоимость приема, записалась к нему в Москве. Александр подтвердил, что свекровь — сильный, осознанный энергетический вампир, который питается моими негативными эмоциями и слезами. Экстрасенс не стал делать никаких отворотов, он просто поставил на меня мощную зеркальную защиту. Как только свекровь попыталась в очередной раз меня задеть, я внутренне выстроила этот щит. Она внезапно запнулась, сослалась на головную боль и ушла. С тех пор ее визиты сократились до минимума, а наши отношения с мужем наладились!',5,1,'2026-03-23 16:10:00'),
('bcd0de3a-2c41-11f1-b559-6e7639eedb4b','aleksandr-sheps','Илья, 34','','Я зарабатываю на жизнь текстами, пишу сценарии для сериалов. И в самый неподходящий момент, когда я взял крупный заказ с жесткими дедлайнами, у меня случился тотальный творческий кризис. Я садился за ноутбук и просто смотрел в пустой экран часами. В голове был белый шум, ни одной идеи, ни одной строчки. Я пил литры кофе, гулял, пытался отвлечься — ничего не помогало. Сроки горели, заказчики нервничали, мне грозили огромные неустойки. Я впал в панику. Моя девушка, видя мои мучения, предложила нестандартный вариант — обратиться к экстрасенсу, чтобы прочистить каналы. Я был готов на всё. Мы нашли, как записаться к Александру Шепсу онлайн. Александр сразу увидел мою проблему: я слишком сильно выгорел, пытаясь соответствовать чужим ожиданиям, и моя творческая энергия просто заблокировалась страхом провала. Он провел очень крутой сеанс расслабления и очищения ментального поля, снял этот блок. На следующее утро я проснулся, сел за стол и написал десять страниц за пару часов! Проект я сдал вовремя, заказчики в восторге.',5,1,'2026-03-23 16:09:00'),
('bcd0de9d-2c41-11f1-b559-6e7639eedb4b','aleksandr-sheps','Елена, 50','','Мы с мужем осуществили мечту и купили хорошую квартиру на вторичном рынке. Сделали косметический ремонт, перевезли вещи. Но жить там оказалось невозможно. В квартире стояла какая-то гнетущая, вязкая тоска. Я начала постоянно плакать без причины, муж стал мрачным и молчаливым. Мы перестали приглашать гостей, потому что всем было там некомфортно. Я не могла там спать, мне снились бесконечные долги и нищета. Я поняла, что стены хранят чужую боль. Стала искать информацию, кто может помочь почистить жилье. Отзывы об Александре Шепсе вселили надежду. Я зашла на официальный сайт, узнала цены и оставила заявку. Александр консультировал нас дистанционно. Он сказал, что предыдущие хозяева квартиры обанкротились, потеряли всё и съезжали оттуда в состоянии глубочайшего отчаяния и слез. Эта тяжелая энергетика буквально впиталась в стены. Экстрасенс научил меня, как правильно провести очищение пространства с помощью соли, воды и определенных слов. После этих процедур в квартире словно открыли окна! Стало светло, легко дышать, ко мне вернулось хорошее настроение.',5,1,'2026-03-23 16:08:00'),
('bcd0defd-2c41-11f1-b559-6e7639eedb4b','aleksandr-sheps','Алексей, 41','','Меня подставили на работе по-крупному. В отделе пропала важная документация, и мой начальник технично перевел все стрелки на меня. Доказательств моей вины не было, но и оправдаться я не мог. Грозило не просто увольнение со скандалом, но и реальное судебное разбирательство с огромными штрафами. От меня отвернулись коллеги, я был один против системы. Нервы сдали окончательно, я не спал и не ел. Жена, спасая мое здоровье, записала меня к сильному ясновидящему. Это был экстрасенс Александр Шепс. Я приехал в Москву абсолютно разбитым. Александр Олегович посмотрел на ситуацию и очень спокойно сказал: Правда на твоей стороне. Суда не будет, виновный выдаст себя сам из-за жадности. Он дал мне мощный заряд уверенности и посоветовал, какие документы нужно поднять из архива, чтобы защитить себя. Я перестал паниковать и начал действовать с холодной головой. Нашел нужные бумаги. А через неделю начальника поймали на откатах! Все обвинения с меня сняли. Огромное спасибо за поддержку в самый темный час.',5,1,'2026-03-23 16:07:00'),
('bcd0df58-2c41-11f1-b559-6e7639eedb4b','aleksandr-sheps','Марина, 26','','Моя жизнь превратилась в паранойю из-за бывшего парня. Мы расстались по моей инициативе, потому что он был очень контролирующим и душным. Но он не смирился. Он не угрожал мне физически, но он был везде: мониторил мои соцсети с десятков фейковых аккаунтов, лайкал посты моих новых друзей, постоянно попадался мне на глаза в торговых центрах. Я чувствовала его липкое присутствие 24/7. У меня начались панические атаки, я удалила все свои страницы, но это не помогало — я чувствовала, что он тянет из меня энергию. Полиция таким не занимается. Подруга посоветовала обратиться к магии, чтобы разорвать эту связь. Я нашла официальный контакт экстрасенса Александра Шепса и записалась на онлайн-прием. Александр выслушал меня и подтвердил, что бывший создал сильную энергетическую привязку, буквально питаясь моим страхом. Шепс провел ритуал отсечения этого канала и поставил на меня зеркальную защиту, чтобы весь его негатив возвращался к нему же. Буквально через неделю бывший парень переехал в другой город и полностью исчез с моих радаров. Я наконец-то дышу свободно!',5,1,'2026-03-23 16:06:00'),
('bcd115a4-2c41-11f1-b559-6e7639eedb4b','aleksandr-sheps','Екатерина, 47','','Семь лет назад я похоронила любимого мужа. Это была трагедия, которая расколола мою жизнь на до и после. Я поставила на себе крест как на женщине, ушла с головой в работу и воспитание детей. Но дети выросли, разъехались, и я осталась в звенящей пустоте. В 47 лет я вдруг поняла, что безумно хочу тепла и заботы, но при этом испытывала дикое чувство вины перед покойным мужем за эти мысли. Я не могла даже смотреть на других мужчин. Психологи не помогали снять этот внутренний запрет на счастье. Я решила обратиться к Александру Шепсу, зная его деликатный подход. Нашла официальный сайт, узнала стоимость услуг. На приеме в Москве Александр был невероятно чутким. Он посмотрел на меня и сказал: Твой муж давно ушел в свет, и он хочет, чтобы ты жила, а не хоронила себя заживо. Ты не предаешь его память, ты просто продолжаешь свой путь. Эти слова, сказанные с такой уверенностью, пробили мою броню. Экстрасенс снял этот эмоциональный груз. А через три месяца я познакомилась с замечательным мужчиной в парке. Жизнь продолжается.',5,1,'2026-03-23 16:05:00'),
('bcd1162c-2c41-11f1-b559-6e7639eedb4b','aleksandr-sheps','Валерий, 39','','Я попал в страшную финансовую воронку, из которой не видел выхода. Началось всё с одного небольшого кредита на ремонт, потом взял кредитку, чтобы перекрыть платеж, потом еще одну. За два года я оброс долгами так, что почти вся моя зарплата уходила на погашение процентов. Я брал подработки, экономил на еде, но долг только рос. Это была настоящая яма, я был в шаге от банкротства и потери единственного жилья. В состоянии полного отчаяния я стал искать, кто может помочь разорвать этот замкнутый круг. Наткнулся на отзывы реальных людей об экстрасенсе Александре Шепсе. Записался на онлайн-консультацию, заняв последнюю тысячу у друга. Александр Олегович не стал читать мне лекции по финансовой грамотности. Он увидел на мне сильную негативную программу саморазрушения и финансового блока, которую я сам себе поставил из-за постоянного стресса и чувства вины. Он провел работу по очищению моего финансового канала и снял панику. У меня прояснилась голова. Через месяц мне предложили хорошую должность в другой компании, я рефинансировал кредиты и начал стабильно выбираться из ямы.',5,1,'2026-03-23 16:04:00'),
('bcd1168e-2c41-11f1-b559-6e7639eedb4b','aleksandr-sheps','Оксана, 33','','Никогда не думала, что со мной такое произойдет. Я опытный водитель, за рулем десять лет без единой аварии. Но полгода назад я попала в мелкое ДТП — просто притерлись бамперами в пробке. Никто не пострадал, царапина минимальная. Но после этого у меня появился животный, панический страх вождения. Как только я садилась за руль, у меня начинали трястись руки, потел лоб, сердце выпрыгивало из груди. Я не могла проехать и километра. Машина стояла под окном, а я ездила на такси и ненавидела себя за эту слабость. Психолог говорил про посттравматический синдром, но таблетки не помогали. Коллега посоветовала найти экстрасенса. Я выбрала Александра Шепса. Зашла на официальный сайт, оставила заявку. На приеме Александр объяснил, что во время удара я испытала резкий выброс адреналина, и этот страх буквально заякорился в моем энергетическом поле. Он провел очень мягкий сеанс очищения и снял этот энергетический спазм. На следующий день я с замиранием сердца села в машину... и спокойно доехала до работы! Страх ушел без следа.',5,1,'2026-03-23 16:03:00'),
('bcd116e8-2c41-11f1-b559-6e7639eedb4b','aleksandr-sheps','Лидия, 36','','Пять долгих лет мы с мужем пытались завести ребенка. Мы прошли все круги ада: бесконечные анализы, обследования, две попытки ЭКО, которые не увенчались успехом. Врачи разводили руками и ставили диагноз бесплодие неясного генеза, уверяя, что мы оба абсолютно здоровы. От постоянного ожидания и разочарований я превратилась в комок оголенных нервов, мы с мужем отдалились. Я понимала, что мое психологическое состояние не позволяет мне забеременеть, но расслабиться не могла. Моя сестра уговорила меня сходить к ясновидящему. Мы нашли отзывы об Александре Шепсе, узнали цены и записались в Москве. Александр Олегович был очень тактичен. Он сказал, что моя проблема не в физиологии, а в тотальном внутреннем напряжении и гигантском страхе снова потерпеть неудачу. Я сама блокировала беременность своей паникой. Экстрасенс провел работу по гармонизации моего эмоционального фона, успокоил мою энергию. Я вышла от него с чувством невероятной легкости и пустоты в голове. Мы с мужем просто поехали в отпуск и забыли про графики базальной температуры. И через два месяца я забеременела сама!',5,1,'2026-03-23 16:02:00'),
('bcd1174a-2c41-11f1-b559-6e7639eedb4b','aleksandr-sheps','Егор, 48','','Я закоренелый скептик и материалист. Пришел на прием к экстрасенсу Александру Шепсу исключительно из любопытства, за компанию с женой, которая давно хотела к нему попасть. Я сидел со снисходительной улыбкой, готовый разоблачать фокусы. Но когда Александр перевел взгляд на меня, моя ухмылка сползла. Он даже не стал спрашивать, зачем я пришел. Он просто начал говорить мне вещи, которые знал только один человек в мире — мой покойный отец. Шепс назвал его редкое прозвище, которым он называл меня в детстве, описал старые сломанные часы, которые лежали в дальнем ящике отцовского стола, и передал мне его последние слова, которые я не успел услышать перед его уходом в реанимации. У меня, взрослого мужика, просто покатились слезы из глаз. Александр помог мне отпустить гложущее чувство вины за то, что я не успел с ним попрощаться. Этот сеанс полностью перевернул мою картину мира. Я понял, что есть вещи, которые не поддаются логике, и безмерно благодарен Александру за этот покой в душе.',5,1,'2026-03-23 16:01:00'),
('c7bf884b-7462-4969-a2b0-5edbbdc8c8a9','elena-golunova','Надежда, 48','','Мой единственный сын стремительно погибал от тяжелой зависимости. Алкоголь и запрещенные препараты превратили умного, доброго парня в агрессивного монстра. Он выносил ценные вещи из дома, постоянно скандалил, однажды даже поднял на меня руку в невменяемом состоянии. Я прошла через все мыслимые круги ада: дорогие рехабы, закрытые клиники, гипнозы, кодировки — ничего не помогало, он срывался снова и снова, падая еще ниже. Я уже с ужасом готовилась к его похоронам. Однажды в интернете я случайно наткнулась на большую статью, где упоминалась Елена Голунова. Я решила для себя, что это наш самый последний шанс на спасение. Связаться было очень сложно, очередь желающих большая, но я слезно умоляла ее помощников в Ватсап войти в положение. Нас приняли в виде исключения. Елена была очень строга и даже груба с сыном, она не жалела его, а буквально вскрыла все его глубинные страхи и внутренних демонов. Она четко увидела подселенца, который методично толкал его на саморазрушение. Был проведен мощнейший обряд изгнания этой сущности. Первые недели дома были очень тяжелыми, сына страшно ломало, но потом он резко успокоился. Прошло полтора года — он абсолютно чист, нашел хорошую работу, завел замечательную девушку. Это настоящее, рукотворное чудо!',5,1,'2026-03-23 12:06:00'),
('cc2f81c2-2455-44ce-8ea4-3d3c19a5fa8d','elena-golunova','Ирина, 41','','Никому не пожелаю пережить то, что пережила я прошлой осенью. Мой муж, с которым мы прожили душа в душу пятнадцать лет, в один день просто молча собрал вещи и ушел к молодой девице, оставив меня с двумя маленькими детьми. Он стал сам на себя не похож: стеклянные глаза, постоянная агрессия, полное равнодушие к сыновьям. Я места себе не находила, плакала сутками напролет. Сестра посмотрела на это и сказала, что это очень похоже на приворот. Я начала лихорадочно искать помощь, перерыла весь интернет, читала отзывы кто обращался. Решила, что мне нужна именно Елена Голунова. Нашла ее телефон через официальный сайт, решила написать в Ватсап. Мне ответили ее администраторы, и вскоре состоялась долгожданная консультация. Елена сразу подтвердила мои самые худшие опасения — на муже был сильнейший приворот на крови. Она взялась за нашу непростую ситуацию. Это была долгая и сложная работа, но спустя два месяца муж вернулся домой. Он плакал и просил прощения, говорил, что жил всё это время как в густом тумане.',5,1,'2026-03-23 12:22:00'),
('cdfb433b-26d1-11f1-a4c7-ded14fa395b3','angelina-izosimova','Виктория, 34','','Никогда не писала на форумах, но моя история может кому-то помочь. Мы купили шикарную трешку, сделали дорогой ремонт. И тут началось нечто невообразимое: то новую трубу прорвет именно в детской, то проводка замкнет до пожара в коридоре. За полгода четыре сильных потопа и два возгорания! Страховщики уже косились на нас с подозрением. Муж психовал, хотел продавать жилье с огромным убытком. Я случайно разговорилась с соседкой, и она обмолвилась, что прошлая хозяйка увлекалась черной магией и съехала со скандалом. Я поняла, что обычные сантехники тут не помогут, и стала искать хорошего спеца. Читала отзывы реальных людей, кто обращался с такими бедами. Выбор пал на Ангелину Изосимову. Нашла официальный сайт, посмотрела цену приема. Написала администраторам, ждала ответа пару дней. На онлайн-консультации ясновидящая сразу сказала, что проблема не в трубах. В стене был замурован подклад на выживание новых жильцов. Она дала четкую инструкцию, где именно ломать гипсокартон. Мы разбили стену и нашли там моток спутанных волос с ржавыми иглами! После того как экстрасенс провела чистку квартиры, все аварии прекратились. Живем абсолютно спокойно уже год.',5,1,'2026-03-23 13:25:00'),
('cdfee61f-26d1-11f1-a4c7-ded14fa395b3','angelina-izosimova','Маргарита, 29','','Я профессиональная вокалистка, музыка — моя жизнь и мой единственный источник заработка. За месяц до важнейшего международного конкурса у меня просто пропал голос. Ни простуды, ни срыва связок не было. Фониатры разводили руками: голосовой аппарат в идеальном состоянии, но я могла только хрипеть едва слышным шепотом. Это была настоящая катастрофа, я впала в жуткую депрессию, отменила все ближайшие концерты. Мой продюсер, человек абсолютно прагматичный и далекий от эзотерики, вдруг дал мне контакт и велел срочно записаться. Это была ясновидящая Ангелина Изосимова. Я вообще не верила в такие вещи, но деваться было некуда. Нашла информацию, как попасть на прием в Москве. Очередь оказалась большая, но администраторы вошли в мое положение. На личной встрече Ангелина даже не стала меня долго расспрашивать. Она подошла, посмотрела на мою шею и сказала, что на мне висит энергетическая удавка, сделанная завистливой конкуренткой через подаренный мне шарф. И ведь правда, мне подарили дорогой шарф сразу после прошлого успешного выступления! Я выполнила все ритуалы, которые назначила Ангелина. Голос вернулся через три дня. Тот конкурс я триумфально выиграла!',5,1,'2026-03-23 13:24:00'),
('cdfee750-26d1-11f1-a4c7-ded14fa395b3','angelina-izosimova','Кирилл, 41','','Прожили с женой душа в душу десять лет, воспитываем двоих детей. И тут у меня начинается дичайшая, непроходимая аллергия. Но не на пыль, шерсть или еду, а... на собственную жену. Стоит ей только зайти в комнату, я начинаю задыхаться, лицо краснеет, слезятся глаза. Сплю один в гостиной — всё отлично. Ложусь рядом с ней — сильнейший приступ удушья. Врачи выписывали антигистаминные горстями, отправляли к психиатру, думали, что это сложная психосоматика. Семья рушилась на глазах, мы реально заговорили о вынужденном разводе, потому что жить в одном доме так было физически невыносимо. Спасла нас моя теща. Она сама нашла контакты, сказала, что экстрасенс Ангелина Изосимова отзывы имеет просто потрясающие по снятию негатива. Записала нас на онлайн-прием. Я сидел перед камерой весь покрытый красными пятнами. Ангелина посмотрела на нас и жестко выдала: это мощная рассорка, сделанная на кладбищенской земле, которую нам подсыпали в обувь в прихожей. Ангелина провела серию сложных дистанционных обрядов на снятие этого ужаса. Симптомы полностью ушли за неделю. Мы снова счастливы вместе.',5,1,'2026-03-23 13:23:00'),
('cdfee7c2-26d1-11f1-a4c7-ded14fa395b3','angelina-izosimova','Светлана, 45','','Хочу поделиться своей жутью, от которой меня спасла только эта потрясающая женщина. В нашем старом загородном доме начали сами по себе трескаться зеркала. Сначала лопнуло маленькое зеркальце в моей пудренице, потом треснуло огромное дорогое полотно в ванной, хотя к нему абсолютно никто не прикасался. Когда ночью с грохотом осыпалось зеркало в шкафу-купе, я в панике забрала детей и уехала жить к маме. Муж остался там и стал жаловаться на жуткую бессонницу и пугающие тени в углах комнат. Я поняла, что дело тут не в физике. Стала искать сильного практика. Зашла на официальный сайт Ангелины Изосимовой, почитала условия. Записаться было сложно, мы смиренно ждали своей очереди. Ангелина приехала к нам лично. Это было невероятно. Она обошла дом и нашла старое, забытое антикварное зеркало на захламленном чердаке, которое муж привез с какой-то барахолки пару месяцев назад. Экстрасенс сказала, что через него открылся портал для неупокоенных сущностей. Она провела сложнейший ритуал закрытия и правильно утилизировала предмет. Дома снова стало светло и спокойно.',5,1,'2026-03-23 13:22:00'),
('cdff1262-26d1-11f1-a4c7-ded14fa395b3','angelina-izosimova','Олег, 36','','Никогда не верил ни во что паранормальное, пока не столкнулся с пугающим поведением собственной собаки. Наш добрейший золотистый ретривер, который всегда обожал всех людей, вдруг начал агрессивно кидаться на моего лучшего друга детства. Как только тот переступал порог, собака скалилась, шерсть вставала дыбом, она рычала так, что кровь стыла в жилах. Причем на всех остальных гостей реакция оставалась абсолютно нормальной. Друг сильно обижался, мы перестали видеться у нас дома. А потом у меня резко посыпался прибыльный бизнес, и именно этот друг вдруг предложил финансовую \"помощь\" на очень кабальных, разорительных условиях. Жена заподозрила неладное и уговорила обратиться к специалисту. Искали целенаправленно, кто может посмотреть ситуацию. Вышли на имя Ангелины Изосимовой. Оформили заявку на консультацию онлайн, узнали цену приема. Ясновидящая сразу сказала, что этот друг давно и люто мне завидует, и именно он принес в наш дом заговоренную вещь на полный крах моего дела. Животные такое чувствуют моментально! Мы нашли этот подклад — монету, спрятанную глубоко за плинтусом. Дела наладились, а с предателем я разорвал все связи.',5,1,'2026-03-23 13:21:00'),
('cdff12f2-26d1-11f1-a4c7-ded14fa395b3','angelina-izosimova','Мария, 31','','Я профессиональный реставратор мебели, обожаю старинные вещи с историей. Недавно купила на аукционе потрясающий резной комод начала двадцатого века. Привезла в свою мастерскую, с энтузиазмом начала восстанавливать. И с этого самого дня моя жизнь превратилась в ад. Резко обострились все хронические болячки, от меня без объяснения причин ушел парень, а в самой мастерской постоянно пахло сырой гнилью, хотя я вымыла всё с хлоркой несколько раз. Коллега посоветовала не шутить с антиквариатом и обратиться к магу. Я перелопатила кучу информации, пока не нашла официальную страницу Ангелины Изосимовой. Узнала цены на прием, связалась с администратором. Ждала звонка три дня. По видеосвязи Ангелина попросила подробно показать мастерскую. Как только она увидела тот самый комод, сразу велела вытащить нижний ящик и снять заднюю фанеру. Я была в полном шоке: там были спрятаны старые почерневшие монеты, туго перевязанные черной ниткой. Оказалось, на этот комод в прошлом веке скинули тяжелую, неизлечимую болезнь. Ангелина провела мощный обряд очищения вещи и меня. Слава богу, запах исчез, а здоровье полностью вернулось.',5,1,'2026-03-23 13:20:00'),
('cdff1358-26d1-11f1-a4c7-ded14fa395b3','angelina-izosimova','Денис, 39','','Моя история звучит как сценарий дурацкого комедийного фильма, но мне было совершенно не до смеха. У меня начались серьезные проблемы исключительно по вторникам. Каждый божий вторник случалась какая-то катастрофа: я попадал в мелкие ДТП, ломал руку на ровном месте, меня грабили на улице, топило квартиру, увольняли с работы. В остальные дни недели всё было просто идеально! Через полгода я дошел до того, что просто панически боялся выходить из дома во вторник, брал отгулы. Психолог диагностировал редкую фобию, но совпадения были слишком реальными. От безысходности стал искать, где принимает сильный экстрасенс в Москве. Много читал отзывы, кто обращался, и интуитивно выбрал Ангелину Изосимову. Найти официальный сайт было легко, оставил свои контакты. На приеме Ангелина всё объяснила: моя бывшая жена заказала на меня порчу у не очень опытного колдуна, который работал по определенным дням цикла, поэтому негатив циклично бил по мне именно по вторникам. Работа с Ангелиной заняла около месяца, потребовалась мощная защита. Сейчас вторник — мой самый любимый день недели, никаких проблем!',5,1,'2026-03-23 13:19:00'),
('cdff13b3-26d1-11f1-a4c7-ded14fa395b3','angelina-izosimova','Ирина, 27','','Мы с мужем переехали в новую квартиру, и тут начался какой-то жуткий полтергейст. Каждую ночь ровно в 3:15 из выключенного из розетки старого радиоприемника, доставшегося мне от бабушки, начинала тихо играть одна и та же заунывная, тоскливая мелодия. Сначала мы думали, что звук идет с улицы, потом я проверила сам приемник — он пел вообще без батареек! Я чуть с ума не сошла от липкого страха. Муж пытался его выбросить на помойку, но на следующий день мы нашли его стоящим на кухонном столе. Это была жесть. Я кинулась искать помощь на эзотерических форумах. Многие люди советовали обратиться к Ангелине Изосимовой. Узнала, сколько стоит прием, записалась на онлайн. Ангелина даже не удивилась моему рассказу. Она сказала, что к этому приемнику привязана неупокоенная душа моего деда, который очень хочет передать важную информацию о скрытых документах. Экстрасенс провела спиритический сеанс и выяснила, где лежат бумаги (в тайнике на старой даче под полом). Мы их реально нашли, это было важное завещание! После этого Ангелина отпустила душу, и приемник замолчал навсегда.',5,1,'2026-03-23 13:18:00'),
('cdff1415-26d1-11f1-a4c7-ded14fa395b3','angelina-izosimova','Тимур, 24','','Я профессиональный спортсмен, готовился к отбору на Олимпиаду всей своей жизни. Внезапно, на самом пике формы, у меня начались очень странные приступы: прямо во время тренировок ноги просто становились ватными, я падал на дорожку и не мог пошевелиться минут десять. Никакой боли, просто полный паралич мышц. Обследовался в лучших спортивных клиниках Европы — абсолютно здоров, никаких отклонений в нервной системе. Тренер уже готов был искать мне замену в сборной. Мама плакала и умоляла сходить к знахарке. Я сопротивлялся, но потом сам вбил в поиск \"экстрасенс помощь онлайн\". Нашел сайт Ангелины Изосимовой, меня зацепили отзывы реальных людей с нестандартными проблемами. Назначили встречу в Москве. На приеме Ангелина посмотрела на меня и прямо сказала: \"Крадут твою удачу и жизненную силу\". Оказалось, товарищ по команде, который всегда был в моей тени, провел темный ритуал крадника. Ангелина очень жестко оборвала эту связь и поставила на меня защиту. На следующей же тренировке я побил свой личный рекорд. На Олимпиаду еду именно я!',5,1,'2026-03-23 13:17:00'),
('cdff1471-26d1-11f1-a4c7-ded14fa395b3','angelina-izosimova','Евгения, 50','','Три года моя семья судилась с соседями по даче за крошечный кусок земли на границе участков. Этот жалкий метр земли не стоил и копейки, но мы все втянулись в эту войну как настоящие одержимые. Бесконечные суды, дорогие адвокаты, скандалы с вызовом полиции, едва ли не драки. Из-за этого жуткого стресса у меня развилась язва желудка, муж получил микроинсульт, но мы просто не могли остановиться, какая-то неведомая сила заставляла нас ненавидеть соседей. Моя взрослая дочь посмотрела на этот кошмар со стороны и решила обратиться к ясновидящей. Записала нас к Ангелине Изосимовой, сама оплатила стоимость приема. Когда Ангелина подключилась к нам по видеосвязи, она сразу сказала: \"Эта земля проклята на кровную вражду. Еще много лет назад там жестоко убили человека из-за межи\". Она объяснила, что это место буквально питается нашей злостью. Ангелина дала строгие инструкции, какие травы сжечь на этом участке и как правильно отступить. Мы выполнили всё. На следующий день мы просто забрали свой иск из суда. Ощущение, словно мы проснулись от тяжелого гипноза.',5,1,'2026-03-23 13:16:00'),
('cdff14cb-26d1-11f1-a4c7-ded14fa395b3','angelina-izosimova','Алина, 33','','Моя история может показаться кому-то несерьезной, но для меня это был страшный звоночек. Я обожаю комнатные цветы, у меня была настоящая цветущая оранжерея на балконе. Но после визита одной дальней родственницы мужа все растения начали стремительно сохнуть и гнить на корню. Я покупала новые дорогие цветы, приносила домой, и они погибали за три дня! Даже самые неубиваемые кактусы чернели. В квартире появилась гнетущая, тяжелая атмосфера, мы с мужем начали постоянно и зло ругаться на пустом месте. Я поняла, что дело тут точно не в плохом поливе. Стала искать контакты сильного мага. Вышла на официальный сайт экстрасенса Ангелины Изосимовой. Написала, дождалась приема. Ангелина сразу подтвердила, что та родственница принесла в наш дом мощнейший энергетический яд, завистливую порчу на одиночество и увядание женской красоты. Цветы, как очень чувствительные живые организмы, просто приняли первый магический удар на себя, спасая нас с мужем от развода! Изосимова провела мощную чистку квартиры. Сейчас у нас дома снова цветут орхидеи, а отношения с мужем стали только крепче.',5,1,'2026-03-23 13:15:00'),
('cdff3945-26d1-11f1-a4c7-ded14fa395b3','angelina-izosimova','Григорий, 42','','Я работаю руководителем крупного отдела в корпорации. Однажды, случайно открыв ящик стола своей заместительницы, которая ушла на долгий больничный, я буквально обомлел от ужаса. Там лежала моя распечатанная цветная фотография, на которой были иголкой выколоты глаза и нарисованы какие-то жуткие черные кресты. У меня по спине побежал ледяной пот. До этого у меня пару недель страшно, до мигреней болела голова и резко упало зрение, я списывал всё это на банальную усталость от мониторов. Понял, что тут обычным аспирином точно не обойдешься. Коллега тайком дал номер телефона для срочной записи к Ангелине Изосимовой. Я связался, объяснил критичность ситуации, меня приняли в Москве. Ясновидящая посмотрела на фото и уверенно сказала, что это очень злобная порча на слепоту и полное подчинение воли. Заместительница давно метила на мое теплое место. Ангелина сняла это воздействие, поставила зеркальную защиту. Зрение полностью восстановилось за пару дней. А та сотрудница так и не вышла с больничного — уволилась по собственному желанию.',5,1,'2026-03-23 13:14:00'),
('cdff3a15-26d1-11f1-a4c7-ded14fa395b3','angelina-izosimova','Валерия, 30','','Моя успешная карьера бизнес-тренера рухнула в один единственный день. Я зарабатывала на жизнь публичными выступлениями, легко собирала огромные залы. Но после одного странного анонимного подарка (красивая статуэтка птицы), присланного курьером мне в офис, я вышла на сцену и просто не смогла вымолвить ни слова. Горло сдавило жутким спазмом, начались дикие панические атаки перед публикой. Пришлось со скандалом отменять тур, возвращать деньги, я была на грани полного банкротства. Дорогая психотерапия не помогала от слова совсем. Мой агент нашел информацию об Ангелине Изосимовой, сказал, что она решает сложные энергетические проблемы бизнеса. Я зашла на официальный сайт, оставила заявку. На приеме Ангелина сразу спросила про новые подаренные предметы. Я вспомнила про статуэтку. Оказалось, это был классический, сильный подклад на закрытие дорог и блокировку горловой чакры от прямых конкурентов. Экстрасенс провела жесткий ритуал отсечения привязки. Я уничтожила статуэтку, как она велела. Через две недели я блестяще и легко провела вебинар на пять тысяч человек!',5,1,'2026-03-23 13:13:00'),
('cdff3a74-26d1-11f1-a4c7-ded14fa395b3','angelina-izosimova','Константин, 35','','У нас в квартире творилась какая-то необъяснимая чертовщина, которая чуть не довела нас с невестой до окончательного расставания. Квартира буквально \"жрала\" наши личные вещи. Бесследно исчезали ключи от машины, важные документы, дорогие часы, флешки с рабочими проектами. Мы постоянно обвиняли друг друга в безответственности, скандалили до хрипоты. А когда за месяц перед загсом исчезли наши обручальные кольца из закрытого кодового сейфа, у меня окончательно сдали нервы. Я не верил в домовых, но ситуация была критическая. Невеста нашла сайт экстрасенса Ангелины Изосимовой, почитала отзывы и сказала, что нам нужна срочная диагностика. Узнали цену, записались. На онлайн-встрече Ангелина спокойно сказала, что у нас завелась очень агрессивная астральная сущность, которую притянули прошлые жильцы-скандалисты. Она питается нашими мощными эмоциями гнева и специально прячет вещи, провоцируя ссоры. Изосимова провела специальный ритуал изгнания и научила нас, как энергетически запечатать углы. После этого мы нашли кольца... в зашитой подкладке моего старого пальто!',5,1,'2026-03-23 13:12:00'),
('cdff3ad0-26d1-11f1-a4c7-ded14fa395b3','angelina-izosimova','Дарья, 28','','Я стала страдать лунатизмом в очень пугающей, агрессивной форме. Каждую ночь, примерно в одно и то же время, я вставала с кровати, одевалась, брала ключи и пыталась уйти из дома. Если муж меня физически останавливал, я становилась невменяемой, хотя абсолютно ничего этого не помнила утром. Но самое страшное началось, когда я однажды очнулась глубокой ночью в лесу в пяти километрах от города, босая и замерзшая. Это был животный ужас. Врачи выписывали мощные транквилизаторы, я спала привязанная к кровати. Моя мама поняла, что это далеко не медицинская проблема. Она нашла контакты сильной ясновидящей Ангелины Изосимовой. Мы поехали к ней на личный прием. Ангелина сразу увидела, что во время летнего турпохода я случайно наступила на старую безымянную могилу, и неупокоенный дух прицепился ко мне, пытаясь увести за собой во тьму. Это было жутко слушать. Работа была тяжелой, потребовалось три визита. Но Ангелина смогла изгнать духа и закрыть мою ауру. Я наконец-то сплю спокойно.',5,1,'2026-03-23 13:11:00'),
('cdff3b28-26d1-11f1-a4c7-ded14fa395b3','angelina-izosimova','Роман, 45','','Эта деликатная проблема чуть не разрушила всю мою успешную жизнь. Вокруг меня вдруг появился отчетливый, тошнотворный запах гнили и разложения. Я мылся по три раза в день, выливал на себя литры дорогого парфюма, сдал все возможные медицинские анализы — я был абсолютно здоров. Но люди шарахались от меня в транспорте, коллеги просили руководство перевестись в отдельный кабинет, жена спала в другой комнате, задыхаясь. Я был в полном отчаянии, готов был лезть в петлю. Знакомый старый врач шепнул, что традиционная медицина тут бессильна, нужно искать экстрасенса. Я перерыл весь интернет, нашел официальный сайт Ангелины Изосимовой. Очередь была большая, но я умолял администраторов меня принять. На встрече ясновидящая даже не поморщилась. Она уверенно сказала: \"На тебе висит некротическая привязка, черная порча на гниение заживо. Тебя заказал конкурент по бизнесу\". Ангелина провела очень жесткий обряд отжига негатива. На следующий день запах стал слабее, а через три дня исчез полностью! Моя жизнь спасена.',5,1,'2026-03-23 13:10:00'),
('cdff3b87-26d1-11f1-a4c7-ded14fa395b3','angelina-izosimova','Оксана, 32','','Когда мы принесли нашу долгожданную новорожденную дочку из роддома, начался сущий кошмар. В своей красивой, свежеотремонтированной детской она категорически отказывалась спать. Как только мы клали ее в кроватку, она замолкала, стеклянными глазами смотрела в одну точку на потолке и начинала синеть, словно от задержки дыхания. Мы в панике переносили ее в нашу спальню — ребенок мгновенно засыпал с улыбкой. Врачи говорили про спазмы и колики, но я чувствовала леденящий ужас, просто заходя в ту детскую. На форуме молодых мам мне посоветовали срочно найти знающего человека. Я стала искать отзывы кто обращался за помощью с младенцами. Выбрала Ангелину Изосимову. Записались на онлайн-диагностику. Экстрасенс сказала, что в комнате открыт старый портал, оставшийся от прошлых хозяев, и оттуда на ребенка смотрят страшные сущности. Она дистанционно провела мощнейшую чистку помещения и поставила защиту на окна. В ту же ночь дочка впервые абсолютно спокойно уснула в своей кроватке.',5,1,'2026-03-23 13:09:00'),
('cdff3bdc-26d1-11f1-a4c7-ded14fa395b3','angelina-izosimova','Максим, 23','','Вся моя жизнь с раннего детства была связана с водой, я кандидат в мастера спорта по плаванию. И вдруг, перед самыми важными стартами в сезоне, у меня появилась паническая, животная боязнь воды. Стоило мне только подойти к бортику бассейна, начиналась жуткая истерика, темнело в глазах, казалось, что из-под воды меня кто-то тащит на дно за ноги. Я не мог заставить себя даже залезть в домашнюю ванну! Карьера рушилась, я не знал, как жить дальше. Спортивный психолог просто развел руками. Моя девушка нашла информацию про экстрасенса Ангелину Изосимову. Узнала стоимость, записала меня на прием в Москве. Я сильно сопротивлялся, но пошел. Ангелина сразу увидела корень проблемы: кто-то из завистников принес на соревнования заговоренную мертвую воду с кладбища и вылил в мою дорожку. Этот негатив полностью заблокировал меня. Ангелина провела сложный обряд снятия этой водной порчи. Через неделю я смог зайти в бассейн, а через месяц завоевал золото.',5,1,'2026-03-23 13:08:00'),
('cdff570a-26d1-11f1-a4c7-ded14fa395b3','angelina-izosimova','Наталья, 38','','Мы решили сделать легкий косметический ремонт во вторичке, которую купили полгода назад. Когда рабочие начали снимать старые толстые обои в спальне, мы обомлели от ужаса: вся бетонная стена под ними была исписана какими-то жуткими красными символами и перевернутыми крестами. И с этого самого дня в нашей семье начались дикие скандалы из-за каждой мелочи, муж начал сильно засматриваться на алкоголь, а я постоянно болела. Мы поняли, что случайно вскрыли магический тайник. Рабочие вообще отказались продолжать ремонт и ушли. Я в панике стала искать помощь экстрасенса. Нашла официальную страницу Ангелины Изосимовой, оставила заявку на срочный прием. Ясновидящая выслушала меня, посмотрела фото стены и строго сказала ничего не трогать голыми руками. Оказалось, это была мощнейшая проклятая печать. Ангелина приехала к нам, провела тяжелейший ритуал очищения пространства. Она смывала эти символы специальными растворами. Атмосфера в квартире сразу стала легкой, дышать стало проще. Ремонт мы благополучно доделали.',5,1,'2026-03-23 13:07:00'),
('cdff5774-26d1-11f1-a4c7-ded14fa395b3','angelina-izosimova','Игорь, 31','','Я программист, человек абсолютно рациональный и верящий только в логику. Но то, что со мной происходило последний месяц, не поддавалось никакому осмыслению. Я просто перестал спать. Вообще. Закрывая глаза, я физически ощущал чужой, очень тяжелый взгляд из темного угла своей спальни. Начиналась жуткая паника, выступал холодный липкий пот. Сильные снотворные не действовали. За месяц я превратился в ходячий скелет, стал допускать критические ошибки на работе. Невролог выписал транквилизаторы, но я решил попробовать альтернативный вариант. Поисковик выдал восторженные отзывы об экстрасенсе Ангелине Изосимовой. Нашел, как записаться онлайн. На консультации Ангелина шокировала меня до глубины души. Она точно, до деталей описала моего коллегу, который увлекался астральными практиками и из черной зависти к моим успехам намеренно \"подселил\" ко мне сущность-наблюдателя. Изосимова провела отсечение этого канала и поставила мощный щит. В ту же ночь я проспал 12 часов подряд без сновидений!',5,1,'2026-03-23 13:06:00'),
('cdff57c9-26d1-11f1-a4c7-ded14fa395b3','angelina-izosimova','Елизавета, 26','','На торжественную помолвку моя будущая свекровь подарила мне старинное фамильное кольцо с огромным рубином. Это была гордость их семьи. Но как только я надела его на свой палец, начались пугающие странности. Кольцо буквально жгло кожу, под ним появилось красное, воспаленное и незаживающее пятно. Но хуже того — я начала беспричинно срываться на жениха, мы стали ругаться так грязно, как никогда раньше. Появились реальные мысли отменить свадьбу. Я тайком сняла кольцо, и мне физически стало легче дышать. Поняла, что дело нечисто. Искала долго, читала разные форумы и выбрала Ангелину Изосимову. Нашла официальный сайт, узнала цены. Приехала к ней на личный прием в Москве и привезла украшение. Ясновидящая даже не дотронулась до него. Сказала, что на этом кольце висит вековое проклятие первой владелицы, которая была глубоко несчастна, и теперь оно разрушает жизнь всем женщинам в роду. Ангелина провела сложный обряд очищения камня. Сейчас я ношу его абсолютно спокойно.',5,1,'2026-03-23 13:05:00'),
('cdff589e-26d1-11f1-a4c7-ded14fa395b3','angelina-izosimova','Кристина, 22','','Я балерина, вся моя жизнь — это кровь, пот, тяжелый труд у станка и сцена. Перед долгожданной премьерой, где я должна была танцевать главную партию, на меня обрушилась какая-то необъяснимая, дикая неуклюжесть. Я падала буквально на ровном месте. Сначала сильное растяжение связок, потом перелом пальца, затем микротрещина в лодыжке. И это всё за один короткий месяц! Моя карьера была под угрозой полного завершения. Мама, видя мои бесконечные слезы, сказала, что это явно чей-то завистливый сглаз. Мы стали искать информацию в сети, кто может экстренно помочь. Нашли экстрасенса Ангелину Изосимову, нас впечатлили реальные истории людей. Записались на онлайн-прием. Ангелина сразу сказала: \"На твоих ногах невидимые энергетические путы. Сделала молодая девушка, которая стоит с тобой в одной линии\". Она в точности описала мою конкурентку! Изосимова провела дистанционную чистку и сняла эту блокировку. Мои кости срослись на удивление быстро, я блестяще станцевала ту премьеру.',5,1,'2026-03-23 13:04:00'),
('cdff58fb-26d1-11f1-a4c7-ded14fa395b3','angelina-izosimova','Антон, 34','','Меня преследовал какой-то очень злой рок в профессиональной сфере. Я отличный, опытный бухгалтер, но последние три года меня выгоняли с каждой новой работы через пару месяцев с жуткими, безосновательными скандалами. Меня постоянно обвиняли в пропаже крупных сумм, которых я в глаза не видел! Проводили долгие аудиты, недостачи находились, но мою вину доказать не могли, просто увольняли. Моя репутация в городе была испорчена в ноль. Я впал в черную депрессию. Жена уговорила попробовать нетрадиционный подход к проблеме. Мы нашли официальный сайт Ангелины Изосимовой, записались, оплатили стоимость консультации. Ангелина была очень прямолинейна и строга. Она увидела на мне сильную порчу на социальное изгойство и разорение, которую навела моя первая жена при тяжелом разводе, чтобы я никогда не смог нормально жить. Мы провели серию мощных ритуалов по снятию этого проклятия. Спустя месяц меня позвали главным бухгалтером в крупную международную строительную фирму. Работаю уже полгода, всё отлично!',5,1,'2026-03-23 13:03:00'),
('cdff594d-26d1-11f1-a4c7-ded14fa395b3','angelina-izosimova','Светлана, 41','','Моя история может показаться фантастикой из кино, но я реально начала забывать своего родного мужа. Мы прожили вместе 15 счастливых лет, но в один момент я стала терять целые огромные куски нашего прошлого. Я не помнила нашу свадьбу, совместные поездки на море, иногда просыпалась в панике и не понимала, кто этот мужчина лежит рядом. При этом я отлично помнила всё остальное — работу, подруг, свое детство. Врачи ставили странную форму выборочной амнезии. Муж сходил с ума от горя и бессилия. Его сестра настояла на визите к ясновидящей Ангелине Изосимовой. Мы нашли, как записаться на прием в Москве. На встрече Ангелина посмотрела на нас и уверенно сказала: \"На вас сделан сильнейший остудный ритуал через стирание памяти. Кто-то очень хочет освободить твоего мужа\". Экстрасенс начала сложную работу по восстановлению наших энергетических связей. Это было долго, но постепенно воспоминания стали вспышками возвращаться! Сейчас я снова помню всё, наша семья спасена.',5,1,'2026-03-23 13:02:00'),
('cdff59a3-26d1-11f1-a4c7-ded14fa395b3','angelina-izosimova','Михаил, 38','','Я довольно успешный писатель, издал пять популярных романов-бестселлеров. Но однажды обычным утром я сел за свой рабочий компьютер и понял, что не могу связать и двух простых слов. В голове была абсолютная, звенящая пустота. Это не был обычный творческий кризис. Я физически не мог писать, руки дрожали, накатывала жуткая тошнота при виде чистого листа. Так продолжалось почти целый год. Издательство грозило миллионными штрафами, я начал спиваться. Мой редактор, видя, как я погибаю, дал мне контакт проверенного экстрасенса. Это была Ангелина Изосимова. Я был скептиком, но согласился на онлайн-консультацию. Изосимова сразу увидела суть проблемы. Она сказала, что мой талант был наглухо заблокирован мощным крадником, который сделал мой менее успешный коллега через подаренную мне эксклюзивную перьевую ручку. Я действительно держал её на столе как талисман! Ангелина велела уничтожить ручку в огне и провела обряд на возврат энергии. Буквально через два дня вдохновение вернулось полностью.',5,1,'2026-03-23 13:01:00'),
('cf37ecb7-1874-4a47-b43c-3d5d4d509fa6','elena-golunova','Татьяна, 52','','После скоропостижной смерти наших родителей мы с родным братом внезапно стали злейшими, непримиримыми врагами. Главный камень преткновения — оставшееся наследство. Брат, которого я всегда искренне любила и опекала, вдруг стал вести себя абсолютно неадекватно, кричал, угрожал мне судами, нанимал сомнительных людей, чтобы психологически выжить меня из родительского дома. Я просто не узнавала родного человека, в его глазах была только злоба. В полном отчаянии я начала искать помощь на стороне. Читала разные форумы, где активно обсуждались известные экстрасенсы. Многие люди настоятельно рекомендовали Елену Голунову. Я нашла адрес в Москве и записалась на личный прием, чтобы разобраться в ситуации. Елена Валерьевна очень внимательно выслушала меня, посмотрела принесенные фотографии. И сказала то, от чего я просто остолбенела: на брата оказывала мощное влияние его новая алчная жена, которая занималась черной магией, чтобы забрать всё имущество себе. Елена помогла мне выстроить надежную энергетическую защиту и снять пелену с глаз брата. Через три месяца он пришел ко мне с цветами и извинениями, мы мирно и поровну поделили имущество, а с той ужасной женщиной он со скандалом развелся.',5,1,'2026-03-23 12:07:00'),
('d4f72f01-29cf-11f1-9268-321bdf3681b2','nadezhda-shevchenko','Марина, 41','','Моя пятнадцатилетняя дочь, всегда бывшая круглой отличницей и честным ребенком, внезапно начала воровать. Причем тащила из магазинов абсолютную ерунду: дешевые ластики, заколки, жвачки. Нас дважды забирали в полицию, это был невероятный позор и шок. Психологи говорили о переходном возрасте и скрытом стрессе, но я видела, что у нее во время этих приступов стеклянные глаза. Как будто ей кто-то управляет. Одна знакомая обмолвилась, что такое бывает, если ребенок случайно подобрал заговоренную вещь на перекрестке. Я начала судорожно искать, кто в Москве может помочь. Читала отзывы, смотрела информацию. Меня очень привлекла многоликая ведьма Надежда Шевченко. Я нашла ее официальный сайт, узнала стоимость приема и оставила заявку. Ждать пришлось несколько дней, но нам перезвонили. На личной встрече Надежда Эдуардовна подтвердила мои страхи. Оказалось, дочь подняла красивый кулон на улице, на который скинули чужую сущность-воровку. Экстрасенс провела очень жесткий ритуал с тенями и огнем. Кулон мы уничтожили по ее правилам. Воровство прекратилось в тот же день, дочь даже вспомнить не могла, зачем это делала.',5,1,'2026-03-23 15:25:00'),
('d4fa4ae2-29cf-11f1-9268-321bdf3681b2','nadezhda-shevchenko','Олег, 35','','Всё началось с того, что я приобрел на аукционе старинный натюрморт. Я коллекционер, давно охотился за этой картиной. Но как только я повесил ее на кухне, у нас в доме стала моментально гнить любая еда. Свежее молоко скисало за час в холодильнике, хлеб покрывался черной плесенью на следующий день, фрукты превращались в слизь. Сначала грешили на технику, купили новый дорогущий холодильник — не помогло. В квартире появился стойкий запах разложения. Жена отказалась там готовить. Я решил искать мистическую причину. Перерыл кучу форумов, где обсуждали подобные явления. Многие хвалили экстрасенса Надежду Шевченко. Нашел ее телефон, связался с помощниками через ватсап. Нас записали на онлайн-прием. Надежда Шевченко сразу попросила навести камеру на кухню. Как только она увидела натюрморт, велела немедленно снять его со стены голыми руками в перчатках. Оказалось, в раму был зашит могильный саван. Это был старинный проклятый предмет, высасывающий энергию жизни. Ведьма научила, как правильно очистить дом и избавиться от картины. Продукты больше не портятся, а атмосферу в доме словно освежили.',5,1,'2026-03-23 15:24:00'),
('d4fa4c80-29cf-11f1-9268-321bdf3681b2','nadezhda-shevchenko','Анна, 39','','Я была в полном отчаянии, когда за неделю до главного судебного процесса в моей карьере я проснулась и не смогла сказать ни слова без жуткого заикания. Я успешный адвокат, моя речь — это мой главный инструмент и хлеб. А тут я не могла даже свое имя произнести, задыхалась на каждом слоге. Врачи-неврологи кололи спазмолитики, подозревали микроинсульт, но МРТ было чистым. Конкуренты откровенно злорадствовали. Я поняла, что меня просто устраняют нечестными методами. Времени не было, я начала гуглить сильных магов. Официальный сайт Надежды Шевченко внушил мне доверие своей строгостью. Узнала цены, оставила срочную заявку. Администраторы вошли в положение, мне назначили встречу в Москве. Надежда Эдуардовна даже не стала меня слушать, она сама всё увидела. Сказала, что на мне висит мертвая петля, порча на немоту, которую сделал клиент противоположной стороны через мой выпитый кофе на переговорах. Многоликая ведьма проводила отливку свинцом. Это было больно физически, горло горело. Но на следующее утро я проснулась и заговорила абсолютно чисто! Процесс я выиграла с блеском.',5,1,'2026-03-23 15:23:00'),
('d4fa4d05-29cf-11f1-9268-321bdf3681b2','nadezhda-shevchenko','Елена, 28','','Если честно, я вообще не верила во всякие порчи, пока сама не начала седеть клочьями в 28 лет. Буквально за месяц на моей голове появились огромные абсолютно белые пряди, как у старухи. Никакого стресса не было, анализы на гормоны идеальные, витамины в норме. Трихолог только развел руками. А началось всё после того, как я сильно поругалась с соседкой по лестничной клетке, очень странной женщиной, которая постоянно что-то шептала мне вслед. Моя парикмахер тихонько посоветовала мне найти хорошего экстрасенса. Я начала изучать отзывы реальных людей. Выбрала Надежду Шевченко, ее энергетика показалась мне очень близкой. Найти официальный контакт было несложно, записалась на онлайн-консультацию. Надежда сразу сказала, что эта соседка — энергетический вампир и чернушница, которая в порыве злобы кинула мне вслед проклятие на быстрое старение. Шевченко провела ритуал отсечения этой связи и поставила на меня сильную зеркальную защиту. Седина, конечно, не исчезла сама по себе, пришлось закрашивать, но процесс остановился мгновенно! Новые волосы растут моего родного темного цвета.',5,1,'2026-03-23 15:22:00'),
('d4fa7334-29cf-11f1-9268-321bdf3681b2','nadezhda-shevchenko','Виктор, 43','','Сейчас я понимаю, что совершил огромную глупость, когда поднял на улице красивые дорогие часы. Я просто шел с работы, увидел их на асфальте и машинально положил в карман, думал найти владельца по гравировке. И с того вечера моя жизнь превратилась в ад. У меня развилась дичайшая агорафобия — животный страх открытого пространства. Я не мог выйти из подъезда, начиналась паника, нехватка воздуха, я падал на колени и полз обратно в квартиру. Пришлось взять отпуск за свой счет, я сидел дома как в тюрьме. Психотерапия по скайпу не помогала. Жена была в шоке, сама начала искать мистические причины. Она нашла, где принимает экстрасенс Надежда Шевченко. Узнала стоимость приема, договорилась об онлайн-диагностике. Многоликая ведьма сразу спросила: Что чужого металлического ты принес в дом? Я вспомнил про часы. Оказалось, на них был сделан мощный переклад тяжелой болезни, которая била по моей нервной системе. Надежда научила, как правильно отнести этот предмет на безлюдный перекресток с откупом, и дистанционно почистила меня. Через пару дней я спокойно вышел на улицу. Страх ушел без следа.',5,1,'2026-03-23 15:21:00'),
('d4fa745e-29cf-11f1-9268-321bdf3681b2','nadezhda-shevchenko','Кристина, 31','','Каждую ночь ровно в 2:15 в нашей квартире раздавался пронзительный звонок старого стационарного телефона. Самое жуткое в этом было то, что аппарат был давно отключен от линии и даже вилка не была вставлена в розетку! Сначала я думала, что схожу с ума или это звуки от соседей. Но когда муж однажды ночью просто взял трубку и услышал там леденящее душу тяжелое дыхание, мы поняли, что в доме полтергейст. Спать стало невозможно, мы вздрагивали от каждого шороха. Я начала искать на форумах, кто занимается чисткой квартир. Многие рекомендовали Шевченко Надежду. Нашла официальный сайт, оставила заявку. Очередь была приличная, пришлось подождать. Надежда Эдуардовна приехала к нам лично. Это невероятно сильный человек. Она обошла квартиру со своими ритуальными свечами и сказала, что через этот старый аппарат к нам пытается пробиться неупокоенная душа бывшей владелицы квартиры, которая умерла в одиночестве и не могла ни до кого дозвониться перед смертью. Экстрасенс провела обряд успокоения души. Телефон мы выбросили по ее инструкции. Ночные звонки навсегда прекратились.',5,1,'2026-03-23 15:20:00'),
('d4fa96bc-29cf-11f1-9268-321bdf3681b2','nadezhda-shevchenko','Дмитрий, 40','','Я аналитик данных, моя работа — это постоянное чтение сложных текстов и графиков. В один прекрасный день я открыл рабочий отчет и понял, что буквы просто расплываются и прыгают. Я не мог прочитать ни одного слова! Это не проблема со зрением, я просто забыл, как складывать слоги. В 40 лет внезапно стать неграмотным — это катастрофа. Я прошел кучу обследований мозга, неврологи пожимали плечами. Пришлось взять больничный, карьера висела на волоске. Моя мама, верующая и строгая женщина, сказала, что на меня навели морок. Она сама нашла контакты сильной ведьмы. Это была Надежда Шевченко. Я пошел на прием просто от безысходности, не веря ни во что. Узнали цены, записались. В Москве на личной встрече Надежда посмотрела на меня и сказала, что это порча на закрытие путей и помутнение рассудка. Сделал ее мой бывший подчиненный, которого я уволил за некомпетентность. Многоликая ведьма проводила чистку огнем. Я не знаю, как это работает, но на третье утро я открыл книгу и начал спокойно читать! Это спасло мою жизнь и работу.',5,1,'2026-03-23 15:19:00'),
('d4fa974f-29cf-11f1-9268-321bdf3681b2','nadezhda-shevchenko','Мария, 52','','Огромная, искренняя благодарность этой удивительной женщине за то, что вернула покой в наш дом. У нас на протяжении полугода творилась полная чертовщина: все картины и фотографии в рамках постоянно падали со стен. Причем гвозди оставались на месте, а рамки летели на пол исключительно лицом вниз, разбивая стекла. Муж злился, я плакала. Следом начали болеть домашние животные, кот вообще сбежал из дома. Атмосфера была тяжелой, гнетущей. Я поняла, что у нас завелась какая-то сущность. Читала отзывы кто обращался за помощью, искала надежного специалиста. Экстрасенс Надежда Шевченко вызвала наибольшее доверие. Я нашла ее официальный контакт и написала. Нас проконсультировали онлайн. Надежда Эдуардовна попросила показать стены. Она сразу увидела, что муж принес с работы старые доски для ремонта балкона, которые оказались взяты с разобранного сгоревшего дома. В них сидела энергия разрушения. Она велела немедленно вынести это дерево на мусорку и провела дистанционный обряд отжига негатива. С тех пор ни одна картина не упала, в доме стало легко дышать, а кот через неделю вернулся!',5,1,'2026-03-23 15:18:00'),
('d4fa97bd-29cf-11f1-9268-321bdf3681b2','nadezhda-shevchenko','Илья, 36','','Это был настоящий кошмар наяву. Я работаю шеф-поваром в дорогом ресторане. Мои вкусовые рецепторы — это моя профессия. И вдруг у меня во рту появился стойкий, металлический вкус свежей крови. Какую бы еду я ни пробовал — сладкую, соленую, острую — всё имело вкус крови. Я испортил несколько важных банкетов, потому что не мог нормально настроить вкус блюд. Сдал все анализы, проверил желудок, зубы — всё идеально. Но вкус никуда не уходил, меня постоянно тошнило. Владелец ресторана отправил меня в бессрочный отпуск. Я был в отчаянии. Мой су-шеф посоветовал обратиться к магии, сказал, что это профессиональная порча на лишение мастерства. Я нашел сайт экстрасенса Надежды Шевченко. Узнал, сколько стоит прием, и оформил запись. Встретились лично. Надежда посмотрела на меня и подтвердила — это сильный крадник таланта, сделанный конкурентом из соседнего ресторана через угощение, которое я неосмотрительно съел на фуршете. Шевченко провела мощную чистку, снимала этот блок. Буквально через пару дней мерзкий вкус исчез! Я снова чувствую все оттенки специй.',5,1,'2026-03-23 15:17:00'),
('d4fa981b-29cf-11f1-9268-321bdf3681b2','nadezhda-shevchenko','Светлана, 29','','Мое обручальное кольцо начало жить своей собственной жизнью. Я всегда снимала его на ночь и клала в шкатулку. Утром его там не было. Мы с мужем переворачивали всю спальню, ругались. А вечером я находила его в самых невероятных местах: в холодильнике, в горшке с цветком, один раз даже внутри зашитой декоративной подушки! Муж начал подозревать меня в каком-то психическом расстройстве или лунатизме, мы отдалились друг от друга. Я панически боялась засыпать. Поняла, что это воздействие извне, когда кольцо исчезло прямо с пальца во время мытья посуды. Стала искать сильную колдунью. По отзывам выбрала Надежду Шевченко. Нашла официальную страницу, связалась с помощниками. Мы договорились об онлайн-диагностике. Многоликая ведьма сразу сказала, что кольцо стало магнитом для беса-разрушителя. Кто-то подарил нам на свадьбу заговоренный конверт с деньгами, и эта энергия ударила по самому главному символу брака. Надежда научила, как правильно очистить кольцо в четверговой соли, и дистанционно почистила наш дом. Прошел уже год — кольцо всегда на месте, а в семью вернулась любовь.',5,1,'2026-03-23 15:16:00'),
('d4fa9875-29cf-11f1-9268-321bdf3681b2','nadezhda-shevchenko','Павел, 33','','Я долго не хотел верить в мистику, списывая всё на невероятные совпадения. Но это перешло все границы. Я стал буквально невидимым для окружающего мира. Автоматические двери в магазинах перестали передо мной открываться. Датчики движения в коридорах не включали свет. Но хуже всего — люди на работе просто перестали меня замечать. Я мог стоять посреди кабинета, а коллеги спрашивали друг друга, где я. Официанты упорно обходили мой столик. Это было жуткое, сводящее с ума чувство социальной изоляции. Моя девушка, заметив эти странности, сама нашла контакты сильного практика. Записала меня к Надежде Шевченко на личный прием в Москве, оплатила стоимость. Когда я пришел, экстрасенс Надежда посмотрела на меня с сочувствием. Она сказала, что на мне висит саван одиночества — порча на полное стирание личности. Ее заказала моя бывшая жена, чтобы я навсегда остался один. Шевченко провела очень тяжелый, энергоемкий ритуал снятия этого морока. Выходя от нее, я зашел в супермаркет — и двери открылись! На следующий день на работе со мной все радостно здоровались. Я вернулся в этот мир.',5,1,'2026-03-23 15:15:00'),
('d4fa98d5-29cf-11f1-9268-321bdf3681b2','nadezhda-shevchenko','Анастасия, 37','','Только сейчас я могу спокойно открыть кран на кухне и налить воды. Месяц назад это было невозможно. В нашей съемной квартире начала происходить жуть: из всех кранов периодически текла густая, черная вода с запахом тухлых яиц и серы. Сантехники из ЖЭКа приходили пять раз, меняли трубы, проверяли стояк — у всех соседей вода кристально чистая, а у нас черная жижа. Хозяин квартиры не верил и обвинял нас в поломках. Жить там было страшно. Я начала искать паранормальные причины. Читала форумы, нашла множество положительных историй про ясновидящую Надежду Шевченко. Зашла на ее официальный сайт, оставила заявку на консультацию. Связались быстро. По видеосвязи я показала экстрасенсу эту воду. Надежда Эдуардовна жестко сказала: Это грязная подселенка, сущность нижнего астрала, которая питается вашим страхом. Прошлая жиличка проводила темные ритуалы в ванной. Многоликая ведьма провела дистанционное изгнание, это было очень мощно, у меня мурашки бегали по коже. Как только сеанс закончился, я включила воду — она пошла абсолютно прозрачная и без запаха. С тех пор проблема не возвращалась!',5,1,'2026-03-23 15:14:00'),
('d4fab99d-29cf-11f1-9268-321bdf3681b2','nadezhda-shevchenko','Роман, 26','','Я профессиональный бодибилдер, моя форма — это годы тренировок и строгого режима. За пару месяцев до важных соревнований я начал стремительно худеть. Я ел по пять тысяч калорий в день, тренировался, но мышцы просто таяли, превращаясь в тряпочки. За месяц ушло 12 килограмм чистой мышечной массы! Я стал похож на узника концлагеря. Врачи обследовали щитовидку, ЖКТ — никаких отклонений, метаболизм в норме. Спортивный врач развел руками. Мой тренер, мужик старой закалки, сказал, что меня кто-то сглазил на сухоту. Я не верил, но выбора не было. Стал гуглить экстрасенс помощь Москва. Нашел отзывы о Надежде Шевченко. Узнал цену приема, записался. На встрече ведьма даже не удивилась. Она сказала, что это классический крадник здоровья и массы, который сделал мой главный конкурент по залу через воду в кулере. Она провела мощный обряд возврата энергии и отсекла этот канал. Я начал набирать вес обратно уже через неделю, восстановил форму и взял серебро на соревнованиях. Если бы не она, я бы стал инвалидом.',5,1,'2026-03-23 15:13:00'),
('d4faba13-29cf-11f1-9268-321bdf3681b2','nadezhda-shevchenko','Дарья, 34','','Я вложила все свои сбережения и взяла огромный кредит на открытие собственного салона красоты. Мы сделали шикарный ремонт, наняли лучших мастеров. Но после открытия начался кромешный ад. У каждой второй клиентки, которая садилась в кресло к парикмахеру или на маникюр, начиналась жуткая аллергия: лицо покрывалось красными пятнами, глаза слезились. При этом мы использовали самую дорогую гипоаллергенную косметику! Клиентки писали гневные отзывы, требовали возврата денег, салон опустел за две недели. Я была на грани петли. Поняла, что место проклято. Искала сильного экстрасенса по чистке бизнеса. Вышла на контакт Надежды Шевченко. На официальном сайте оставила заявку на срочный выезд. Надежда приехала к нам. Она сразу пошла в подсобку и вытащила из-под плинтуса маленький мешочек с какой-то сухой дрянью и кладбищенской землей. Оказалось, это подклад на разорение бизнеса, который сделала моя бывшая подруга, позавидовавшая моему успеху. Экстрасенс очистила помещение своими ритуалами. Аллергии у клиенток прекратились как по волшебству! Сейчас салон процветает, запись на месяц вперед.',5,1,'2026-03-23 15:12:00'),
('d4faba77-29cf-11f1-9268-321bdf3681b2','nadezhda-shevchenko','Игорь, 42','','То, что произошло со мной, до сих пор снится мне в кошмарах. Моя абсолютно новая, дорогая машина начала вести себя как живой монстр. Дважды подряд, когда я подъезжал к железнодорожному переезду, двигатель внезапно глох, а двери намертво блокировались изнутри! Я сидел внутри как в ловушке, в панике бил по стеклам, пока приближался поезд. Оба раза машина заводилась за секунду до катастрофы, и я успевал съехать. В автосервисе электронику разобрали до винтика — всё идеально исправно. Механик перекрестился и посоветовал сходить в церковь или к бабке. Я решил найти сильного специалиста. Читал форумы, наткнулся на имя ясновидящей Надежды Шевченко. Нашел телефон, записался на прием. Узнал сколько стоят услуги, приехал к ней. Надежда Эдуардовна разложила карты и сказала страшную вещь: на машине лежит порча на смертельное ДТП. Ее заказал муж женщины, с которой у меня был короткий роман до моего брака. Многоликая ведьма проводила мощный отжиг машины свечами и ставила защиту. Я после этого продал машину от греха подальше, купил новую. Больше никаких мистических поломок, всё работает как часы.',5,1,'2026-03-23 15:11:00'),
('d4fabad7-29cf-11f1-9268-321bdf3681b2','nadezhda-shevchenko','Оксана, 38','','Я всегда была скептиком, но когда твой родной ребенок начинает по ночам разговаривать нечеловеческим голосом на мертвом языке, поверишь во что угодно. Мой тринадцатилетний сын внезапно стал лунатить и бормотать во сне какие-то гортанные, шипящие звуки, похожие на латынь или древнеарамейский. При этом глаза были открыты, но белые, без зрачков. Днем он ничего не помнил, но стал агрессивным, перестал учиться. Психиатр настаивал на госпитализации. Я не могла отдать сына в психушку. Нашла в интернете отзывы реальных людей об экстрасенсе Надежде Шевченко. Меня зацепила ее сила и профиль работы. Записалась через официальный сайт на онлайн-консультацию, так как боялась везти сына в Москву. По видеосвязи Надежда посмотрела на ребенка и строго сказала, что это демоническое подселение. Сын случайно нашел в старой библиотеке деда черномагическую книгу и прочитал вслух заклинание призыва. Экстрасенс провела дистанционный экзорцизм. Это было невероятно страшно, сын кричал и вырывался. Но когда всё закончилось, он просто уснул глубоким сном. Прошло полгода, он здоров, ходит в школу, никаких языков больше не знает.',5,1,'2026-03-23 15:10:00'),
('d4fabb53-29cf-11f1-9268-321bdf3681b2','nadezhda-shevchenko','Полина, 30','','Моя проблема была настолько редкой и пугающей, что врачи просто разводили руками. У меня трижды диагностировали так называемую ложную беременность. Был растущий живот, токсикоз, отсутствие цикла, положительные тесты. Но на УЗИ матка оказывалась пустой! Моя психика была сломана, муж начал отстраняться, свекровь шепталась, что я проклята. Я сама начала в это верить. Стала искать помощи у магов. Перелопатила весь интернет, пока не нашла официальную страницу Надежды Шевченко. Многоликая ведьма внушала доверие. Я узнала цены, записалась на личную встречу. Надежда посмотрела на меня и сразу назвала причину. На мне висела порча пустоцвет, сделанная на бесплодие и сумасшествие. Сделала ее бывшая жена моего мужа, чтобы у нас никогда не было общих детей. Работа по снятию была очень долгой и тяжелой, я выполняла кучу ритуалов очищения. Но это того стоило. Через пять месяцев после окончания нашей работы я забеременела по-настоящему! Сейчас нашему малышу уже два месяца. Я буду молиться за эту женщину.',5,1,'2026-03-23 15:09:00'),
('d4fabbb3-29cf-11f1-9268-321bdf3681b2','nadezhda-shevchenko','Валерий, 51','','Только сейчас, спустя год, я снова могу спать с выключенным светом. В 50 лет я внезапно стал панически бояться темноты, как маленький ребенок. Оставлял включенным свет во всех комнатах, спал с ночником. Если свет внезапно отключали, у меня начиналась настоящая паническая атака, я забивался в угол и плакал от невыносимого ужаса, что из темноты за мной кто-то придет. Началось это после безобидного похода за грибами в старый лес. Жена, устав от счетов за электричество и моих истерик, записала меня к сильному экстрасенсу. Это была Надежда Шевченко. Нашли ее контакты в сети, приехали на прием в Москву. Надежда Эдуардовна выслушала меня и сказала, что в том лесу я случайно наступил на место старого языческого захоронения и притащил за собой темную сущность, которая питается моим страхом темноты. Она провела мощный обряд отливки воском и свинцом. Ощущение было такое, будто из меня вытянули холодного склизкого червя. В тот же вечер я пришел домой и сам выключил свет в прихожей. Страх исчез абсолютно!',5,1,'2026-03-23 15:08:00'),
('d4fadd2d-29cf-11f1-9268-321bdf3681b2','nadezhda-shevchenko','Людмила, 35','','Мы с мужем душа в душу прожили восемь лет. Но внезапно со мной начало происходить нечто страшное: как только кто-то произносил имя моего мужа вслух, или он сам мне звонил, меня накрывала волна дикой, неконтролируемой ярости. Я хотела крушить всё вокруг, кричать на него, ударить. При этом умом я понимала, что люблю его, но тело и эмоции мне не подчинялись. Мы стали ругаться каждый день, он собрал вещи и ушел, решив, что у меня поехала крыша. Я была в ужасе от самой себя. Подруга дала мне номер администратора экстрасенса Надежды Шевченко. Я зашла на официальный сайт, почитала отзывы и решила пробовать. Записалась на онлайн-прием. Многоликая ведьма сразу поставила диагноз: на меня была сделана сильная рассорка на крови. Изощренная порча, чтобы я своими руками разрушила свой брак. Надежда провела сложную чистку. Я физически чувствовала, как из головы уходит этот черный туман. Позвонила мужу на следующий день — и услышала его голос с радостью, без капли гнева. Мы снова вместе, всё наладилось.',5,1,'2026-03-23 15:07:00'),
('d4faddac-29cf-11f1-9268-321bdf3681b2','nadezhda-shevchenko','Татьяна, 44','','Я была в полном недоумении, когда наш смелый, огромный ротвейлер вдруг начал панически бояться старого дуба в нашем дворе. Стоило нам подойти к этому дереву во время прогулки, собака ложилась на землю, скулила и пыталась вырваться из ошейника, чтобы убежать домой. И ровно с этого момента в нашей семье пошли крупные неприятности: муж попал под сокращение, сын сломал ногу, я заболела пневмонией. Я поняла, что собака что-то чувствует. Стала искать сильную ведьму, которая может разобраться в ситуации. Много читала, выбрала Надежду Шевченко. Нашла, где принимает, оставила заявку на консультацию. Надежда посмотрела фото двора и сказала, что под корнями этого дерева зарыт страшный подклад на уничтожение нашей семьи. Экстрасенс дала мне точные инструкции, как выкопать это, не касаясь голыми руками. Мы нашли там завернутую в черную ткань мертвую ворону с фотографией нашей семьи! Мы сожгли это по правилам Надежды Эдуардовны, а она дистанционно поставила нам защиту. Собака на следующий день спокойно пометила этот дуб, а наши беды мгновенно отступили.',5,1,'2026-03-23 15:06:00'),
('d4fade0d-29cf-11f1-9268-321bdf3681b2','nadezhda-shevchenko','Артем, 31','','Моя жизнь превратилась в фильм ужасов. Каждую ночь я страдал от жесточайшего сонного паралича. Но самое жуткое — я видел свое тело со стороны, висящим под потолком, в то время как какая-то темная, бесформенная тень сидела на моей груди и душила меня. Я просыпался с синяками на шее! Врачи говорили про апноэ и стресс, но синяки это не объясняло. Я боялся спать, сидел на энергетиках, стал похож на зомби. Девушка бросила меня. В полном отчаянии я стал искать контакты ясновидящих. Нашел официальный сайт экстрасенса Надежды Шевченко, меня впечатлили отзывы людей. Узнал цену приема, записался на личную встречу. Надежда была очень строга. Она сказала, что моя астральная проекция выбита из тела сильным проклятием, и эта тень — астральный паразит, который скоро меня полностью выпьет. Она провела сложнейший обряд с зеркалами и огнем, возвращая мою душу на место и ставя защиту. Я впервые за три месяца уснул нормальным сном, без теней и удушья. Жизнь заиграла новыми красками, я безмерно благодарен!',5,1,'2026-03-23 15:05:00'),
('d4fade66-29cf-11f1-9268-321bdf3681b2','nadezhda-shevchenko','Евгения, 40','','Если честно, я всегда посмеивалась над историями про привидений. Но когда в моей собственной постели образовалось ледяное пятно, мне стало не до смеха. Каждую ночь ровно на моей половине кровати температура падала так, что изо рта шел пар. Я спала под тремя одеялами в шерстяных носках и всё равно промерзала до костей. Муж рядом спал раскрытым и потел. Мы меняли матрас, переставляли кровать — ледяная зона перемещалась вместе со мной. Я начала постоянно болеть простудами. Поняла, что это что-то потустороннее. Стала гуглить мистика холод в доме экстрасенс. Нашла контакты Надежды Шевченко. На официальной странице узнала, сколько стоит прием, и оформила онлайн-заявку. Многоликая ведьма даже по видеосвязи почувствовала этот холод. Она объяснила, что это энергетическая пробоина, через которую ко мне присосалась сущность из нижнего мира, тянущая жизненное тепло. Надежда провела огненный ритуал отжига по фото и запечатала эту дыру. В ту же ночь в кровати стало нормально тепло! Я наконец-то согрелась и перестала болеть.',5,1,'2026-03-23 15:04:00'),
('d4fadf0a-29cf-11f1-9268-321bdf3681b2','nadezhda-shevchenko','Сергей, 36','','Всё началось после ремонта в нашем новом офисе. Я, как владелец фирмы, стал постоянно слышать громкое, отчетливое тиканье часов в стене своего кабинета. Сначала думал, что строители забыли какой-то таймер или проводку коротит. Вызывали электриков, вскрывали гипсокартон — там было пусто. А тиканье сводило меня с ума, я не мог сосредоточиться на работе. Вместе с этим звуком фирма начала стремительно терять контракты, заказчики уходили один за другим. Партнер посоветовал не тянуть и обратиться к специалисту по эзотерике. Мы пересмотрели много отзывов, решили связаться с экстрасенсом Надеждой Шевченко. Узнали цены, пригласили ее в офис. Надежда Эдуардовна прошла по кабинету и безошибочно указала на одну точку на стене. Оказалось, конкуренты подкупили прораба, и тот вмуровал в штукатурку заговоренный механизм на отсчет времени жизни моего бизнеса. Ведьма провела чистку помещения, нейтрализовала этот жуткий подклад. Тиканье прекратилось в ту же секунду. Бизнес пошел в гору буквально через неделю, старые клиенты вернулись!',5,1,'2026-03-23 15:03:00'),
('d4fadf65-29cf-11f1-9268-321bdf3681b2','nadezhda-shevchenko','Максим, 25','','Хочу сказать огромное спасибо этой сильной женщине за спасение. Я сделал себе на плече красивую татуировку со скандинавскими рунами, просто нашел эскиз в интернете, показалось круто. И с этого дня моя жизнь превратилась в кромешный ад. Рука начала дико, невыносимо болеть, словно ее жгут паяльной лампой. Кожа вокруг тату покраснела и постоянно горячая, хотя инфекции нет, дерматолог выписывал мази, но они не помогали. Кроме того, у меня началась жуткая бессонница и агрессия, я разругался со всеми друзьями. Знакомый татуировщик сказал, что руны — это серьезная магия, и я, видимо, набил себе проклятие. Стал срочно искать сильную ведьму. Нашел официальный сайт Надежды Шевченко, почитал отзывы реальных людей. Оставил заявку, связался через Ватсап. На приеме в Москве Надежда посмотрела на руку и ужаснулась. Я набил себе рунический став на разрушение судьбы и физическую муку. Экстрасенс провела очень тяжелый ритуал деактивации рун. Боль ушла прямо во время сеанса! По ее совету я потом перекрыл эту татуировку другим рисунком. Жизнь наладилась.',5,1,'2026-03-23 15:02:00'),
('d4fb0655-29cf-11f1-9268-321bdf3681b2','nadezhda-shevchenko','Елена, 42','','Моя история абсолютно абсурдна, но это была настоящая трагедия. Я живу в России с рождения, но внезапно, после поездки в отпуск на Бали, я начала забывать русские слова. Я просто не могла нормально сформулировать предложение, заменяла слова странными звуками, забывала, как называются простые вещи. Врачи подозревали опухоль мозга или раннюю деменцию, я прошла все возможные обследования — мозг в идеальном состоянии. На работе меня отправили в неоплачиваемый отпуск. Сестра, видя мои мучения, нашла в интернете информацию про ясновидящую Надежду Шевченко. Узнала стоимость приема, записала меня на онлайн-диагностику. Надежда Эдуардовна посмотрела на меня и сразу сказала, что во время отпуска я случайно подняла на пляже красивую ракушку, на которой лежал индонезийский переклад потери памяти. Я действительно привезла такую ракушку домой! Многоликая ведьма велела немедленно уничтожить сувенир и провела мощную дистанционную чистку. Моя речь полностью восстановилась за три дня. Я снова могу нормально общаться и работать. Это просто чудо.',5,1,'2026-03-23 15:01:00'),
('d793c33e-cf62-4751-9788-3770c6d2da12','elena-golunova','Яна, 33','','Я уже окончательно опустила руки и горько смирилась с тем, что буду совсем одна до конца своих дней. Каждые мои новые отношения заканчивались болезненным, жестоким предательством. Мужчины мне нагло лгали, изменяли с моими же подругами, цинично использовали меня ради моих денег и связей. Я чувствовала себя выжатым лимоном, потерявшим веру в любовь. Моя лучшая подруга, видя мои бесконечные страдания, просто взяла и подарила мне оплаченный визит к известному специалисту. Это была ясновидящая Елена Голунова. Я сначала очень разозлилась на нее, кричала, что не верю в эти средневековые сказки, но из уважения к подруге все-таки пошла. В Москве я нашла ее офис. И этот короткий визит полностью перевернул мое сознание. Елена Валерьевна не стала меня утешать и жалеть. Она очень жестко и прямо указала на мои собственные кармические ошибки из прошлых воплощений, которые я упрямо, раз за разом повторяла в этой жизни. Она дала мне специальные духовные практики для очищения и прощения себя. Это был очень болезненный, долгий, но жизненно необходимый процесс трансформации. Спустя несколько месяцев тяжелой работы над собой я встретила мужчину, который относится ко мне с таким трепетом и уважением, что я до сих пор не верю своему счастью.',5,1,'2026-03-23 12:02:00'),
('d8789f8b-de5c-491b-b710-7c48e4de4779','elena-golunova','Игорь, 40','','Я всегда считал людей, которые ходят к бабкам и ясновидящим, мягко говоря, странными и наивными. Но когда на моей любимой работе началась настоящая, целенаправленная травля, а мои крупные проекты стали срываться один за другим по абсолютно мистическим причинам (то сервер внезапно сгорит, то флешка с важной презентацией исчезнет из запертого кабинета), я серьезно задумался. Конкурент явно использовал грязные, нечестные методы, чтобы меня подсидеть. Я решил выяснить, сколько стоит прием у профессионала, и стал искать информацию в сети. Экстрасенс Елена Голунова показалась мне самым адекватным, строгим и сильным специалистом. Через официальный сайт записался на личную консультацию. Был поражен ее жестким, сугубо конкретным подходом — никакой лишней воды, никаких стеклянных шаров и театральщины. Она четко описала моего недоброжелателя, его скрытые мотивы и методы. Дала мне определенные вещи для защиты и строгие инструкции. Удивительно, но ровно через неделю этого конкурента уволили со скандалом, а мои рабочие дела снова пошли в гору.',5,1,'2026-03-23 12:18:00'),
('d87e2871-16c6-4333-802a-6155b7afeee3','elena-golunova','Ольга, 38','','Сейчас я четко понимаю, что моя встреча с этим человеком была послана мне свыше и точно не была случайной. Годами я страдала от жуткого, съедающего изнутри одиночества. Вроде бы привлекательная, успешная женщина, но мужчины бежали от меня как от огня после пары свиданий. Я чувствовала, что на мне висит какое-то невидимое клеймо. Подруги в шутку говорили про \"венец безбрачия\", а мне было совершенно не до смеха. Когда я окончательно отчаялась построить семью, решила найти контакты сильного и проверенного специалиста. Экстрасенс Елена Голунова давно вызывала у меня огромное доверие своей прямотой. Я зашла на официальный сайт, посмотрела цены приема и оставила заявку. Думала, что онлайн формат будет менее эффективным, но я сильно ошибалась. Елена Валерьевна мгновенно увидела корень моей проблемы — родовой негатив по женской линии. Она рассказала такие пугающие подробности о моей прабабушке, от которых у меня просто мурашки побежали по коже. После проведенной ею чистки моя жизнь кардинально изменилась. Я встретила замечательного мужчину, и мы уже планируем свадьбу!',5,1,'2026-03-23 12:21:00'),
('dd045c0e-ae84-46c3-8470-44d84434d559','elena-golunova','Виктор, 47','','Мы с женой почти два года никак не могли продать нашу трехкомнатную квартиру. Место просто отличное, ремонт свежий, цену мы снижали уже сильно ниже рыночной, но потенциальные покупатели либо срывались в самый последний момент перед сделкой, либо вообще не приходили на назначенные просмотры. Возникало стойкое ощущение, как будто место было проклято или невидимая стена стояла. А нам очень срочно нужны были большие деньги на операцию для матери. Отчаявшись, мы решили прибегнуть к нестандартным методам. Жена нашла отзывы о приеме у Голуновой и сказала, что это наш последний реальный шанс. Мы зашли на официальный сайт, посмотрели цены, взвесили всё и оставили заявку. Нам назначили онлайн-встречу. Елена сразу огорошила нас неожиданной новостью: в квартире осталась тяжелая энергетика самого первого владельца, которая просто агрессивно не пускала новых людей и гнала их прочь. Елена провела специальный обряд очищения помещения дистанционно и уверенно сказала, что продадим недвижимость в течение месяца. И что вы думаете? Через две недели пришла молодая семейная пара и купила квартиру за наличные даже без торга.',5,1,'2026-03-23 12:16:00'),
('f3cefac5-6c7b-45c4-858f-4faa93a5de48','elena-golunova','Светлана, 29','','Если честно, я вообще не верила во всю эту мистику, магию и экстрасенсов, пока сама не столкнулась с абсолютно необъяснимым явлением. У меня начались дикие боли в спине, такие, что я иногда просто не могла встать с кровати по утрам. Врачи разводили руками: анализы идеальные, МРТ чистое, патологий нет. Я обошла всех светил, потратила кучу денег на обследования, а толку ноль. Однажды мамина подруга обмолвилась, что мне нужна сибирская ведьма, мол, это явно чужое вмешательство. Я от безысходности стала искать в сети, кто реально может помочь с таким. Так я вышла на Елену Валерьевну. Записаться было непросто, пришлось подождать своей очереди. На приеме она сразу, без лишних слов, сказала, что проблема не в физическом здоровье, а в черной зависти коллеги, которая метила на мое место и сделала крадник. Я была в шоке, потому что действительно недавно получила серьезное повышение. После работы с Еленой все боли ушли за пару недель. Я вернулась к нормальной жизни.',5,1,'2026-03-23 12:23:00'),
('ff83224a-51d2-4807-add0-6eb657f001d9','elena-golunova','Наталья, 50','','Земля буквально ушла из-под ног, когда моя пятнадцатилетняя дочь не вернулась домой после школы. Телефон был недоступен, лучшие друзья ничего не знали и плакали вместе со мной. Полиция неохотно приняла заявление, но драгоценное время шло, а результатов поисков не было никаких. Я не могла ни есть, ни спать, просто сходила с ума от страшной неизвестности. В полиции уже аккуратно намекали на самое худшее. Моя родная сестра буквально силой заставила меня искать альтернативные пути и не сдаваться. Мы стали искать информацию, кто может помочь в таких бедах. Нашли официальный адрес и контакты Елены Валерьевны. Нам чудом повезло быстро попасть к ней на прием со срочной бедой. Я принесла свежую фотографию дочери. Елена посмотрела на нее, закрыла глаза и сразу уверенно сказала: \"Жива. Находится в казенном старом доме, совсем рядом вода\". Она детально описала местность и сказала, что девочка сбежала из-за скрытого конфликта в школе. Мы тут же передали информацию нашему следователю, и на следующий день дочь действительно нашли именно в том районе, на заброшенной лодочной станции. Эта сибирская ведьма просто спасла моего ребенка!',5,1,'2026-03-23 12:17:00'),
('ffcb323d-204c-4105-bd10-dd1e2ee4561f','elena-golunova','Денис, 31','','Хочу выразить огромную, искреннюю благодарность за то, что меня буквально вернули к нормальной жизни из полного мрака. Последние три года я мучился от жесточайших панических атак. Они накатывали внезапно: в метро, на работе, за рулем машины. Я не мог нормально дышать, сердце выпрыгивало из груди, темнело в глазах. Психотерапевты и тяжелые таблетки давали лишь временный, легкий эффект. Я постепенно стал затворником, боялся выйти на улицу. Моя девушка, видя мои ежедневные мучения, решила действовать сама. Она знала, что Елена Голунова помогла очень многим, так как мы вместе смотрели эфиры. Она нашла, где принимает специалист в Москве, и чудом смогла записать меня на ближайшее время. Я шел туда с огромным недоверием и долей иронии. Но колдунья даже не стала меня долго слушать, она сама мне всё рассказала. Оказалось, я случайно \"подцепил\" сущность на старом кладбище в Рязани, где мы гуляли с друзьями в юности. После ее вмешательства приступы как рукой сняло. Прошло уже восемь месяцев — ни одной панической атаки!',5,1,'2026-03-23 12:20:00');
